/* 平成27年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h27.committeeSessions.push(...[{"id":"h27-20151013-4","meetingId":"h27-c-settlement","date":"2015年10月13日","dateIso":"2015-10-13","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３２分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を174件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 ただいまから決算特別委員会を開会いたします。 それでは、平成２６年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 ただいまから決算特別委員会を開会いたします。 それでは、平成２６年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問","question":"おはようあります。よろしくお願いします。私からは、成果報告書の１６３ページの品川シェルター設置助成、関連をしまして、防災緑化助成の改定についてお伺いをします。品川シェルターから始めます。平成２０年度に区と区内の建築団体、日本大学理工学部が共同開発した耐震シェルターの助成内容と、実績の件数をお聞かせください。よろしくお願いします。","respondent":"鈴木建築課長","answer":"品川シェルターにつきましては、６５歳以上の高齢の方あるいは身体障害者がいる世帯、かつ、年間世帯所得が６００万円未満である世帯に対して、建物全体を耐震補強するのではなくて、昔から地震のときにトイレに逃げ込めというところがありますけれども。","voiceIndex":4,"id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問","question":"平成２６年度１件ということなのですけれども、今後増やしていくには、いわゆる品川区住宅耐震化促進協議会との連携を今まで以上に協議が必要かと思いますが、いかがでしょうか。もう１点なのですけれども、一般の建築業者でも行えるようマニュアル化したようですけれども、定期的に研修会とかは開催しているのでしょうか。お聞かせください。","respondent":"鈴木建築課長","answer":"区内の団体ですが、当初は開発に携わった１社の工務店のみがこの工事を請け負っていたのですけれども、その後、講習等を受けての登録制度を設けまして、十数社の区内工務店の方に登録いただいて。","voiceIndex":6,"id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問","question":"ぜひ高齢者を地震から守る方策、今後ともよろしくお願いいたします。関連をしまして、次に、防災緑化助成制度についてお伺いをします。東京都の総合危険度ランクが５の旗の台四丁目地区をモデル地区に、平成２５年１２月から助成制度を適用した内容と、現在までの助成件数、相談件数、改定の理由を教えてください。","respondent":"多並公園課長","answer":"これまで実績としては０件、相談としては５件ございました。今後もこの解消に向けてさらなる制度構築ということで、現在、１１月１日をめどに考えているところです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問","question":"今、相談件数が５件ということなのですけれども、旗の台四丁目の住民の方なのでしょうか。お聞かせください。","respondent":"多並公園課長","answer":"旗の台四丁目の方と、あとはやはりほかの地区の方がいらっしゃいまして、今回、対象地区ではないということで実績として上がらなかった、そういうところです。","voiceIndex":10,"id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問","question":"やはり旗の台四丁目も、旗台小学校の目の前に木密地域が密集しているところがあります。ここは助成制度をするというと、隣地が密接している状況なので、旗の台四丁目に限って言いますと、そういったところを今後どういうふうに展開していくのでしょうか。お聞かせください。","respondent":"多並公園課長","answer":"その際、地元に回りまして、町会に回りながら、地域に応じた状況をお聞きして、今ある本当に危険なブロック塀からどのような形でできるかということをいろいろお聞きしながら、丁寧な対応をしながら、より防災性の向上を図ってまいりたいと考えているところです。","voiceIndex":12,"id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"私からは、１６２ページの耐震診断助成、１６３ページ、耐震化アドバイザー派遣委託、そしてまた、シェルターの設置助成について、そして時間がありましたら、１５５ページの八潮団地内区道歩道拡幅整備工事費についてお伺いいたします。個人宅への派遣も可能なのかということをお伺いしたいと思います。","respondent":"鈴木建築課長","answer":"こちらの実績が上がっていかない要因ですが、やはりこれもいかにＰＲをしていくかということが非常に大事かと思いますけれども、特にマンションにつきましては、区分所有で合意を得ていくというところが非常に課題として大きいというふうに認識しています。","voiceIndex":16,"id":"exchange-006"},{"speaker":"新妻委員","kind":"質問","question":"今年度は１件ということで、かなり少ない実績かと思われます。今までこういう実績があるのか、また、現在、６５歳以上の高齢者の方が対象でありますけれども、少しこの要件を緩和して、６０歳以上、または収入に応じても少し緩和をするなど、周知をし、また実績をつくることが、知ってもらうことが必要かと思いますが、ここら辺はいかがでしょうか。","respondent":"鈴木建築課長","answer":"要綱の、今、６５歳以上、６００万円未満ですが、こちらの要件の引き下げについてですが、耐震事業を行っている中で一番感じるところは、ご高齢のみの世帯の方が、「費用がかかる」、「引っ越しが面倒だ」、あるいは、「そのことを考える自体がなかなか踏み出せない」。","voiceIndex":18,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"さらなる周知の徹底をお願いしたいと思います。八潮団地内の歩道拡張工事ですが、予定どおり、第１期が終了いたしまして、今この拡張されたところは区民の皆さまに大変喜んでいただいております。今後、第４期まで全地域を歩道拡張になりますけれども、具体的に今後、八潮団地内で新たに横断歩道がつけられるところがありましたら教えていただきたいと思います。","respondent":"稲田道路課長","answer":"昨年度、第１期区間におきましては、地域の方の要望等を精査しながら、横断歩道を１カ所設置したところです。ただ、以降につきましては、現在のところ、横断歩道を設置する予定は今のところはありません。","voiceIndex":20,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"現在つくられました横断歩道のところ、保育園と学校を結ぶ横断歩道ですが、横断歩道だけでは怖くて渡れないという声があります。ぜひ品川区からも信号の設置を要望していただきたいのと、今後、横断歩道がつくられる場合には、信号機と合わせての設置を要望させていただいて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１６０ページの武蔵小山駅周辺地区の再開発問題、あと、１５８ページ、放射２号線道路沿道まちづくりについてお伺いをいたします。武蔵小山のパルム駅前地区再開発事業の説明会のお知らせが、２Ｈの範囲に配られました。総事業費、補助金の総額も教えてください。もう１点ですが、飲食店街がかなり閉店をしています。借家の方々の状況をつかんでいるのでしたら、その辺も教えていただきたいと思います。","respondent":"溝口都市開発課長","answer":"今回、権利変換計画、再開発法に基づく事業を進めておりますので、決して強引に権利者を追い出すという形ではなく、権利者の意向を聞きながら手続が進められているというふうに認識しているものです。","voiceIndex":24,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"借家人の方々はかなり厳しい状況にいらっしゃるので、その辺もつかんでいたらお伺いしたいと思います。元気に営業していた商店を追い出して、駅前にタワーマンションをつくる、そしてパルム商店街は今後どうなるのでしょうか。新しい床に新しい事業者を呼び込めば、商店街は栄えるのでしょうか、巨大マンションをつくれば、人が集まってにぎわいができるのでしょうか、この点も伺います。","respondent":"溝口都市開発課長","answer":"パルム商店街についてですが、今回、再開発ビルを建てて、ただ住宅のビルを建てるだけではなくて、店舗を３階まで三層の店舗を入れる予定になっております。","voiceIndex":26,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２棟目、３棟目、４棟目といったところで増えていくことによってフロアがどんどん増えているのですけれども、私は商店街というのは、そこで働いていらっしゃる皆さま、そしてそこに住んでいらっしゃる皆さまが、どういうものを、どういうまちを、どういう品物を求めているのかというところで、やはり希望に合った必要なものを十分そろえていただく、このことが何よりも大事であって。","respondent":"溝口都市開発課長","answer":"区といたしましては、そういった地元の意向をしっかり見て、必要な支援、または指導、そういったものを行いながら、武蔵小山駅周辺のよりよいまちづくりに寄与していきたいというふうに考えているものです。","voiceIndex":28,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川の宝物と言われている商店街、ぜひ本当に守り尽くしていただきたいと思います。ゼネコンの仕事をどんどんつくる、もうけさせる、このための再開発は自治体の仕事ではないと思いますが、いかがでしょうか。品川区中でも求められています。区が公園をつくるとか、また、住宅や商店街の耐震補強と建替え支援の拡大こそ最優先に進めるべきと思いますが、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"ですから、一概にゼネコンのため、または権利者のためだけでなく、再開発地域周辺の人たちにも喜ばれるようなまちづくりを目指して、これまでも再開発事業を進めておりますし、これからも再開発事業についてはしっかり応援、支援していきたいというふうに考えているものです。","voiceIndex":30,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"補助金の総額を聞き漏らしたのでしょうか。メモがないのでもう一度お願いします。次に、放射２号線のところに移りますが、星薬科大学が都知事に対して陳情書を提出しています。教育環境が悪化し、大学として機能が著しく損なわれる。大学を将来にわたって守り続けていきたいと見直しを求めています。都への陳情ですけれども、区もこの点を重く受けとめるべきと思いますが、いかがでしょうか。","respondent":"溝口都市開発課長、中村都市計画課長","answer":"済みません、武蔵小山のパルム地区の総事業費と補助金額です。総事業費としましては、先ほど答弁申しましたように約４５０億円、補助金額につきましては、約７０億円が補助金という形で入っているものです。放射２号、星薬科大学ですけれども、この星薬科大学、学校としての歴史が非常に深いということで、これは事業を進める東京都も十分認識をしておりまして、今、星薬科大学と交渉の中で。","voiceIndex":32,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"補助金総額が７０億円と前回よりも上がっているので、本当にこういった税金のむだ遣いはやめていただきたいと思います。私はぜひ地域の声、大学の声を聞いて、この計画の撤回を東京都に対して求めるべきと思いますが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"大学の教育機関としての役割も大切ですけれども、また、都市計画道路の機能そのものも大事ですので、これからも進めてまいります。","voiceIndex":35,"id":"exchange-015"},{"speaker":"松永委員","kind":"質問","question":"私からは、成果報告書の１５３ページ、駅周辺等放置自転車対策事業について、１５６ページのオリンピック・パラリンピック施設周辺無電柱化事業について、１５３ページの交通安全啓発費について、時間がありましたら、１５８ページの治水対策費について伺いたいと思います。成果報告書の１５３ページの駅周辺等放置自転車対策事業について伺います。駅名もよろしくお願いいたします。","respondent":"田口交通安全担当課長","answer":"大崎広小路駅、北品川駅、そして大森海岸駅、以上の３カ所です。対策としましては、比較的この駅周辺は放置自転車が少ないということはありますが、個別に放置自転車の対策をとっていただきたいというご連絡を受けますので、その場合、個別に対応しています。","voiceIndex":38,"id":"exchange-016"},{"speaker":"松永委員","kind":"質問","question":"ぜひよろしくお願いいたします。そこで、区では放置自転車の統計をとっていると思われますが、どのような方法でそうした統計をとっているのか、内容について伺います。駅周辺の公園やコインパーキングの片隅に自転車を置いて通勤通学する人の状況等、把握されていますか。あわせて伺いたいと思います。","respondent":"田口交通安全担当課長","answer":"その場合の対応といたしまして、撤去活動の際にその場所に立ち寄っていただいて、警告札をつけていただく。ひどい状況の場合は、看板を設置したり、セーフティーコーンを置いて対応しています。","voiceIndex":40,"id":"exchange-017"},{"speaker":"松永委員","kind":"質問・要望","question":"そうした中で、最近ですが、地域の方より伺った話ですが、自転車を放置している人を見受けたときに、「ここはだめだよ」ということで注意を促したのですが、無視をしてそのまま通勤されたということだったのですけれども、今後そうした中で何回か注意していくに当たって、もしかしたらトラブルになる可能性が出てくるのではないかと私は思うのですけれども。","respondent":"田口交通安全担当課長","answer":"現在もそういった場所につきましては、警備員だとか、シルバー人材センターからの派遣になっている方、そういった方を利用しておりますが、ただ、やはり全ての場所にというわけにはいきませんので、その辺も今後、検討課題とします。","voiceIndex":42,"id":"exchange-018"},{"speaker":"松永委員","kind":"質問・要望","question":"最近そうした中で、自転車駐輪場について、なかなか定期がとれないという声が上がっております。そこで、一時利用者と定期利用者の割合について、何対何なのか、もしわかりましたら教えていただきたいと思います。例えば定期をとりやすくするための対策等はとられているのか、あわせて伺いたいと思います。","respondent":"田口交通安全担当課長","answer":"それにつきましては、近くの駐輪場の案内、また、立体でございましたら、１階、２階は比較的キャンセル待ちが多いのですが、例えば３階とかになりますとキャンセル待ちが少ないという状況がありますので、その場合は、とりあえず一旦３階のほうをご利用していただきまして。","voiceIndex":44,"id":"exchange-019"},{"speaker":"松永委員","kind":"質問","question":"関連いたしまして、自転車等の保管、返還について伺いたいと思います。そこで、撤去作業と保管場所の方について少し伺いたいと思います。これら撤去された自転車、バイクについて、リサイクルと処分とありますけれども、その内容について伺いたいと思います。そのリサイクル、処分された自転車、バイクは、その後どのようになっているのか流れを教えてください。","respondent":"田口交通安全担当課長","answer":"それと処分です。こちらにつきましては、契約業者のほうに売却をしているという状況です。自転車につきましては毎月、バイクは年に４回実施しています。","voiceIndex":50,"id":"exchange-020"},{"speaker":"松永委員","kind":"質問","question":"そうした中で、ニュースでよく高級自転車盗難事件が多発しているということをお聞きしたのですけれども、そうした中で、盗難被害者は、まず警察に届出を出されると思います。一方、盗難事件の中には、実際には自転車が放置自転車とみなされて撤去されてしまった例は今までにあるのでしょうか。そうした中で警察との連携はどのようにとられているのかあわせて伺います。","respondent":"田口交通安全担当課長","answer":"トラブルで多いのが、返還業務の際に酔っぱらって自転車を引き取りに来てトラブルになるというケースがありますが、それ以外は大きなトラブルはございません。そうした場合で、もし対応できないような状況であれば、警察のほうには連絡するということで指導をしています。","voiceIndex":52,"id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"最後に、放置自転車が多い地区については、今後、駐輪場の整備、建設等の対策はとられていくと思いますが、２０２０年のオリンピック・パラリンピックを控えて、区の整備目標について最後に伺いたいと思います。","respondent":"田口交通安全担当課長","answer":"その結果を踏まえて、今後の駐輪場の整備、また、放置対策として何をやっていくか、こういったところを検討しています。この結果をもって今後の計画に反映させていきたいと考えています。","voiceIndex":54,"id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"これからも住みやすい環境に配慮したまちづくりをよろしくお願いいたします。次に、１５６ページのオリンピック・パラリンピック施設周辺無電柱化事業について伺いたいと思います。不法投棄対策として、防犯カメラが設置されておりますが、その設置状況について、また、成果について伺いたいと思います。","respondent":"稲田道路課長","answer":"大井埠頭中央海浜公園、競技場周辺の無電柱化です。競技場周辺の区道の電線類を地中化していくところですが、まず街路灯につきましては、地中化を実施するに当たりまして、道路復旧もあわせて行ってまいります。","voiceIndex":56,"id":"exchange-023"},{"speaker":"松永委員","kind":"質問","question":"今後も多くの方が利用されると予想されますので、犯罪等の少ない安全安心なまちにしていただければと思います。次に、交通安全啓発費についてです。私も実際に通ったらそんな感じになっておりましたけれども、今後、そうした方の注意の呼びかけ、対策などありましたら伺いたいと思います。","respondent":"田口交通安全担当課長","answer":"駐車につきましては、各所でも駐車の重点路線ということで指定して駐車対策を行ってありますが、今後、オリンピック・パラリンピックに向けて、今まで指定した場所と違う場所の放置駐車も懸念されますので、警察と連携を図りながら対策を講じてまいりたいと考えています。","voiceIndex":58,"id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"私からは、１５８ページの都市計画費全般で、品川区の羽田空港の機能強化に関する対応について、１６２ページの不燃化１０年プロジェクトで、木密地域対策について、１６０ページの用地取得費でヘリポート機能を持つ防災拠点について、１５８ページの水辺利活用事業で、災害時の物資運搬について、時間があれば１５９ページの公園新設改良費で、公園への民間レストラン。","respondent":"三ツ橋環境課長","answer":"第二種区域につきましては、６時から８時につきましては４５デシベル、８時から１９時につきましては５０デシベル、１９時から翌６時につきましては４５デシベルです。","voiceIndex":61,"id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"１９時までの基準値で十分でした。大丈夫です。単純比較すれば、環境確保条例の指定基準値を大きく超えるということです。では、これは１日平均の数値にされてしまうのですが、環境基本法に基づく航空機騒音に係る環境基準の住宅用地域である類型地の基準値は幾つでしょうか。これも簡潔にお願い申し上げます。","respondent":"三ツ橋環境課長","answer":"住宅地域におけます基準値ですけれども、そちらにつきましては７５デシベルです。","voiceIndex":63,"id":"exchange-026"},{"speaker":"筒井委員","kind":"質問・要望","question":"そこで質問ですが、品川区もホームページで国への改善要望を求めておりますが、私が以上述べた問題点および区として考えている問題点を踏まえ、今回の新飛行ルート案についてどのようにお考えでしょうか。新飛行ルート案では、この品川区役所の上空も８０デシベルの騒音で飛ぶことになるのですが、区の業務、区議会等、公務上、支障は出ないのでしょうか。それぞれご見解をお聞かせください。","respondent":"中村都市計画課長","answer":"この中でさまざまな意見が出る中で、これを今度、国としましては、その出ました意見を取りまとめて次の今後の方策に生かしていくですので、区としては、まず地域の皆様方に対する丁寧な説明を行っていただいている段階というふうに認識しております。","voiceIndex":65,"id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"特にブラインドサッカーはボールの音と味方の声の指示が大事で、プレー中は観客も静かに見ることが求められる競技です。この競技への影響は、特にブラインドサッカーについて、本当に８０デシベルの音を出し競技場の上を通るということは、本当に視覚障害者に対して愚弄する行為だと思うのですけれども、国土交通省と東京都とブラインドサッカー協会は、この問題を把握しているのでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そうした判断のもと、最終的にパラリンピックの競技会場が決定されていくものだというふうに認識しております。","voiceIndex":69,"id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"せっかく招致して、もしかしたら来ないという可能性もあるかと思われますけれども、非常に憂慮することだと考えています。公営ギャンブルの性質上、レースの安定性が求められると思いますが、航空機騒音で馬に悪影響が出てレースが不安定になるのではないか。レース不安定で来場者数が減り、競馬組合配分金の収入も減るのではないかと大変憂慮しておりますが、区のご見解をお願い申し上げます。","respondent":"中村都市計画課長","answer":"大井競馬場としましても、これは国ではその辺についても当然認識を持っておりまして、今後また検討していくというふうに思われます。レースに対する影響も、これも他の都道府県の競馬場の例を踏まえて、今後、国がその辺の対応策もまた出してくるというふうに考えております。","voiceIndex":71,"id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"フェーズ１の説明会を早々に終了したことからもこれがうかがえます。区、区長に、ぜひともこの問題を頑張って対処していただきたいと考えております。国土交通省は、私が質問したところ、撤回の余地があるとも言っておりますから、以上述べたような問題点をしっかりと指摘をしていただいて、撤回できるならば白紙撤回に戻すよう、ぜひとも主張していただきたいと考えておりますが、ご見解を伺います。","respondent":"中村都市計画課長","answer":"区としましては、今回の羽田空港、首都圏空港の機能強化につきましては、まだ現時点では、地域の皆様方に十分丁寧な説明を国から行っていただいて、まずは機能強化が、新飛行経路がどのようなものなのか。","voiceIndex":73,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"説明会の存在およびこの新飛行ルート案自体を知らない区民がたくさんいらっしゃるので、これも国の責任で新聞折り込み等、積極的な広報をするように区からもしっかりと求めていただきたいと考えております。時間の都合上、次の第２点目、木密地域対策についてお伺いいたします。除却などがやむを得ず間に合わない場合の区の対策はどのようになっているでしょうか。","respondent":"寺嶋木密整備推進課長","answer":"ご指摘のとおり、いつ地震が来るかもわかりませんので、区としましては、個々の住宅の不燃化だけではなく、防災広場の整備、広域避難所のバリアフリー化、広域避難所に至る道路の整備、それから消防自動車のホースが届かないエリアの解消等々を行っているほか。","voiceIndex":75,"id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"今後ともよろしくお願い申し上げます。最後ですけれども、東京都駒沢オリンピック公園の民間レストラン・カフェの事業者を品川区の業者に決定しましたけれども、区での公園への民間レストラン・カフェの導入検討調査研究はするのでしょうか、お伺いいたします。","respondent":"多並公園課長","answer":"これは東京都の大きな公園の中でカフェの設置ということで行っているところでありますので、品川区の場合は、そこら辺の状況を踏まえながら、現在一番大きい区民公園ではレストハウスという形でありますし、今後については。","voiceIndex":77,"id":"exchange-032"},{"speaker":"吉田委員","kind":"質問","question":"可動式ホーム柵助成についてです。可動式ホーム柵は、基本的には事業者が設置すべきものだと思いますが、区民にとってもぜひ必要なものであり、区が助成をすることで、その事業者の事業を推進するということで理解しておりますが、まず、この理解でよろしいかどうか伺いたいと思います。","respondent":"中村都市計画課長","answer":"国あるいは区、都の補助があるです。","voiceIndex":80,"id":"exchange-033"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。これも同様の考え方によるものと理解してご質問いたしますが、実績として、２０１０年から京急、東急、りんかい高速鉄道、ＪＲの各社の駅へそれぞれの事業ついての助成が行われています。どこの鉄道のどの駅にどういう順番で助成をしていくのか、そういう計画とか基準があるのだと思いますが、それについて伺いたいと思います。","respondent":"中村都市計画課長","answer":"今後につきましては、これは区としては引き続き働きかけを事業者に対して行っていくということ。それから、設置の計画につきましては、これはそれぞれの事業者が負担をするというところがありますので、また１カ所当たり数億円単位の費用がかかります。","voiceIndex":82,"id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"そうしますと、事業者のほうから助成の申請というか、そういうものが出てきたところについて、申請を受けてやっていくということで、品川区としては特にどういうふうに設置助成していくという計画はないということでしょうか。","respondent":"中村都市計画課長","answer":"鉄道駅にホーム柵を設置する場合に、具体的にはその駅の構造ですとか、こういったもので実現が難しいところとそうでないところがあります。","voiceIndex":84,"id":"exchange-035"},{"speaker":"吉田委員","kind":"質問","question":"なので、ある程度、どこへどう働きかけるかについても、ぜひ区のほうでも少し計画を持っていただけたらいいのではないかと思うのですが、その辺についてはいかがでしょうか。","respondent":"中村都市計画課長","answer":"これもバリアフリーの協議会を通して鉄道事業者に協力を働きかけて、ホーム柵についてこれから実現するであろうという予定ですけれども、こういった協議会等を通して、鉄道事業者に対して駅の安全対策について計画を立てていただくように働きかけをしたのがこの大井町です。","voiceIndex":86,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"今も申しましたとおり、やはりこれは本当に人によっては命にかかわることになりますので、ぜひ区としてもある程度の計画性を持って進めていただきたいと、これは要望でとどめておきます。それが目黒川を越えたあたりで工事がとまっているように見えます。近所にお住まいの方からどうなっているのかというお声が私に届けられました。どういう状況なのか教えていただけますか。","respondent":"溝口都市開発課長","answer":"今後につきましては、その先、大崎ニュー・シティの敷地の中に接続し、通すのが一番という形になっておりますが、まだ大崎ニュー・シティの権利者の方からの合意をいただけない状況にありますので、一旦は、仮設ではありますが、区道上に階段を落として。","voiceIndex":88,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。基本的には再開発事業組合の事業であるということで理解はしますが、区も再開発事業組合の中に地権者として参加しています。それから、今のお話だと大崎ニュー・シティの側と合意が得られないということですが、その大崎ニュー・シティとの話し合いの落としどころというのでしょうか、そういうようなものは何か今の段階で考えていらっしゃればお聞かせください。","respondent":"溝口都市開発課長","answer":"これまでもさまざまな提案をしながら協議を進めてきているところではありますが、まだ大崎ニュー・シティの方のご理解がいただけていない現状ですので、早期に、できるだけ早い時期にお互い合意のもと、目黒川デッキが完成するように。","voiceIndex":90,"id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"最後に、区民住宅費から、滞納使用料の納付促進について伺いたいと思います。滞納使用料等納付促進委託費について、当初歳出予算見積書を見ました。借上型区民住宅の滞納使用料等納付促進委託費予算は６３万６,０００円、建設型のほうが２９万４,０００円で、この予算額を算出する数式の意味がわからないので、最終的な決算額の意味を伺いたいのですが、前段として予算の考え方を教えてください。","respondent":"矢木住宅担当課長","answer":"予算額の考え方ですが、こちらは年度当初に指定いたしました滞納使用料、今年度につきましてはこの金額を回収しようという目標のもとに設定する金額です。","voiceIndex":92,"id":"exchange-039"},{"speaker":"吉田委員","kind":"質問","question":"金額はわかるのですが、その趣旨、そこまではわかるのですけれども、数式がありますよね、この予算額を算出する数式が。この数式の意味がわからないで、この決算額の意味を伺っても理解できないと思って伺ったのですが、難しいですか、簡単に教えていただければと思うのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-040"},{"speaker":"吉田委員","kind":"質問","question":"わかりましたというか、ちょっと私には難しいのですけれども、要するに、これだけを見込んで、この決算の差があるのですけれども、それは例えば、滞納を少なく済ますことができたのか、それとも回収ができなかったという意味でしょうか。この決算額はどういうふうに読み取ったらいいのか伺いたいと思います。","respondent":"矢木住宅担当課長","answer":"決算額の意味ですが、こちらは回収金額に先ほど申し上げた４割インセンティブを掛けて事務費を計上したものです。","voiceIndex":97,"id":"exchange-041"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。基本的に退去をされたところで滞納というふうになるのでしょうか。その辺のことも含めて、この予算の立て方と決算の額がよくわからなかったので伺いました。そこでの納付促進というのが、具体的にどういう形でやられていて、本来、基本的に収入のある方たちに払っていただけるようにしていくものになっているのかどうか、その辺のことが伺いたくて質問いたしました。","respondent":"矢木住宅担当課長","answer":"納付促進のやり方ですが、先ほど申し上げたとおり、文書を発送したりですとか、電話、訪問等を行って回収しているものですが、基本的に収入がある方、区民住宅は中間ファミリー層をターゲットとした住宅ですが、こちらは例えば収入の減少ですとか、退職、その他。","voiceIndex":99,"id":"exchange-042"},{"speaker":"吉田委員","kind":"質問","question":"そうすると、具体的に文書を送られたりとか、いわゆる督促をされているということだと思うのですけれども、例えば状況を聞き取って払っていただくためにはどうしたらいいかとか、そういうところまでは踏み込んではいないということでしょうか。","respondent":"矢木住宅担当課長","answer":"滞納者の生活状況の把握ですが、こちらにつきましても、可能な限り、電話、訪問等で生活状況を把握いたしまして、その生活状況に合った形で分納誓約等をいただいているところです。","voiceIndex":101,"id":"exchange-043"},{"speaker":"吉田委員","kind":"質問","question":"この委員会のところでも、部署間の連携ということが幾つか出てきたかと思うのですけれども、このことはまさに住宅の担当と、生活困窮者向け相談、それから、家計簿診断というところまで具体的な連携がイメージできることではないかと思うのですけれども、その辺について、こちらから働きかけるというか、そういうことを今後構想するという可能性はないのでしょうか。伺いたいと思います。","respondent":"矢木住宅担当課長","answer":"部署間の連携ですが、私ども、日々生活相談等々で滞納のご相談をいただく中で、やはりこれは非常に生活保護レベルだというような場合もありますので、そういう場合は現時点での生活福祉課への連携等は進めておりますし、今後ともそのように対応していくつもりです。","voiceIndex":103,"id":"exchange-044"},{"speaker":"横山委員","kind":"質問","question":"私からは、１５９ページ、しながわ水族館運営費と、もし時間がありましたら、１５８ページ、治水対策費についてお伺いをいたします。しながわ水族館運営費についてです。ほかの水族館と比較をしまして、しながわ水族館の特色と入館者の年齢層を区はどのように捉えておられますでしょうか。これまで実施してきた企画の内容と、その効果をお知らせください。","respondent":"多並公園課長","answer":"この中の何回かアンケート調査しているところでありますけれども、やはりファミリー層の方が非常に多い水族館ということで、ほかの最近オープンしましたエプソン品川ですとか、いろいろな施設の中ではファミリー層をターゲットにする施設だと認識しています。","voiceIndex":106,"id":"exchange-045"},{"speaker":"横山委員","kind":"質問・要望","question":"館長、飼育係、ダイバーのさらなるアイデアや創意工夫で、生き物が自然に泳いだり、動いたり、生きる本来の魅力を間近に見られるように、また同時に、飼育技術、生き物の保護や繁殖を通じた種の保存、調査研究、子どもから大人までの学習の場として、その実績や成果を館内でＰＲすることはもちろん、区内外への発信等もしていただきたいと思いますが、いかがでしょうか。","respondent":"多並公園課長","answer":"今のようないろいろな媒体を使いながらやっているところなのですけれども、最近、フェイスブックも始めまして、そこの中で結構映像も使ったものを職員の方がご自分でつくってアップしているところもありますので、そういうものも見ていただくようなＰＲの方法で。","voiceIndex":108,"id":"exchange-046"},{"speaker":"横山委員","kind":"質問・要望","question":"平成２６年度の執行率が５２.４％なのですけれども、こちらの理由をご説明いただきたいと思います。そして、しながわ水族館の今後の展望についてなのですが、羽田空港から一番近い水族館として、大田区や羽田空港との連携強化の方策、また、開館２５周年に向けての運営について、区の考えをお聞かせください。","respondent":"多並公園課長","answer":"先ほどの執行率の点ですが、主な原因としましては、もともともう少し入館者が少ないと見込んでいたところ、多くの方のご利用いただいて、約４％ほどの入館者のアップだったということで、それでサンシャインとの契約の中で、入館者が減ると区の負担金が減るということで。","voiceIndex":110,"id":"exchange-047"},{"speaker":"横山委員","kind":"質問","question":"多言語化について、今、デジタルサイネージの導入というところでお話があったのですけれども、空港等ではＱＲコードからアクセスするという方法などもとっていらっしゃいます。水族館は照明がちょっと暗くなりますので、そういった課題もあるかと思うのですけれども、詳しくお聞かせいただけますでしょうか。","respondent":"多並公園課長","answer":"今年度、企画しておりますのがビーコンで、そこの現場に行きますと、日本語で表示されている水槽の表示を、スマートフォンでソフトをダウンロードしていただいた方がその近くに行くと、登録されている言語でそこに説明表示が出てくるという表示を考えているところで、今年度。","voiceIndex":112,"id":"exchange-048"},{"speaker":"横山委員","kind":"質問","question":"デジタルサイネージのほうも、暗さの対応もしていただいて、今後ともスムーズに進めていただけたらと考えています。治水対策費のほうをお伺いいたします。浸水ハザードマップをいただいたのですけれども、浸水したときの水深が大きくなる地域において、備蓄倉庫の高さ、位置なのですけれども、その現状をお聞かせください。","respondent":"鈴木防災課長","answer":"浸水ハザードマップの中にある浸水エリアの備蓄倉庫ですが、基本的に備蓄倉庫につきましては、海抜、標高等を配慮して設置をしていなかったですが、そこ自体は堅牢な建物、また、場合によっては建物の２階、３階が倉庫になっていますので。","voiceIndex":114,"id":"exchange-049"},{"speaker":"横山委員","kind":"質問・要望","question":"備蓄倉庫は、すぐ使えなくなることはないというご説明をいただきました。ちょうどその位置に倉庫が幾つか置いてあるのですけれども、１ｍ、２ｍというふうになってしまった場合に、倉庫が使えなくなってしまうのかというふうに懸念しておりますけれども、町会への周知ですとか、そういったところはどのように行っておりますでしょうか。","respondent":"鈴木防災課長","answer":"町会の備蓄倉庫を公園等に置く場合、町会のほうからの場所の希望を中心に公園のほうの支障がない範囲で置かせていただいていますので、現時点では、標高等についてのお話し合いや情報提供は行っていないというのが現状です。","voiceIndex":116,"id":"exchange-050"},{"speaker":"つる委員","kind":"質問","question":"お願いします。１５３ページ、駅周辺等放置自転車対策事業、１５９ページ、公園管理費、１５４ページ、街路樹等維持管理費について伺っていきたいと思います。駅周辺であります。放置防止指導啓発について、まず平成２６年度、どのような啓発を行ったか、簡単で結構ですので教えてください。","respondent":"田口交通安全担当課長","answer":"指導、啓発につきましては、警備員の配置、またシルバー員の配置、それと鉄道事業者、また商店街等との合同のキャンペーンを行っております。","voiceIndex":119,"id":"exchange-051"},{"speaker":"つる委員","kind":"質問","question":"今、簡潔に答えていただいてありがとうあります。人員配置、ハード面というか、啓発の中で、人ではなくて、ハードの部分で何か啓発をしていただいていることがあるかと思うのですが、そのあたり、あれば教えてください。","respondent":"田口交通安全担当課長","answer":"指導、啓発の部分につきましては、ハードというのは特にございません。先ほどもお話ししたように、例えば看板の設置、また、カラーコーンの設置、こういったもので対応しているものです。","voiceIndex":121,"id":"exchange-052"},{"speaker":"つる委員","kind":"提案","question":"もっと言うと、利用者がしっかりと意識を持ってといいましょうか、正しい使い方をしていただくというのが一番でありますけれども、大阪市の事例を挙げて何度も提案させていただいている子どもに描いていただいた駐車禁止の絵を路面シートに貼る、これは大阪市が天神橋の駅とか、そうしたところを私も現地を視察して一般質問でもさせていただいて。","respondent":"田口交通安全担当課長","answer":"ただ、法定外ということで、警視庁のほうでは難しいですが、委員ご指摘のとおり、子どもを使ったそういった施策は確かに効果があると思いますので、私どももいろいろ考えて、またできるものであれば、警察のほうと協議をさせていただきたいと思います。","voiceIndex":123,"id":"exchange-053"},{"speaker":"つる委員","kind":"質問","question":"教育委員会の方との連携とかもあると思いますので、そうしたことを広く含めてお願いしたいと思います。次に行きます。この質問も何度か伺っているのですが、今、品川区内の公園で、順次、複合遊具に変えていっているという流れがあるかと思います。これは公園を防災の観点なども含めて整備をしていくという視点もあると伺っておりますが、今現在、公園中、幾つがこの複合遊具になっているのか教えてください。","respondent":"多並公園課長","answer":"それが今の時代、古くなったときに利用の範囲を決定する安全基準がありまして、そのようなことをすると、なかなか全部が設置できない。","voiceIndex":125,"id":"exchange-054"},{"speaker":"つる委員","kind":"質問・要望","question":"次の質問を簡潔にお答えいただきたいのですが、これ、今、答えていただいた複合遊具のその下は、やわらかい素材のクッション素材も一緒になって整備されていると思うのですが、まだそうなっていない遊具の下、わりと基礎を固めるためにコンクリートで角が結構むき出しになっているところがある。これ、過去にもタイミングによってはあると思うのです。","respondent":"多並公園課長","answer":"今ご案内のありましたいわゆるゴムチップ舗装と言われているものですが、これにつきましては、その中でもやはり利用が多い場所を考えて、あとは地元の方のご要望、いろいろ勘案しまして、最近の例ですと、平塚公園を設置したときに下をゴムチップ舗装させていただいたり。","voiceIndex":127,"id":"exchange-055"},{"speaker":"つる委員","kind":"質問","question":"次に行きます。健康課のほうで、私の散歩道ということで散歩のさまざまないい場所を区民の方からいただいてまとめた１冊があると思いますが、区内、また区外の方が品川区を楽しんでいただく上で、水と緑の基本計画、また、行動計画に基づくという形になると思うのですが、区内で四季を通じて楽しむため、どのような樹木などがあるか、これは代表的なもので結構ですので教えてください。","respondent":"稲田道路課長","answer":"平成２７年４月１日現在では、総数４,００６本です。一番多いのは桜です。３３％ほどを占めております。常緑ですがクスノキ、それから珍しいというか、ケヤキが３％程度、ヤマモモ４％、ハナミズキが６％というぐらいで、このような形で約４,００６本の街路樹管理しております。","voiceIndex":129,"id":"exchange-056"},{"speaker":"つる委員","kind":"質問・要望","question":"多分この一、二年で２００本近く街路樹全体で増えたでしょうか。過去の議事録を見ると、桜の数を聞いたときに３,８００本の街路樹に対して１,３００本で３４％というご答弁をいただいていて、今、４,００６本ですから、２００本弱が増えてきたのかというふうに思います。緑豊かな品川を求めている者としては、嬉しいことなのですけれども。これも何度も申し上げております。","respondent":"稲田道路課長","answer":"駅前がどの範囲かと言われると、ちょっと私はこの場ではなかなか難しいところです。ちょっと今、わからない状況です。","voiceIndex":131,"id":"exchange-057"},{"speaker":"つる委員","kind":"質問・要望","question":"２００本は別に桜でなくても、個人的には桜が増えてほしいという思いで、品川区全体で緑が増えていくという部分では非常に喜ばしいことかと思います。そうした意味で、四季を通して楽しめる品川自慢、まさに品川音頭、品川自慢の花と緑、これが本当にあふれる品川区をこれからも皆さまでつくっていただきたい、このようにお願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-058"},{"speaker":"安藤委員","kind":"質問","question":"私からは、１６０ページ、目黒駅前地区再開発事業、そして１６１ページ、五反田駅周辺地区コーディネート業務委託、五反田のまちづくりについて伺います。この開発の最大地権者は、都バス車庫を所有していた東京都かと思いますが、東京都が確保する権利床はどこの建物に何m2確保され、それはどのように利用されるのか伺います。","respondent":"溝口都市開発課長","answer":"その業務棟の床を取得したものについて、今後どのように交通局のほうで活用していくかというのは、現在、交通局のほうで検討している最中だというふうに聞いておりますので、利用についてはまだ未定というふうに聞いているものです。","voiceIndex":136,"id":"exchange-059"},{"speaker":"安藤委員","kind":"質問","question":"確保する東京都の権利の床の平米数が漏れていたので、後でお伺いします。この東京都の所有する土地や床、こうしたものは都民の財産ですので、都営住宅ですとか、高齢者や障害者施設、認可保育園など、区民、都民のために活用するよう地元自治体としても強烈に強く働きかけるべきだと思いますが、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"そういった中で交通局としてどのような活用をしていくのか、今現在、検討中というふうに聞いておりますので、今後の推移等については十分確認しながら進めていきたいと思います。","voiceIndex":138,"id":"exchange-060"},{"speaker":"安藤委員","kind":"質問・要望","question":"税金投入して１１０億円、１万７,０００m2の床が確保されるということですけれども、今回、東京都、地方自治体がこうした収支にまさに座って再開発をするということです。ぜひやっていただきたいと思います。こちらについていかがでしょうか、伺います。続けて、五反田のまちづくりについて伺います。こちらはゆうぽうとも会員に入っておりますでしょうか。あわせてお答えください。","respondent":"溝口都市開発課長","answer":"その中には子育て支援施設、行政サービスコーナー、または在宅介護支援センター、備蓄倉庫等々のものが入るという形になっておりますので、改めて東京都の交通局が取得する床については、それは取得する側である交通局のほうで公営企業としてどのような運営をしていくのか。","voiceIndex":140,"id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"現状として、ゆうぽうとは入っていないということでしたが、昨年の４月の建設委員会で、この質問を我が党の委員がしたのですが、ゆうぽうとも入っているということでした。その後の活用は検討中といわれておりますが、現時点で３つのにぎわい拠点のうち１つがなくなってしまった現状ですけれども、ビジョンとの整合性はどうなるのでしょうか。ビジョンと矛盾が来さないのか伺います。","respondent":"溝口都市開発課長","answer":"地元の方たちも同様な思いがありますので、これまでも機会を捉え日本郵政に対して、引き続き、にぎわいに資する施設としていただくよう要望しておりますし、今後についても要望していきたいというふうに考えているものです。","voiceIndex":142,"id":"exchange-062"},{"speaker":"安藤委員","kind":"質問・要望","question":"ほかの２つのにぎわい拠点について伺いたいのですが、五反田駅ですけれども、駅ビルのリニューアル、いつも取り沙汰されていますが、一向に具体化しません。区は見通しをどう聞いているのか伺います。しかし、法制度上、やむを得ず、それ以上は１０年間としたのですという旨の説明でしたけれども、品川区は、概ね８年という、つまり、平成３２年９月で返還を求める考えがあるのかどうか伺います。","respondent":"溝口都市開発課長、柏原企画調整課長","answer":"にぎわい拠点の３つの拠点のうちの１つ、五反田駅についてです。今現在、ＪＲのほうでは、東口のほうに駅ビルを計画する計画があります。これが１０年間という最低期間がありますので、それを使ったです。概ね８年という考え方は変わっていないです。","voiceIndex":144,"id":"exchange-063"},{"speaker":"安藤委員","kind":"質問","question":"今のところですが、今年３月の予算特別委員会の中で、我が党の質問に対しても、このＴＯＣビルの本体の建替え計画について伺っておりますが、品川区は、「来年２０１６年８月から工事に着工する、解体に入るということで変わりはないと聞いております」との答弁でした。本体ビル建替えでどんなビルができ上がるのかということについても、やはり計画の中身について品川区がつかんでいるところを伺います。","respondent":"柏原企画調整課長","answer":"具体的な図面とか絵というところでは、まだ出ているところはございませんけれども、そういったところで内部でかなりの検討をしているというふうには聞いてあります。","voiceIndex":147,"id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"全くこの時点でもこうした計画が具体化もされていないということで、私はちょっとおかしいのではないかと、こういった計画はおかしいのではないかと思います。お伺いしたいのは、ＴＯＣビルの概ね８年、契約書類上は１０年という契約期間なのですが、建替えが進んでいないわけです。この契約期間を区としては更新または延長することも選択肢として考えているのか、そこら辺はいかがなのか伺います。","respondent":"柏原企画調整課長","answer":"先ほど申しましたように、ＴＯＣは、内部でいろいろな案を検討しているというふうに聞いてありますし、こちらのほうも現在のところで概ね８年というところで話を聞いているところです。","voiceIndex":149,"id":"exchange-065"},{"speaker":"安藤委員","kind":"質問・要望","question":"今は考えていないというところで非常にあやしいと思うのですけれども、私は、何がなんでもＴＯＣに協力する、そんな印象をやはり拭えません。都市部の貴重な土地を先の見えない、何かころころ延長の理由も変わっていく。具体化が進まない計画に差し出すというのはやめて、認可保育園、特養ホームなど、住民要望のために使うべきだと求めて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-066"},{"speaker":"沢田委員","kind":"意見","question":"よろしくお願いします。補助２８号線についてなのですけれども、特定整備路線の中でもそれなりに整備が進んできているかと思うのですけれども、２０２０年までの整備ということで進めているかと思うのですが、現状についてと、それから、今後の見通しについてまずお聞かせいただければと思います。","respondent":"中村都市計画課長","answer":"特定整備路線の補助２８号ですけれども、現在、地元の方に対する東京都からの説明会は全て完了しております。そして、今現在、土地をお譲りいただくための交渉に関して進めているですが、まだ、ただいまのところ、用地取得率については０％です。","voiceIndex":153,"id":"exchange-067"},{"speaker":"沢田委員","kind":"質問・要望","question":"今いらっしゃる方とあわせて、その後の話で、地域からはさまざまな声が上がっていますけれども、以前も質問させていただきましたけれども、あそこの三ツ又の歩道橋を撤去してくれとか、また、広くするならば歩道を広くしてほしいとか、また、アーケード撤去後の商店街の装飾灯の整備をしっかりやってほしいとか、バス停の部分だけ車道を広くしてというような、バス停のところの切り下げというのですが。","respondent":"中村都市計画課長","answer":"区といたしましても、都と連携をいたしまして、また、区民の声を東京都へしっかりと伝えて対応していただくように、これからも要望して、連携しながら進めてまいります。","voiceIndex":155,"id":"exchange-068"},{"speaker":"沢田委員","kind":"質問・要望","question":"都道でありますけれども、しっかりと区の地域の方々の要望をこの中にも盛り込んでいっていただきたいと思います。","respondent":"寺嶋木密整備推進課長","answer":"現況７.２ｍの幅員の道路を１０ｍに拡幅する事業ということで、進捗状況につきましては、今、件数で言いますと、平成２１年度から事業を開始しておりまして、１２軒の方のご同意をいただきまして用地の取得ができているところです。","voiceIndex":157,"id":"exchange-069"},{"speaker":"沢田委員","kind":"質問・要望","question":"なぜこの先がどちらも整備が、片方は南大井のほうにＪＲの高架を抜けるほうですけれども、片方は池上通りの大森に向かって、そちらが指定されていないのですけれども、その辺のところのお考えをお聞かせください。","respondent":"中村都市計画課長","answer":"この道路の整備に当たりまして避難の考え方ですけれども、こちらは、それぞれ目標をクリアしながら一歩一歩進めていくという観点から、まず特定整備路線を整備する、そして避難道路機能の強化を図る、その先も次の段階といたしまして、現在。","voiceIndex":159,"id":"exchange-070"},{"speaker":"沢田委員","kind":"意見","question":"避難道路強化、特に大井四丁目と大井六丁目の間の南大井に抜ける高架の通りですけれども、避難道路強化ということで、そういうふうに大井警察署までしかなっていないということですけれども、避難道路としては、あそこを左折して大井競馬場に抜けるというふうになっているのですけれども、この最短のルートは、まさにこの道路が最短の大井競馬場までの、広域避難所までのルートなわけで、この道路は。","respondent":"藤田都市環境部長","answer":"２８号線の南の区間につきましては、今、東京都と区であわせて検討しております第４次整備路線、こういったものの中でもきっちり評価をして、今後どうしていくかということを考えていくべきことかということで考えてあります。","voiceIndex":161,"id":"exchange-071"},{"speaker":"沢田委員","kind":"質問・要望","question":"ちょっと時間がないですけれども、道路維持費で、区界のところに関して、例えば大田区との境目のところの歩道とか車道とか、それから側溝とかの扱いというか、大田区と品川区の中でどういった話し合いとか関係で整備をされているのか教えてください。","respondent":"稲田道路課長","answer":"区界の道路に関しましては、区界が道路の中心であるというところで、別々に管理するわけにもいきませんので、協定を結んでどちらかの区が管理するというところで進めております。","voiceIndex":163,"id":"exchange-072"},{"speaker":"中塚委員","kind":"質問","question":"２８号線と３１号線にかかわって幾つか伺いたいと思います。初めに、２８号線の先ほどの答弁ですけれども、完成後もにぎわいは続くということですけれども、具体的にどのような姿を描いているのか伺いたいと思います。もちろん私は進めるべきではないと思っていますけれども、いかがでしょうか。","respondent":"中村都市計画課長","answer":"補助２８号線につきましては、これはこの拡幅後の道路の整備の内容につきましては、これは東京都がこれから考えていくということで、実際に拡幅に当たって、車道あるいは歩道がどの程度拡幅になるのか、こういったものもこれから東京都のほうで。","voiceIndex":166,"id":"exchange-073"},{"speaker":"中塚委員","kind":"質問","question":"拡幅後もにぎわいが続くと言いながら、そのための具体策が何もないというのは一体どういうことか改めて伺いたいと思います。商店街から上がっているのは、店の軒先が削られてしまったら、とても今の事業は続けることができないと、そういう話を私はたくさん伺っております。商店街のにぎわいのためにも、２８号線は計画をやめるべきだと思いますけれども、いかがでしょうか。","respondent":"寺嶋木密整備推進課長","answer":"そういった形で、今現在の状況を残せるように地域の方とお話を続けながら、どういった形を望まれるのか、どういうことが可能であるのか、こういったことを検討しながら進めていくということです。","voiceIndex":168,"id":"exchange-074"},{"speaker":"中塚委員","kind":"質問","question":"先ほど、にぎわいが続くと答弁したわけですから、その点を改めて伺いたいと思います。しかも、西から東、東から西に吹く風は１年間を通して僅かであり、北風ないし南風時には道路が四丁目から六丁目、隣に移ってしまうことが明らかになっているので、防災だという説明はもうやめるべきだと思いますが、いかがでしょうか。","respondent":"寺嶋木密整備推進課長","answer":"シミュレーションの結果は、それぞれの設定条件もあろうかと思いますが、いずれにしても防災上必要であるという点についてはかわりないというふうに認識しております。","voiceIndex":170,"id":"exchange-075"},{"speaker":"中塚委員","kind":"質問・要望","question":"大儀も道理も失った都市計画道路２８号線は直ちにやめるべきだと強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":172,"id":"exchange-076"},{"speaker":"西本委員","kind":"質問","question":"これが１つです。２つ目が、特定整備路線、沿道まちづくりになりますが、今も質問がありました。特に２８号線の商店街はお聞きしました。２９号線も含めて、商店街の動きはどういうふうになっていますでしょうか。これは今、何人に対してされているのか、この金額、補助金というのは、国、被災県のほうからあるのかないのか、今後の動向はどういう形になるのでしょうか。教えてください。","respondent":"鈴木防災課長、寺嶋木密整備推進課長、矢木住宅担当課長","answer":"区のほうでも研修や訓練の際にこの地図を活用いただいて、しっかりと正しい対応ができるように、区民の方にお知らせをしています。全く同じ形でのまちということではなくて、道路ができることによってまちの形は変わりますけれども。今後の動向ですが、宮城県は入居後６年間、福島県は平成２９年３月３１日までの入居期間となっております。","voiceIndex":174,"id":"exchange-077"},{"speaker":"西本委員","kind":"質問","question":"そこからどう読み取っていくか、自分たちの安全な避難場所はどこなのだろうかということをしっかりと自分のその場所の中でやっていかなければいけない。そうなると、当然ながらこの助成金も切られる可能性も当然あるわけですけれども、これをどういうふうな見立てをしているでしょうか。これを品川区としてはどういうふうな形で自立に向けてのサポートをしていこうとしているのかお聞きしたいと思います。","respondent":"鈴木防災課長、寺嶋木密整備推進課長、矢木住宅担当課長","answer":"ハザードマップの活用につきましては、ご指摘のありましたとおり、ただ地図を持っているだけではなく。そういう意味で、品川区としましては、特定整備路線の必要性を地元の方に引き続き訴えていきながら。現在、被災地の避難者の方に対する助成金ですが、国等の動きもございまして、今のところ、助成金がなくなった段階では。","voiceIndex":178,"id":"exchange-078"},{"speaker":"西本委員","kind":"質問・要望","question":"これ、なかなか被災地の方々に対する支援は難しいところがありますので、丁寧に自立に向けてお願いしたいと思います。そして、治水対策、水による災害ですけれども、地震においての避難行動というのは、災害が起きてから逃げるという事後の避難なのです。なので、事前に避難をしていく、そしてそれを自分の中で組み立てられる、そういう訓練をぜひ取り入れていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-079"},{"speaker":"木村委員","kind":"質問","question":"土木費の１５５ページの下から１０行目、道路バリアフリー事業からお伺いいたします。この事業は、主に高齢者、障害者の方々、またベビーカー等を対象に、現在ある段差や勾配、ブロック等を人に優しくする平成５年からの事業ですけれども、事業後の区民の反応や、また効果は、どのように出ているのか。そういう声が聞こえているのかどうかをお聞かせください。","respondent":"稲田道路課長","answer":"道路バリアフリー事業です。これは側溝の段差解消、ゼロ段差にする、それから、歩道の段差解消、２cm段差を基本として、ゼロ段差を一部設けていく。","voiceIndex":184,"id":"exchange-080"},{"speaker":"木村委員","kind":"質問","question":"効果があるということを聞きましたけれども、道路バリアフリーは区内に道路でもどのような順番でこの事業が進められているのか、この事業が始まったのでしょうか。歩道での問題箇所は、区民の皆さまからの情報がとても大事ではないかと思います。区民の皆さまからの情報が区役所に入った時点で、担当部署はどのように対処、行動をとるのかもお聞かせください。","respondent":"稲田道路課長","answer":"区民からの情報です。これは確かに毎年何件か上がってくるです。「あそこに段差があってつまずいてしまった」、「ちょっと歩きづらかった」というようなことが上がってきますので、その辺を現場を確認しながら、そのような段差解消等を実施しております。","voiceIndex":186,"id":"exchange-081"},{"speaker":"木村委員","kind":"質問","question":"この段差、横断歩道と歩道との段差、これをゼロ段差にということですけれども、これは品川区独自ともお聞きいたしました。品川区が一番先にやったということをお聞きしましたけれども、いかがでしょうか。高齢者になると、平坦な道でも爪先が引っかかることがしばしばあります。あるとすれば、次の事業に教訓としてそういうことを生かすことが大事だと考えていますけれども、その点はいかがでしょうか。","respondent":"稲田道路課長","answer":"アスファルトが剥がれてそこに足をつまずいたというような情報も入りますので、そういうときは、事前には巡回調査、そういうものをやってなるべくなくすようにはしていますけれども、もし発生した場合は、応急処置をし。","voiceIndex":188,"id":"exchange-082"},{"speaker":"木村委員","kind":"質問・要望","question":"ぜひ教訓として取り入れていただきたいと思います。これからいつ起きるかもわからないと言われている地震対策のためにも、絶対にこの道路は必要になると思いますし、道路整備の基本は、道路とはどうあるべきか、行政としては、道路とはこうあるべきだというお考えをお聞かせ願いたいと思います。拡幅する道路に対策としての新たな工夫などがあるかどうか、そういう点におきましてもお聞かせください。","respondent":"稲田道路課長","answer":"現状が１.５ｍという狭い歩道でございました。有効幅員で言えば１.２ｍぐらいしかございませんで、それを約２.３、約２ｍほどの有効幅員を設け、現在、バリアフリーを実施しています。区の道路としての考え方です。心構えというか、考え方。","voiceIndex":190,"id":"exchange-083"},{"speaker":"木村委員","kind":"質問","question":"道路の関連質問で、特定整備路線についてお聞きいたします。昭和２１年に戦災復興によってできた道路が区内にも多くあります。中延駅前で区民の皆さまからよくお話を聞くのですけれども、約８４０ｍですけれども、現在は６ｍ、これを１５ｍに拡幅する事業という話が持ち上がっておりますけれども、区として、特定整備路線になる可能性、この路線はどれぐらいあるとお考えでしょうか。お願いいたします。","respondent":"中村都市計画課長","answer":"補助３０号線につきましては、これも今後整備を進めていく将来的な予定はありますけれども、これもあわせて、東京都が優先整備事業として策定してまいります。","voiceIndex":192,"id":"exchange-084"},{"speaker":"塚本委員","kind":"質問","question":"私からは、１５３ページ、交通安全啓発費、それと余った時間で１５４ページ、雨水排水調査委託、この２つについてお伺いしたいと思います。初めに、交通安全啓発費のほうなのですが、毎年品川区は交通安全運動を実施しておりまして、この９月にも、９月２１日から３０日、秋の品川区交通安全運動実施ということで実施をされました。","respondent":"田口交通安全担当課長","answer":"自主返納のデータ的なものは手元にはございませんが、やはり自分で「ちょっと危ないな」、あと、周りの方から、「ちょっともう運転危ないんじゃないの」と言われた場合、そういった助言をいただいた場合は、やはり返納するということが、事故防止上。","voiceIndex":195,"id":"exchange-085"},{"speaker":"塚本委員","kind":"質問","question":"自主返納した方は、運転経歴証明書というものを発行されるということで、特にこういった運転経歴証明書を持つ高齢者に対して、他の自治体の例としては、これを推奨するために、タクシーやバスの運賃の割引あるいは商品券を贈るとか、場合によっては、レストランや商店での割引、こういったことで自主返納を勧めるというようなことをしている自治体もあるというふうになっているのですけれども。","respondent":"田口交通安全担当課長","answer":"以前、品川区のほうでも、運転免許の返納ということで支援制度を行ってございました。ただし、この事業は、平成２２年度末で終了していますが、今後また他区の状況等を踏まえながら、調査研究をしていきたいというように考えてあります。","voiceIndex":197,"id":"exchange-086"},{"speaker":"塚本委員","kind":"質問","question":"一般には、いわゆる公共交通の充実ということで、コミュニティバスであるとか、乗合タクシー、こういった公共交通のネットワークを再構築していかなくてはならない、こういったことにもつながっていくというふうに、セットで考えなければいけない問題ということでもあるかと思いますけれども、関連して、公共交通ということについてお伺いしたいのですが。","respondent":"中村都市計画課長","answer":"と申しますのは、皆さま、歩行が困難な方の度合いというのは、これはさまざまありますけれども、ただ、区としてのスタンスは、やはり全ての人に優しい、全ての人が快適に公道を歩くことができる、そういったところを目標に進めているところです。","voiceIndex":199,"id":"exchange-087"},{"speaker":"塚本委員","kind":"提案","question":"事業の対象者についても、いわゆる高齢者、障害者等、交通弱者ということにしっかりとフォーカスするというか、対象者を明確化して事業を展開していく、これも大変に大切であると、こういったことを安曇野市の方は強調されておりましたので、そういったことも１つの参考に、これを提案してやっていただきたい、こういうわけでございません。","respondent":"中村都市計画課長","answer":"品川区内公共交通の状況を見てみますと、やはり他区に比べて非常に充実はしておりますけれども、ただ、それで終わりということではなくて、常に交通事業者とともに研究を重ねて、よりよい住みやすいまちづくりのために、これからも研究をしていきたいと考えております。","voiceIndex":201,"id":"exchange-088"},{"speaker":"塚本委員","kind":"質問・要望","question":"よろしくお願いしたいと思います。では、続きまして、雨水排水調査委託なのですけれども、１５４ページです。この事業は一体どういうものか、ご説明をいただきたいと思います。","respondent":"稲田道路課長","answer":"雨水排水調査委託です。これは勝島一丁目雨水排水の調査委託を実施したものです。","voiceIndex":203,"id":"exchange-089"},{"speaker":"塚本委員","kind":"質問","question":"現状では、時間５０mmの雨に対応するという形で整備が進められていると思いますけれども、近年の豪雨の数字はそれをはるかに上回っていますので、そういった中で、当面といいますか、現状、対応できる対策をいま一度考えていかなくてはいけないときに来ているのではないかというような思いが今しているのですけれども、そういった水害につきまして。","respondent":"和田河川下水道課長","answer":"ただ、やはり浸水被害が多発している地区だとか、それから、谷地、坂下、こういうところにつきましては、その整備のスピードを待っていては、区民の生命、財産に影響があるということで、東京都下水道局としては。","voiceIndex":205,"id":"exchange-090"},{"speaker":"塚本委員","kind":"質問・要望","question":"今のはまさにインフラとして５０mm対応の整備はもちろん必要なことであるというか、早期に進めていただきたいと思うのですけれども、一方で、これは本当に難しい話だと思いますけれども、こちらの想定をはるかに上回る自然災害が起こり得るということがかなり身近に迫っている昨今の中で、特に防災面においてですけれども、現状以上にでき得る対応を考えていく。","respondent":"鈴木防災課長","answer":"想定外の、予想を超えるような大きな災害の対応ですが、昨年の１０月に土砂災害の避難勧告等の基準を区として定めました。","voiceIndex":207,"id":"exchange-091"},{"speaker":"塚本委員","kind":"質問・要望","question":"ただ、具体的にどうするのだという話になれば、なかなかそれは難しいところがあるというのは、私も思っているところであるのですけれども、本当にこの対応については、災害の備えとして、でき得る限りのことをして準備をして、備えていただくように一層の努力をお願いしたいというふうに思うところですので、要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":209,"id":"exchange-092"},{"speaker":"渡部委員","kind":"質問","question":"ですから、ここの審議会にかかって認められた後にさまざまな対策が行われていくのですが、この間、審議会はどれぐらい開催されて、どのような方々が審議会に入られていてというところ、そして、区長のほうからも進んでいるとすれば、何カ所か諮問が上がってきたのか、箇所数がわかれば。","respondent":"矢木住宅担当課長","answer":"何カ所か諮問をしたのかというご質問に対しましては、既に諮問を２カ所してございまして、２カ所ともそれぞれ管理不全状態にある空き家、いわゆる特定空き家１軒と、廃棄物に起因する管理不全状態にある空き地等といたしまして、いわゆるごみ屋敷１軒を諮問、答申しております。","voiceIndex":211,"id":"exchange-093"},{"speaker":"渡部委員","kind":"質問","question":"この条例の中でさまざまなことがあって、当然またそれが代執行をやるとか、公表するとなると、また次の段階だと思うのですが、これから認められたことによって話し合いがされたり、例えば、有効活用なのか、売却なのか、建替えなのかというような指導にも当たられていると思うのですが、どのような形で進められているのでしょうか。","respondent":"矢木住宅担当課長","answer":"今の進捗状況です。両方とも助言および指導ということで、指導の通知を発して、それぞれにコンタクトをとるように努めているところです。１軒につきましては、現在、行方不明中でございまして、今、探している最中です。","voiceIndex":213,"id":"exchange-094"},{"speaker":"渡部委員","kind":"質問・要望","question":"わかりました。この間、見に行ってきまして、北側ゾーン、少年野球場のほうなのですけれども、これはどのような形でこれから工事、計画等進んでいくか教えてください。","respondent":"多並公園課長","answer":"今のご質問もありました北側につきましては、中央ゾーンが今年度、プールが終わり、平成２８年、平成２９年と工事を行った後、段階的に次の段階で北側と移っていきたいというのが現在の計画です。","voiceIndex":215,"id":"exchange-095"},{"speaker":"渡部委員","kind":"質問","question":"であれば、また最初からスタートをかけなければならないことだと思いますので、平成３１年とか平成３２年とか、早急だという感じではないのですが、実際、工事に入るのは、そんなに平成３０年とか平成３１年とか、すぐ入りそうな感じ、また、基本設計からやり直しですか、その辺を。","respondent":"多並公園課長","answer":"ということで、戻りがないように、平成２９年度の中央ゾーンの工事が終わった後は、遅滞なく今度は北側に入っていける、要するに、野球場も入っていけるような形で、必要なことがあれば拡充で修正設計をかけながら、地元の方ときちんとお話しして、ご説明して整備を進めていく。","voiceIndex":217,"id":"exchange-096"},{"speaker":"渡部委員","kind":"質問・要望","question":"利用者団体の声として、実はその改修工事がいつ始まるかわからない中で使っていて、ですから大きな要望とかをしていかなかった中で、今のお話を伺っていると、あと四、五年はそのままかとなった場合、実はグラウンドの土の部分が、もうおわかりかと思うのですが、段々になっているというのでしょうか、水の通り道ができていたりして、何センチもくぼんでいるのです。","respondent":"多並公園課長","answer":"委員の今のご指摘のとおり、利用者の方が安全にご利用いただけるように努めるのが公園管理者の義務ですので、しっかり今後整備を進めて、子どもたちが安全に使えるように努めてまいりたいと思います。","voiceIndex":219,"id":"exchange-097"},{"speaker":"のだて委員","kind":"質問・要望","question":"公園にいた方からもお話を伺うと、高齢の方は、「和式は立ち上がれないため洋式にしてほしい」、また、子どもと一緒に来ていたママからは、「多機能トイレだと子どもと一緒に入れるので安心」という要望がありました。区はこうした実態をつかんでいるのか、つかんでいる場合、どういった対応をしてきたのか伺います。こういった問題も解決するため、誰でもトイレにすべきだと思いますが、いかがでしょうか。","respondent":"多並公園課長","answer":"区の考えとしましては、今のような改築に合わせて、今のような形で整備を進めていくというのが基本の考え方であります。先ほどの委員のお話のとおりの考えです。わかば児童遊園の先ほどの子どものお話ですけれども、私ももちろんそれは聞いてあります。","voiceIndex":222,"id":"exchange-098"},{"speaker":"のだて委員","kind":"質問","question":"整備は今後、洋式を基本として誰でもトイレも設置していくということでした。この中でしっかりと計画を持って進めていってもらいたいと思います。昨年は公園便所の車椅子トイレ対応が２４カ所でしたが、今年の品川の公園では、誰でもトイレが１８カ所、身障者用トイレが１３カ所と合計３１カ所に増えています。ぜひもっとスピード感を持って計画を立てて整備してもらいたいと思いますが、いかがでしょうか。","respondent":"多並公園課長","answer":"ただ、いろいろな形で工夫ができるところがあれば、もちろんそういうつけ方もできますし、基本的な考え方は、先ほどの話ですけれども、あとは、地域のお声をよくお聞きしながら、必要なところがあれば、もちろん整備するということは必要だと思っているところです。","voiceIndex":224,"id":"exchange-099"},{"speaker":"のだて委員","kind":"質問・要望","question":"次は、特定整備路線に移りたいと思います。これだと、ほかのところから話を聞いているので会わないと受け取ってしまいますが、直接会って話をしたいという方に対して、こんな対応はひどいのではないでしょうか。話し合いを持たなかった町会の方は、どうしたらいいのでしょうか。都と区が連携して話を聞くべき場合とはどのような場合でしょうか。住民の会はなぜその場合に当てはまらないのか伺います。","respondent":"中村都市計画課長","answer":"ですので、これは説明会の機会があるときだけ意見をお伺いするということではなくて、日ごろからお伺いするような、そういった姿勢でおりますので、いつでも区民の声としてお寄せいただければというふうに考えております。","voiceIndex":226,"id":"exchange-100"},{"speaker":"のだて委員","kind":"質問","question":"これまでも区は、都が事業者だから住民の会と会おうとしませんけれども、もともとこれは区長が進言して２９号線を含む特定整備路線が再び動き出したわけです。これにより住みなれた地域を立ち退かされる人がいるわけです。生活を破壊される人たちが、直接話をしたいと言うのですから、私は会うべきだと思いますが、いかがでしょうか。区長が会う場合と会わない場合の違いは何か伺います。","respondent":"中村都市計画課長","answer":"こういった地元の方々の声につきましては、先ほど委員からもご指摘ありましたけれども、都と区が連携して話をする場合というところでは、これは事業そのものは東京都が進めるものですけれども、区としましても、東京都にしっかりやっていただくという意味で。","voiceIndex":228,"id":"exchange-101"},{"speaker":"のだて委員","kind":"質問・要望","question":"いつでも聞く姿勢があるのならば、住民の会と会って話を聞いていただきたいと思います。かたくなに会おうとしないこの姿勢は、戦争法や沖縄の辺野古基地などでの政府の対応と重なって見えてきます。反対の人とは話し合いすらしないということでは、民主主義は成り立ちません。住民の会と会うことを強く要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":230,"id":"exchange-102"},{"speaker":"高橋（し）委員","kind":"質問","question":"１５６ページのオリンピック・パラリンピック施設周辺無電柱化事業と、１６３ページのほかの委員からありましたけれども、空き家等実態調査についてお伺いします。先に順序があれですけれども、１６３ページの空き家のほうについてお伺いします。成果報告書にもありますが、この第６条の実態調査についての規定なのですが、平成２６年の空き家等の実態調査についての概要をお尋ねします。","respondent":"矢木住宅担当課長","answer":"外観調査につきましては、１,６７４件、外観調査から空き家ではないかという件数が発見されました。そのうち９９件が要対応物件ということで指摘を受けております。行政等に活用してほしいということで、アンケートによりまして２７件の回答がございました。","voiceIndex":232,"id":"exchange-103"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１,６００戸あまりあって、９９件が要対応、２７件が対応してほしいという、そういう要望であったというふうに今お話を伺いました。は管理不全な状態の早期解決を図るとありますが、この地域の力支援チームで、今お話しあった中のうち、どのぐらいの件数を解決しようとされたのでしょうか。それは具体的にどのようにして進められたのでしょうか。","respondent":"矢木住宅担当課長","answer":"具体的には、例えば、管理不全状態にある空き家、特に建築危害防止から活動しなければならない物件につきましては、建築課、住宅課および地域活動課等々で対応していますし、また、廃棄物に起因する管理不全状態にある空き地等、いわゆるごみ屋敷につきましては。","voiceIndex":234,"id":"exchange-104"},{"speaker":"高橋（し）委員","kind":"質問","question":"ただ、先ほどありましたが、今回、空き家等適正管理審議会のほうに諮問をしなければならなかった例は、この地域の力支援チームでも解決できなかったわけですが、それはどのような点でこちらの審議会に諮問しなければいけない状態になったのでしょうか。それは今後の空き家問題の解決についての検討につながっていくと思いますので、その辺についてお尋ねします。","respondent":"矢木住宅担当課長","answer":"１軒につきましては、こちらはかなり建物的にも危険になっているごみ屋敷的なものでございまして、躯体にも影響が出ているかと、中を見られないので、それは想像にしか過ぎないのですが、危険度が高いということで、また。","voiceIndex":236,"id":"exchange-105"},{"speaker":"高橋（し）委員","kind":"質問","question":"そういう形で、先ほどは１つ解決に向かっているということですが、行方不明の方がいらっしゃるということなのですが、そういった場合は、今後の状況、諮問し、指導しというその次の段階でなかなか解決しない状況なのですが、この件に関してはどのような解決の時間的あるいは方法的な見通しをお持ちでしょうか。","respondent":"矢木住宅担当課長","answer":"それでその後の対応というところで、また、建物の危険度も見ながら最終的な判断をしていく形になると思われます。","voiceIndex":238,"id":"exchange-106"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そのようにして行政の方も努力をしているということがご理解いただけると思います。今後もこの件に関しては、なかなか大変ご苦労があると思いますけれども、このような形で進めていっていただきたいと思います。時間があれなのですが、平成２６年度に空き家活用モデル事業というのがありました。既に１件実績があったようですが、その内容についてお知らせください。","respondent":"矢木住宅担当課長","answer":"１件の実績ということですが、申しわけございません、こちらは新聞の誤報でございまして、現在、鋭意進めているところです。","voiceIndex":240,"id":"exchange-107"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"はい、わかりました。ただ、それを使うことによってトラブルが起きることもありますので、課題を検証して施策を実現させていっていただきたいと思います。空き家に関するこのような事業は積極的に取り組んでいっていただきたいと思います。オリンピック・パラリンピックのほうは、また別の機会にお尋ねします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":242,"id":"exchange-108"},{"speaker":"石田（秀）委員","kind":"質問","question":"私からは、１５９ページ、公園管理費に関連して、中央海浜公園のことを伺います。ここら辺のところは、もちろん警察等もお考えがあってそういうふうにしたのでしょうが、今、自転車が車道を通るということもわかりますけれども、そうなったときに、そこら辺のところをしっかり周知をしないと、歩行者の安全よりも自転車の安全を守るのですかという勘違いが起きるような気がしてなりません。","respondent":"柏原企画調整課長、安井土木管理課長、稲田道路課長","answer":"都立公園の指定管理というお話でございましたので、私のほうから指定管理の考え方の部分からお答えします。ただ、細かい部分で若干不都合な部分が出てきているようなことであれば、私どものほうに言っていただければ、再度やり直しとか。なかなかああいう現場条件で難しいところでございまして、ナビマークの設置を警察にも依頼したのですが。","voiceIndex":244,"id":"exchange-109"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは要望にしておきます。そういうふうに現実起きているではないですか。区が今指導していますと、どこでしているのですか。いつの段階で指導しているのですか。私は一緒になってそういうときにやってほしいと質問をしたのです。それに対してもう一度答弁をいただきたいと思います。だから、そこら辺についてをどう捉えてああいう整備をしたのかということを改めて伺います。","respondent":"安井土木管理課長、稲田道路課長","answer":"一旦、掘削等を行って、仮復旧の段階ではアスファルト等で地固めをするという形になろうかと思いますので、本復旧のときに、私どもも足を運んで、もう一度業者を指導させていただいて。自転車が歩道に乗り上げるときは、歩行者の安全を確認して、降りて乗り入れるというのが原則でございまして、そのように歩行者優先で考えているです。","voiceIndex":248,"id":"exchange-110"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だから、それがいろいろ悩んだ結果ああいうふうになったということはいいのですが、それは誤解を与えないように、どちらの安全を守っているのか、今お話を伺うと、歩道なので歩行者の安全を守っていらっしゃるというのは、それが当たり前だとおっしゃっているのだから、そういうことを言うのであれば、それはそういう整備をするのが私はよかったのではないかと思うのですが、そこら辺。","respondent":"稲田道路課長","answer":"歩道の歩行者の安全を守るというところにおきましては、今後におきまして、現場に周知を図っていく、よく自転車、歩行者、歩行者の安全を優先ですというところの周知を図っていきたいというふうに考えております。","voiceIndex":251,"id":"exchange-111"},{"speaker":"こんの委員","kind":"質問・要望","question":"１点目の橋梁維持管理費ですけれども、現在、平成２２年度策定の橋梁長寿命化修繕計画が５年を経過したということで、見直しをするために道路ネットワークの安全性や信頼性の確保として、橋梁の安全性向上と耐震向上、また、橋梁の定期点検、修繕、架替えによる修繕計画の更新、そのほか３つの目的を果たすために、一部改定の計画が策定していると伺っているところです。現在はどのような状況でしょうか。","respondent":"稲田道路課長","answer":"品川区内にあります歩道橋の数です。区の管理の歩道橋、いわゆる歩道橋というものなのですけれども２２橋、国管理が１６橋、都管理が１０橋という数値です。それから、通行者が２００人未満の横断歩道橋は何橋かです。これは以前にもご回答いたしましたけれども、現在も７橋です。","voiceIndex":254,"id":"exchange-112"},{"speaker":"こんの委員","kind":"質問","question":"そこで平成２５年度の予算特別委員会のときにもお聞きしたのですが、そのときのご答弁では、通行量２００人未満の７橋のうち、極端に利用が少ない横断歩道橋について、現在、撤去も含めた検討を進めておりますと。この件につきまして、今回のこの計画の改定に盛り込まれた利用者が極端に少ない横断歩道橋の検討がどのように進められているのでしょうか。撤去も含めた検討の進捗状況をお知らせください。","respondent":"稲田道路課長","answer":"橋梁長寿命化修繕計画、今年度からスタートしております。昨年度、この見直しを実施してきたところです。","voiceIndex":256,"id":"exchange-113"},{"speaker":"こんの委員","kind":"質問・要望","question":"昨年の決算特別委員会で、我が会派のあくつ副委員長より、北品川一丁目の八ツ山踏切から区道に架かる栄歩道橋、これについて信号設置の地元要望を実現するための１つのハードルとなっているので、撤去を求めさせていただいた経緯があります。桜新道歩道橋の検討状況、撤去できない状況であれば、エレベーターの設置も要望しますけれども、それぞれ現状をお知らせください。","respondent":"稲田道路課長","answer":"ただ、そうは言いましても、バリアフリーの観点からエレベーター等の設置におきましては、設置する場所がないというところがまずハード的な部分で難しいと、今後も警視庁と協議をより一層進めていきまして、横断歩道の設置を要望していきたいというふうに考えております。","voiceIndex":258,"id":"exchange-114"},{"speaker":"こんの委員","kind":"質問・要望","question":"そこでお伺いしたいのですが、空き家の実態調査の中で、今回のような危険な箇所はほかにも存在すると思われますが、実態はどのような現状でしょうか。そうした所有者の空き家の適正な管理はどのようにされているのでしょうか。今年施行になった「空き家等の適正管理等に関する条例」に基づき、所有者への適正な管理を求めていると思いますが、どのような状況なのか、それぞれお答えください。","respondent":"矢木住宅担当課長","answer":"お電話がわかっている場合はお電話でご説明申し上げる。ないしは、実際、会ってお話しするということもあります。あらゆる方法を使いまして、所有者の皆さまにできるだけ自主的に解決していただくように粘り強く交渉を進めているところです。","voiceIndex":260,"id":"exchange-115"},{"speaker":"こんの委員","kind":"質問","question":"所有者が高齢者だったり、区外在住の方というのは、今、調査の中でまだはっきりはしていないというご答弁でした。区外在住の方も、例えば都内在住であっても、定期的に適正な管理をすることは困難な状況がうかがえます。このような場合、区は適正な管理をしていただくために、どのような対策をとっていかれようとお考えなのでしょうか。お願いします。","respondent":"矢木住宅担当課長","answer":"高齢者あるいは区外在住といった空き家管理の困難な方々に対する対策ですが、まず、現在作成中のパンフレットの中に有効活用策、こういったところで支援がありますということを書き込みまして、それを空き家の所有者に配布するとともに、今後、この１年間の取り組みを通じまして。","voiceIndex":262,"id":"exchange-116"},{"speaker":"こんの委員","kind":"質問","question":"燕市は対処療法的な管理不全対策が中心だったのが、予防的取り組みが必要とのことから、管理不全を予防し、空き家を再生につなげようと、市から、同市のシルバー人材センターに持ちかける形で協定を結んでおります。こうした取り組みはとても参考になると思いますし、品川区としても有効な対策ではないかと考えますけれども、いかがでしょうか。","respondent":"矢木住宅担当課長","answer":"委員ご指摘のとおり、予防的取り組みというのは、空き家対策に有効であるというふうに区としても認識しています。","voiceIndex":264,"id":"exchange-117"},{"speaker":"大倉委員","kind":"質問・要望","question":"バイクの考え方、例えば区はどのように考えているか教えていただきたいのですが、自転車だと、停めて放置すると持っていかれて、３,０００円払って手元に戻ってくるという形なのですけれども、バイクだと、駐車しているだけで駐車違反でかなり大きな額をとられるというところであれば、バイク駐輪場を利用したいのだけれども、ないから、どうしてもそうなってしまうという現状があると思いますし。","respondent":"安井土木管理課長、田口交通安全担当課長","answer":"我々としては、さりとて野放しにしておきますと、真面目に屋外広告物を出していらっしゃる方に対して、勝手にやればいいという形になりかねませんので、我々としては。少ないのですが、今年度、五反田のほうにもバイクの駐輪場を整備する計画で現在進めてあります。","voiceIndex":267,"id":"exchange-118"},{"speaker":"大倉委員","kind":"質問・要望","question":"まさに過料の取締りのほうなのですが、私も実際に目撃したことがありますけれども、車で来て、バーッと来て、ペラッと貼って、細い道でもバンバン貼っていっているわけです。バイクなのですが、ぜひ整備を進めていっていただきたいのですが、例えば、駐車場、今ある車の駐車場、あそこに２台停められたほうが効率がいいとか、そういったところは考えたりというのはしていますでしょうか。","respondent":"安井土木管理課長、田口交通安全担当課長","answer":"違法な屋外広告物に対する対応なのですけれども、これは他区とも非常に悩んでいるところですので、ほかの区で何かいいようなものがあれば取り入れながら、こういったものを一掃できるような形で何とか進めていきたいと考えています。バイクの駐輪場の整備ということで、今、委員からご指摘のとおり、例えば、車の駐車場を利用する、確かになかなか用地の確保が難しいということで、やはりいろいろな対策を考えていかなければいけないと考えていますので。","voiceIndex":270,"id":"exchange-119"},{"speaker":"大倉委員","kind":"質問","question":"バイク、いろいろ検討していただいて、バイクに乗っている人も品川区には駐輪場がいっぱいあって行きやすいというところでやっていただければと思います。最後に、自転車走行レーンの周知について伺います。今、歩行者、歩道にある自転車レーンは、基本的には歩行者が歩いていいのかいけないのか教えてください。","respondent":"稲田道路課長","answer":"歩道にある自転車のレーン、区道で言えば桜新道です。基本的に歩道ですから、そこは歩行者は歩いていいというところです。","voiceIndex":273,"id":"exchange-120"},{"speaker":"大倉委員","kind":"意見","question":"自転車走行レーン、できれば自転車が通れる道にしてあげないと、そこを自転車は結構スピードを出して通っていますから、歩行者が入ってきたらぶつかってしまうなどということは、逆に設置したことでと、なってしまうので気をつけて周知してください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":275,"id":"exchange-121"},{"speaker":"本多委員","kind":"質問","question":"それで質問を続けますが、まず、この２００万円の決算です。事務事業概要を見ますと、平成２６年度ではＪＲ大井町駅の概算設計費ということで、平成２７年度は詳細設計費ということになっているのですけれども、今後の工事の、これ、２００万円が大井町の設計費用になっているのですけれども、今後の工事について助成を出していくのか、また、この大井町の今後のスケジュールについて教えてください。","respondent":"中村都市計画課長","answer":"この設計費は、基本的な設計、基礎調査も含めた設計です。本年度につきましては、詳細設計を今行っているところです。今後のスケジュールにつきましては、来年、平成２８年度と平成２９年度にかけて設置工事を行う予定です。引き続き、補助をしていく予定です。","voiceIndex":278,"id":"exchange-122"},{"speaker":"本多委員","kind":"意見","question":"訂正いたします。先ほど、「ホーム棚」と言ったようなので、済みません、「ホーム柵」です。訂正をさせてください。済みませんでした。ホームドアなのですけれども、ホームからの転落や列車との接触事故防止などを目的とした安全対策の１つでありますけれども、これまで区内駅ホームドアの成果がどうなのかお聞かせください。","respondent":"中村都市計画課長","answer":"経費につきましてですけれども、ドアの設置前に警備員が立つということにつきましては、これはよく建築工事などでも交通警備員がついて安全を図るような、そういった工事が完成するまでの間の安全対策として経費としてこれは見込まれているものと考えられます。","voiceIndex":280,"id":"exchange-123"},{"speaker":"本多委員","kind":"質問・要望","question":"ホームドアというのは和製英語でありまして、英語ではPlatform screen doorですとか、Automatic platform gateと呼ばれておりますけれども、これ、種類が実は何種類もありまして、大きく分けて３つぐらいあるそうなのですけれども、フルスクリーンタイプとロープ式スクリーンドア、この可動式ホーム柵、３種類ぐらい大きく分けてあると思うのですけれども。","respondent":"中村都市計画課長","answer":"しかしながら、区といたしましても、そのホームに設置するべき最も安全なものについて要望しているものです。今、委員がご指摘の３種類ありますけれども、こういった中でそのホームの中で一番安全なものを選定していただくように働きかけを行っております。","voiceIndex":282,"id":"exchange-124"},{"speaker":"本多委員","kind":"質問","question":"安全性を追求するためにしつこく質問いたしますけれども、大体よく見られるのが、閉まるときにホームドアと電車のドアが同時に閉まるのが一般的だと思うのですけれども、より安全性を追求していくために、ＪＲ西日本では、ドアのほうを先に閉めて、時間差を持って電車のドアを閉めたりしたり、あと、今、新しいものの企画・開発では、従来のものだと。","respondent":"中村都市計画課長","answer":"こちらについては確認をしながら区としても進めていっていただくよう、鉄道事業者と設置の方法について確認をしてまいりたいと思います。","voiceIndex":284,"id":"exchange-125"},{"speaker":"本多委員","kind":"質問","question":"ぜひよろしくお願いします。先ほどの質疑でも、鉄道事業者との話し合いで、区でも計画を持つようにというご意見がありましたが、私も全く同じに思うのですけれども、その辺の区の進め方、鉄道事業者と進めていくということなのだと思うのですが、具体的にどういうふうに話し合いを持っていくのか、その時間のとり方ですとか、進め方ですとか、その辺を具体的に教えてください。","respondent":"中村都市計画課長","answer":"ちなみに、東急線では２０２０年までに全駅についてホームドアを設置するというふうに公表されているところです。","voiceIndex":286,"id":"exchange-126"},{"speaker":"本多委員","kind":"質問","question":"ホームからの転落とか、事故を防ぐように進めていってください。同じく駅舎のセーフティー化、今はホームドアですけれども、駅全体について伺いたいと思います。区内１４線で延べ４０駅がありますけれども、この安全性について、どういうふうにお考えか、取り組む方針かをお聞かせください。それで、この４駅を中心にもっと増えていくと思うのです。","respondent":"中村都市計画課長","answer":"大井町につきましては、これは先ほども申しましたけれども、今後設置が予定されるということで、今この４駅について安全対策がなされるというふうに認識をしております。","voiceIndex":288,"id":"exchange-127"},{"speaker":"本多委員","kind":"意見","question":"１５９ページの公園管理費で、維持管理で委託というのが何種類かありますけれども、それぞれ委託で金額を決めて、年間を通じて何があってもその金額でという委託だと思うのですけれども、昨今の水害ですとか、台風ですとか、非常に状況が変わってきているのですけれども、その辺のことを考慮されて予算編成等、人件費とか、そのものの処理とか、いろいろなことを考えて単価設定を考えていかれるのか、現状。","respondent":"多並公園課長","answer":"今後につきましては、今のような災害対策を含めながら、よりよい形で考えていきたいと思っているところです。","voiceIndex":290,"id":"exchange-128"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、１５４ページの都市計画道路整備事業についてと、１６２ページの住宅・建築物耐震化支援事業について伺いたいと思います。この１２本の候補路線のうち、補助２７号線について伺いたいと思います。この補助２７号線はどのような道路かを確認させていただきたいと思うのですが、どこからどこまでで、どのような道路で、そして幅はどれぐらいで、区内の全長は、長さはどれくらいなのか。","respondent":"中村都市計画課長","answer":"こちらは幅員といたしましては、２５ｍから２０ｍですけれども、この中で完成部分が９７７ｍ、そして未完成部分が１,２００ｍです。","voiceIndex":293,"id":"exchange-129"},{"speaker":"石田（ち）委員","kind":"意見","question":"この補助２７号線は、今おっしゃられたように、池上通り、品川郵便局の裏のほうから見晴らし通りではない住宅街を突っ切って、そのまま浜川小学校、浜川公園を通って桜新道に抜けていくという、こういう道路ですけれども、この道路は、いつ決定された道路か、そして拡幅する理由は何かをお聞かせください。","respondent":"中村都市計画課長","answer":"この道路につきましては、当時は戦災復興ですが、これは道路の基本的な機能といたしまして、今日の言葉に置き替えますと、交通のネットワークの形成と、それから防災に資する道路ということで進めていく予定がなされたものです。","voiceIndex":295,"id":"exchange-130"},{"speaker":"石田（ち）委員","kind":"質問","question":"昭和２１年の戦災復興院での決定だということで、この道路も戦後まだ荒れたまちの中で決まった道路と、今とは全く違う状況で計画されている道路だということです。２７号線上に住む住民の方々に話を伺ってきました。必要性も住民の要請もないこの補助２７号線は、第４次計画に選定すべきではないと思うのですけれども、いかがでしょうか。","respondent":"中村都市計画課長","answer":"区民の皆様のご心配もあろうかと思いますけれども、十分この計画については地域の皆様方に説明、周知をしていくものであるというふうに認識をしています。","voiceIndex":297,"id":"exchange-131"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"全ての路線に対して検証を行うということで、この２７号線に限らず、先日の建設委員会のところでは、３０号線もやはり選定しないでほしいという署名なども地域から出されています。区は区民の声をしっかりと国や都に住民の立場で説明してほしい。こういう声をしっかり受けとめていただいて、そしてやはり補助２７号線、選定しないように強く求めたいと思いますけれども、いかがでしょうか。","respondent":"中村都市計画課長","answer":"こういった道路の計画を進めていくに当たりましては、一般的には全て進めるに当たりましては、地域の皆様方に十分に説明をして、そして理解を深めてもらいながら進めていくというのが絶対条件ですので、こういったところは都が進める道路につきましては。","voiceIndex":299,"id":"exchange-132"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"いくら説明をしても、そのまちを立ち退かされる、これは理解し得ないことだと思いますので、この１２本の候補の路線を選定しないことを強く求めて、次の質問に行きたいと思います。品川区の耐震化支援事業についてですけれども、品川区耐震改修促進計画の耐震化目標９５％と先ほどもありましたけれども、これに対して、現在、どこまで到達しているのかを伺いたいと思います。","respondent":"鈴木建築課長","answer":"そうした数字を合わせますと、現在、概算ですけれども約７０％というような状況です。","voiceIndex":301,"id":"exchange-133"},{"speaker":"石田（ち）委員","kind":"質問","question":"現在、７０％と。平成２６年度から耐震化建替え助成を品川区は廃止しました。この除却１２６棟中、建替えまで進んだ棟数は幾つか教えてください。それから、除却助成１５０万円が出ますけれども、１５０万円かからずに除却できるケースも多くあると工務店の方からお聞きしました。１５０万円ではなく１００万円未満で除却できたケースがこの１２６棟中どれぐらいあったのか伺いたいと思います。","respondent":"鈴木建築課長","answer":"除却費用、上限１５０万円ですが、これも１５０万円以下の詳細な数字は今現在手元にはございませんが、やはり区内いろいろと平均的なものを見ますと、非常に道路が狭いというところもございまして、一定程度この１５０万円の中で除却。","voiceIndex":303,"id":"exchange-134"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"除却とともに建替え助成を一緒に行っていくということはできないのでしょうか。１５０万円ですけれども、建替えでかかる予算は大体２,０００万円、３,０００万円を超えていくわけです。だったら、そこにしっかりと区が費用的な助成を支援をして進めていくことが必要だと思うのですけれども、建替え助成の復活を求めたいと思いますけれども、いかがでしょうか。","respondent":"鈴木建築課長","answer":"したがいまして、基本的には後退という形では区としては考えていないというところで、費用については、やはり適正な助成、メニュー、単価を設定していますので、今後はしっかりそれをいかにお使いいただけるかというところで。","voiceIndex":305,"id":"exchange-135"},{"speaker":"たけうち委員","kind":"質問","question":"私は、１５４ページの道路空洞修繕、それから１５９ページのしながわ水族館運営費、それから１５７ページの橋梁維持管理費でお聞きしたいと思います。それから１５７ページの橋梁維持管理費は、先ほど出ました歩道橋です。","respondent":"稲田道路課長、多並公園課長","answer":"４９４万７,８４９円の内訳ですが、調査が１３５万円、それから補修が４件、３５９万７,８４９円です。それと、現在の状況、平成２７年度の状況です。平成２７年度は、現在、調査中というところでございまして、調査を実施しています。私からは、水族館についてお答えします。今、委員にご案内いただきましたとおり、平成２３年にあり方検討委員会ということで専門委員を設置して、これからの水族館のあり方について検討してきたところです。","voiceIndex":308,"id":"exchange-136"},{"speaker":"たけうち委員","kind":"質問・要望","question":"歩道橋についてはわかりましたけれども、そうすると、当時出ていた課題が、通学路に指定されているのだという中で、それを今、廃止するという方向で調整しているということで、いずれそうなるのだと。その場合には、壊していただくのだと、お金はかかりますけれども、そういうことでいいのかという確認です。","respondent":"和田河川下水道課長、多並公園課長、稲田道路課長","answer":"もう１件の２５周年、来年度ですけれども、やはりほかの水族館の状況を見てみますと、かなり何億円もかけるものをやるよりは。学校側に問い合わせたところ、そこを渡る児童はいないというところで、通学路の変更については、現在のところ。","voiceIndex":311,"id":"exchange-137"},{"speaker":"たけうち委員","kind":"質問・要望","question":"ただ、都がやると言っているのは都道中心にやると思うのです。区道はやらないのではないかと思うので、そんなことはないですか。やるならしっかりその辺も連動してやっていただきたいと要望させていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":315,"id":"exchange-138"},{"speaker":"松澤委員","kind":"質問","question":"３点お聞きしたいと思います。初めに、細街路拡幅整備事業についてですけれども、建築基準法上に４２条２項道路というものがありますけれども、改めて４２条２項道路はどんな道路なのかについてお聞きしたいと思います。","respondent":"鈴木建築課長","answer":"こういった道路につきましては、建替えに合わせて、塀ですとか建物を中心から２ｍセットバックをして、将来皆様が建替えが完了するときに４ｍの道路を目指す。ひいては地域の防災性能向上、安心なまちづくりを進めていくという条文です。","voiceIndex":317,"id":"exchange-139"},{"speaker":"松澤委員","kind":"質問","question":"中心線から２ｍですから、ちょっとクランクみたいになっている形もありますけれども、これはよくできているのですけれども、私道の部分がなかなか下がってくれない、下がってもそこにプランターを置いたり、いろいろなものを置いたりしています。これはどう考えてもおかしいのです。こんなことが違反でなくて何だろうと思いますので、その辺についてお聞きしたいと思います。","respondent":"鈴木建築課長","answer":"そこに約半分程度、３分の２程度、建築敷地を計画しまして建物が建ったというところでございまして、建築基準法は、設定した計画敷地に対して基準法が適用されるというところでございまして、その部分については後退していただいているという状況ですが。","voiceIndex":319,"id":"exchange-140"},{"speaker":"松澤委員","kind":"質問","question":"今お話を伺いました。１０台ぐらいあるのです。自分の前面は駐車場ですから、そこに１０台の自転車を並べてもいいわけです。なぜこういうことが起こるのか、これはやはり厳正に取り締まるべきだと思うし、また、陳情者の陳情のおかげでごみ置き場は撤去されたのですけれども、駐輪場がそのままなのです。なぜこれが撤去されないのか、なぜ指導できないのか、その点についてお聞きしたいと思います。","respondent":"鈴木建築課長","answer":"ただ、やはりラックが設置されて、そのラックを設置されますと、自転車本体が道路部分にはみ出してしまうというところで、これは今現在、通常のラックがない青空の、青空と言ったら言い方があれかもしれませんけれども、ラックがない自転車とプランター、これは基準法。","voiceIndex":321,"id":"exchange-141"},{"speaker":"松澤委員","kind":"質問","question":"品川区は５０mm対応ということで、目黒川、立会川、そして戸越の下水道幹線、この３つを重点的に５０mm対応ということでやっているのですけれども、聞くところによると、目黒川、戸越幹線は終わったということで、今この最後の立会川、これが第２立会川幹線というものがほとんどでき上がっているので、水を貯留できる暫定貯留が３万５,０００トン、今度、勝島の雨水貯留施設ができる４,７５０トン。","respondent":"和田河川下水道課長","answer":"その他の地区につきましては、先ほども塚本委員のところで答弁させていただいたように、５０mm対応にはなってございませんので、基本的には先ほどの答弁と重複いたしますけれども、下水道局としては、浸水被害が最も厳しいところを中心に現在工事を進めているという状況です。","voiceIndex":325,"id":"exchange-142"},{"speaker":"松澤委員","kind":"質問","question":"戸越下水道幹線はもうできているのかと思っていたものですから、びっくりしました。補正の中で拡充するということだったのですが、これは５０mmが終わって、戸越だけは一番危険性があるので７０mmにするのかというふうに思っていたものですから、ちょっとびっくりしたのですけれども、この工事そのものが新たに始めるということは、どこを起点として、どういう形で始めるのでしょうか。","respondent":"和田河川下水道課長","answer":"ですから、路上を掘削したりという工事ではございませんで、中をモグラのように進む工事ですので、基本的には地上の住宅等にご迷惑をかけることはないものと考えられます。","voiceIndex":327,"id":"exchange-143"},{"speaker":"松澤委員","kind":"質問","question":"そうしますと、出入口が必要なので、また三ツ木公園をつぶすことになるのでしょうか。そうしますと、またその辺の説明会等々はいつごろ行われるのか、それを聞きます。","respondent":"和田河川下水道課長","answer":"現在、設計がこれからですので、今の計画上の話ですけれども、今の計画上は、西品川公園を発信基地として、西側に三ツ木通り、戸越銀座通りの下を掘り進める予定です。","voiceIndex":329,"id":"exchange-144"},{"speaker":"松澤委員","kind":"質問・要望","question":"次へ行きます。それと、なぜこれ、大崎駅西口だけがぴったり合っているのでしょうか。よろしくお願いします。","respondent":"溝口都市開発課長","answer":"それぞれコーディネート業務という形で３つ挙げております。大崎駅周辺地区のコーディネーター業務につきましては、今現在、エリアマネジメント活動をしております。そういった中での今後まちをどのように運営していくのか、そういったプランを策定するためにかかった費用です。","voiceIndex":331,"id":"exchange-145"},{"speaker":"松澤委員","kind":"質問・要望","question":"時間がないので、１点だけ要望しておきますけれども、五反田駅周辺、西五反田二丁目地域、あの辺はやはり桜並木をつくりたい、桜を植えたいという要望がすごくあります。当然こういうことを協議しているのだろうと思いますけれども、改めてその辺を要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":333,"id":"exchange-146"},{"speaker":"藤原委員","kind":"質問","question":"１６４ページ、借上型区民住宅ですが、毎回伺っていますけれども、特優賃です。現状とこれからを教えてください。","respondent":"矢木住宅担当課長","answer":"現時点までで７棟１１２戸をオーナーおよび使用者の皆様のご理解、ご協力を得まして返還してまいりました。今後、３月末までに３棟５０戸の返還を予定しております。今後も借上期間の満了に伴いまして、粛々と返還を進めてまいります。","voiceIndex":335,"id":"exchange-147"},{"speaker":"藤原委員","kind":"質問・要望","question":"これからも清々粛々とお戻しください。お願いします。それと、次が、１５６ページの下水道関連でお伺いしますが、これも毎回私は要望と質問をしていますが、もう、「あの西大井五丁目」と言えば通るぐらいと考えています。毎回これ、何年か越しで質問して要望すると、毎回美しい答弁が返ってくるのです。課長に伺ったら、「まだ工事をしていません。ぜひ新課長、どういう経緯か教えていただけますか。","respondent":"和田河川下水道課長","answer":"この２つの条件を加味して、今の状態で計画を進めますと、沿道の住宅に大きな被害が出るということが懸念されましたので、この辺については慎重に、今、計画を見直して検討を進めている状況というふうに聞いております。","voiceIndex":337,"id":"exchange-148"},{"speaker":"藤原委員","kind":"質問","question":"課長、状況はよくわかります。昔はあそこは池でした。だから、なるべく自転車は乗らないようにという施策だったのですけれども、何か時宜にかなったかもしれないけれども、部長がかわったからですか、違いますか。自転車いいですというのですから、駐輪場は。そういうふうになってきてしまうという、すごく思いがあるのですけれども、その辺の対策についてもどのように考えているか教えていただけますか。","respondent":"立川経理課長","answer":"来庁者の方も入口に近いということでとめられる方もかなりいらっしゃるですので、委員ご指摘のとおり、来年度に向けて費用対効果を踏まえ、どういった対策がとれるかということを検討してまいりたいというふうに考えているところです。","voiceIndex":339,"id":"exchange-149"},{"speaker":"藤原委員","kind":"質問","question":"そういう答弁をしていただけるとは思わなかったのですけれども、そういう答弁が出た以上は、やはり伺わなくてはならない。だから、そんな少ない数だとは思うのですけれども、その辺も含めて１回きちんと整理整頓は、もう１回モラルについての勉強からやらなくてはいけないのかという思いもあるのですけれども、その辺についていかがでしょうか。","respondent":"立川経理課長","answer":"庁舎の敷地内のことですので、今後、職員に対してしっかり指導していきたいというふうに考えております。","voiceIndex":341,"id":"exchange-150"},{"speaker":"藤原委員","kind":"質問","question":"せっかく出てきてくださったので、これはやはり人事もどういうことで、どういう形でやっていくか、これは大事なことです。職員のモラルですから。よろしくお願いします。","respondent":"米田人事課長","answer":"現状を細かく調査いたしまして、職員は職員の置くべき場所がありますので、そちらに置くように指導を徹底してまいりたい、このように考えてあります。","voiceIndex":343,"id":"exchange-151"},{"speaker":"藤原委員","kind":"質問","question":"職員の方は職員が置かれる自転車置き場があるわけですから、今日の質問は違う方向に行ってしまったのですけれども、ですけれども、１台置くとまた１台、また１台と増えていってしまうので、第三庁舎のあそこはひど過ぎるのではないかという思いがすごくありますので、人事課長と経理課長がいい意味でツートップでやっていただければ幸いです。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":345,"id":"exchange-152"},{"speaker":"石田（し）委員","kind":"質問","question":"よろしくお願いします。自転車走行レーンですが、先ほど、我が会派の大倉委員からも質問をいたしましたが、桜新道は歩道上なので歩行しても構わないというご答弁がありましたが、都道になるのですが、例えば今、山手通りで大きくまちが変わっていく中で、歩道と自転車走行レーンと一緒になってきているわけでありますが、そこについて自転車走行レーンで歩行者が歩けるのかどうか教えてください。","respondent":"田口交通安全担当課長、稲田道路課長","answer":"撤去の関係につきましては保管所のほうで対応していただいております。それと、駐輪場の関係につきましては、指定管理者であるＮＣＤのほうで２４時間対応しています。東京都の山手通りにおきましては、私、都道の内容的には詳しくありませんけれども、自転車道、それから自転車専用通行帯、自転車走行位置の明示とかというものがあります。道路構造例、道路交通法によって設置しているものと思われます。","voiceIndex":347,"id":"exchange-153"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"こういった変化が今、自転車においては著しく大きく変わってきている中で、やはり啓発をしっかりやっていかないといけないのかと。それと、１６０ページのまちづくりのイベント、情報発信についてですが、これは一体どのような事業なのかお知らせいただきたいのと、ほかの再開発では、なかなか見られない項目かと思いますので、なぜ大崎駅ではこういったのがあるのかお知らせください。","respondent":"田口交通安全担当課長、溝口都市開発課長","answer":"駐輪場を兼ねての交通安全ですが、以前、駐輪場のほうに、例えば今回、１４類型ですか、交通の道交法が変わりましたが、そういったものをチラシを置いて利用者に対してお配りするとか、現在まだやってございませんが。ですから、他地区でも同じような形でのエリアマネジメント活動を展開していくことによって、区と地元との役割分担をしっかりしていく中で、必要な予算を今後計上していきたいと考えているものです。","voiceIndex":350,"id":"exchange-154"},{"speaker":"石田（し）委員","kind":"質問","question":"市街地整備事業費ですが、そうすると、今後、例えばいろいろなところで再開発が行われるとしたときに、そういったところでもこういった開発が終わった後でもそこの開発事業者等も地域の人たちも含めて、一緒にそういったこともやっていこうかというのが区の方向性なのか、そこだけ教えてください。","respondent":"溝口都市開発課長","answer":"他地区においても開発だけ、つくっておしまいというわけではありませんので、つくったまちをいかに維持管理していくのか、その価値を維持していくのか、そういった観点も大事だと思います。そういったものも含めてまちづくりを進めていきたいというふうに考えているものです。","voiceIndex":353,"id":"exchange-155"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"最後に、１６１ページ、五反田駅周辺地区のコーディネート業務に関連をして、先ほどもほかの委員から五反田駅周辺にぎわいゾーンのお話がありました。なぜかというと、ＴＯＣの前は歩道橋しかなくて、なかなか反対側に渡ろうという気にはどうしてもならないのかというふうに思いますので、そこでどうやって回遊性を生み出していくのか、もし区のお考えがあればお知らせいただきたいと思います。","respondent":"溝口都市開発課長","answer":"そういった中、また回遊性というお話もありましたが、今１つの拠点が閉じられている中ではありますが、引き続き、ＴＯＣ、五反田駅周辺との連携を図っていきたいと思いますが、一時的に機能しなくなるものをしっかり五反田駅を３つの拠点を結んで機能的にまちが。","voiceIndex":355,"id":"exchange-156"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ということは、可能性的に高いのは、やはり売却ではないかというふうに、地元でもいろいろなうわさが今飛び交っていて、どれが真実なのかということがなかなか僕のほうでも理解に苦しむのですが、やはりそういった建て替えをしないということであれば、持っている必要性がないのかというふうに思ってしまうのも確かあるのかと思いますので、その辺の情報等もしっかりと受け取っていただいて、できる限り。","respondent":"溝口都市開発課長","answer":"そういった中でいきますと、今現在、策定しておりますビジョンをいかに実現していくのか、そこが一番大事なことだと考えていますので、ビジョンに基づいて将来のまちをしっかりつくれるように、関係機関とも調整しながら進めていきたいというふうに考えているものです。","voiceIndex":357,"id":"exchange-157"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"公園なのですけれども、都市公園法で国が住民１人当たりの公園面積の目標値を１人当たり５m2と定めていますけれども、品川区はこれにほど遠いという状況で、品川区全体で３.６３m2、そしてその中でも大崎地区は０.５５m2、荏原地区が１.２８m2ということで、とても低い状況になっていますけれども、この低い実態に対してどう捉えているのかということと、どう改善をさせようとしているのか。","respondent":"多並公園課長、寺嶋木密整備推進課長","answer":"その中で最低の誘致距離は半径２５０ｍという考え方がありまして、こういう整備の考え方のもとに、公園を配置計画等やっているところで、現在の今の品川区の状況でこれを当ててみますと。こちらの中から区が優先順位を決めて木密事業を導入しているというのが現状ですけれども、この整備地域というところに限定しての回答になりますが、公園、児童遊園、防災広場のいずれもない町丁目は、現在、３カ所です。","voiceIndex":360,"id":"exchange-158"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"３カ所しかないというのは初めて。私はこの丁目の中に公園がないというのは、やはり町会単位でいろいろと防災の訓練だったりとか、さまざまコミュニティもつくりというふうなことでしていますので、町会単位に公園がないというのが３カ所ということであれば、この３カ所のところには、ぜひ設置するという方針をもって整備をすべきではないかと思うのですけれども、いかがでしょうかというところが１点です。","respondent":"寺嶋木密整備推進課長、多並公園課長","answer":"こういった中で、不足しているところについては、今後の課題というのは十分認識しておりますけれども、まずは現在、指定している地区の早期達成に向けて取り組むということに今、力を注いでいるのが現状です。私からは、先ほど以外の国費についてご説明します。公園の補助金につきましては、今、委員からお話しありましたけれども、２ヘクタール以上の公園に適用ということでなっております。","voiceIndex":363,"id":"exchange-159"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１ヘクタールというのは、ＪＴ跡地が７,０００m2ですから、かなり大きな、あそこよりももっと大きな公園というふうなところなので、なかなかこれをつくるのは大変だということで、普通のまちなかにつくる公園は、網かけがされていないところは補助金が出ないというところですけれども、補助金が出なくても、私はその３町会については。","respondent":"多並公園課長","answer":"補助金というよりは、国の制度自体も大きな公園の改修、また、密集地域で急いで空地をつくらなければいけない、そちらに全力を注いで整備を進めるということのスキームでもありますので、品川区としても、まずは第一で今の密集事業で進めているところを何とか全力を挙げて。","voiceIndex":366,"id":"exchange-160"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこのところが、では、木密で本当に安全なところかというと、全然木密に網かかったところと全く変わらないという、そういう町会ですから、私はそれであれば、木密をそこまで拡大するとか、それから、そうでなければ公園をつくるとか、そういう形でぜひとも強力に進めていただきたいということで、要望をさせていただきたいと思います。改めて区民の切実な願いなのだというふうに思いました。","respondent":"中村都市計画課長","answer":"こういった取り組みを通して、少しでも歩行が困難な方のための外出の機会をつくるために、区としても事業者のほうに求めてまいったところです。","voiceIndex":368,"id":"exchange-161"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"実際に区民が求めているのは、本当にコミュニティバスが隅々まで行って、それで行きたいところに自由に行けるようにしてほしいという。独立採算ができればバス事業者もやるわけですから、そういうふうな中で、２３区調査を最近共産党としても行いました。そういうところで、区が補填しても交通権、移動する権利を保証する、この立場に立つべきだと思うのですけれども、いかがでしょうか。","respondent":"中村都市計画課長","answer":"駅の路線を１つ増やすのに、千数百万円かかるといったところを鑑みますと、全ての方のニーズに応えるためにコミュニティバスを設置するということに対して、税金のかかる費用とコストはやはり避けて通れないものだというふうに考えてあります。","voiceIndex":370,"id":"exchange-162"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ほかのところは１日数千人から１万人を超えるようなところで使われています。こういうところでしっかりと税金を使って実現をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":372,"id":"exchange-163"},{"speaker":"浅野委員","kind":"質問","question":"１５３ページの駅周辺等放置自転車対策事業、１５４ページ、街路灯建替事業、１５８ページ、河川水位監視経費、河川監視システム等再構築経費、時間があれば、１６１ページの百反歩道橋架替整備工事委託について質問します。最初に、放置自転車の件ですけれども、建設委員会で西小山駅近くの場所が放置禁止区域になったというふうに聞いております。","respondent":"田口交通安全担当課長","answer":"台数です。西小山南、こちらは定期自転車が３６７台、バイクが１２台となっています。西小山北、こちらは定期自転車が４台で、当日はございません。","voiceIndex":374,"id":"exchange-164"},{"speaker":"浅野委員","kind":"質問","question":"３６７台ということで、台数としては多いか、十分かというのはなかなか難しいところはあるかと思います。こちらは目黒区と接しておりまして、目黒区のほうでも駐輪場が駅の近くにあったかと思います。これは駐車場のほうが面積は大きいと思いますけれども、目黒川については、駅の近くというのはどのぐらいの駐輪台数が確保されているのか教えてください。","respondent":"田口交通安全担当課長","answer":"私のほうで把握しているのは、目黒区側は８台です。","voiceIndex":376,"id":"exchange-165"},{"speaker":"浅野委員","kind":"質問","question":"８台ということで、私もここへ行って見てきましたら、これだけしかないのだということを改めて感じたものであります。建設委員会の中では、目黒区と連携をしながら駐輪対策、西小山駅周辺は進めていきたいという話がありましたけれども、そもそも品川区と目黒区で駐輪対策、違法駐輪対策に事業の違いというのでしょうか、やり方の違いとかがあれば教えてください。","respondent":"田口交通安全担当課長","answer":"目黒区と品川区の違いというのは特にございません、お互いに連携を取り合いながら対策を進めているところです。","voiceIndex":378,"id":"exchange-166"},{"speaker":"浅野委員","kind":"質問","question":"今後とも監視を続けながら、放置自転車の対策を進めていっていただければと思います。次に移ります。経過観察の必要ありがそのうちの９０２基ということだと思います。何らかの形で危ない街路灯についてはまた建て直さなければならないとかあると思いますけれども、そこら辺の判断基準と、どの程度、建替えを行っているのかということについて教えていただければと思います。","respondent":"稲田道路課長","answer":"道路ストックの計画的な点検をやっていこうというところで考えておりますので、それに準じて５年に一度の点検をやっていきたいというふうに考えているところです。","voiceIndex":380,"id":"exchange-167"},{"speaker":"浅野委員","kind":"提案","question":"この件についてもう一度答弁いただければと思います。一つこれ、前にも提案したことがあるのですけれども、ＬＥＤの街路灯ですけれども、例えば、今、地方でもときどき新聞記事にも出ているのですけれども、灯内に充電器を設置するという、このような街路灯もスリムな形で実現しているみたいでありまして、このような街路灯も利用したらどうかと考えています。","respondent":"稲田道路課長","answer":"東京近辺では町田市ですが、平成２５年から設置をして、１１５基設置している状況です。この蓄電池を搭載した街路灯ですが、まだ出始めて四、五年ですので、明るさ、持ち時間、そういうものについてまだまだ改良の余地があると私どものほうでは考えております。","voiceIndex":382,"id":"exchange-168"},{"speaker":"浅野委員","kind":"質問","question":"次に行きます。先日の台風１８号のときに、河川監視システムの動きが、私のネット環境が悪いのか、動きが悪かったとネットで見ていて思ったわけですけれども、たしか河川監視システムの再構築を実施するという、平成２６年度ですか、予算もあって話もあったと思いますが、そのときには、これが完成するとアクセス障害は今後心配がないという、そのような話を私も聞いた記憶があります。","respondent":"鈴木防災課長","answer":"ご指摘のありました気象協会を通じての気象情報につきましても、外部のサーバを設置する、それから、それぞれ別々に管理、独立したシステムを一元管理をしまして、機器室、災害対策室のほうで全てを一元管理で見られるというような再構築をしたものでございまして。","voiceIndex":384,"id":"exchange-169"},{"speaker":"浅野委員","kind":"質問・要望","question":"百反歩道橋の件ですけれども、こちらは歩道橋ができまして自転車も通れるようになり、また、人も通行できるというようになりましたけれども、こちらの利用率というのでしょうか、以前の歩道橋と比べてプラスになっているのか、それともまだまだ低い状況なのか、この件について教えてください。","respondent":"鈴木防災課長、溝口都市開発課長","answer":"ただし、状況によってはやはりサーバの容量いっぱいまでアクセスが集中すると、動きが鈍くなるという可能性はあるということで認識をしております。新しい歩道橋につきましては、今現在、今年度中に１つの効果として、歩行者、自転車がどのぐらい通行するかということを交通量をはかるような改革をしているところではありますが、感覚的には、歩行者、自転車ともに。","voiceIndex":386,"id":"exchange-170"},{"speaker":"渡辺委員","kind":"質問","question":"私は、１５８ページ、水辺の利活用と、あと、その隣１５９ページ、しながわ水族館あるいは区民公園のところを伺いたいと思います。だとしたら、今後を考えたときに、どう手を入れていくかという中で、ソフト面の充実は継続されるということで、すごくいい質だと思います。必要性が来る、これは現状、来年２５周年を迎えるという中で、一般論も含めて、これはどういう展開をお持ちなのか教えてください。","respondent":"多並公園課長","answer":"大規模改修、それが今までは１,０００万円程度ずっと続けてきたところだったのですけれども、それがやはりここ老朽度が高くなってきているということで、管理しているサンシャインシティと話した中では、もう少し必要だということで、３,０００万円程度、今。","voiceIndex":390,"id":"exchange-171"},{"speaker":"渡辺委員","kind":"質問・要望","question":"やはり立地から言ったら、羽田という拠点から、品川駅の拠点から、やはりしながわ水族館、エプソンも含めてなのですが、自然に増えていく要素をどう取り込んでいくかで、一工夫あるとかなりの取り込みができるのではないかと。ＰＲ次第でまだまだ相当なのびしろもあるのではないかと思うので、現状の分析と今後の見通しを教えていただきたいのが１つです。この辺のグランドデザインの考え方も教えてください。","respondent":"多並公園課長","answer":"南地区も含めた全体的なグランドデザインですけれども、これにつきましても、今後、今の委託の中でも整理していっているところですけれども、また平成２８年度予算、今度の中で整理しながら、もう少し全体的にどういうふうに進めていかなければいけないかということは。","voiceIndex":392,"id":"exchange-172"},{"speaker":"渡辺委員","kind":"質問・要望","question":"かなり今いろいろご要望も含めて言ったのですが、すごく把握をされていて、その中で全体のバランスを考えられているのは十分承知していますので、引き続き検討をよろしくお願いします。水辺の利活用のところで、こちらの決算上のものはそれぞれ承知はしているので、最近の話として、８月に東京都が舟運事業のワーキングチームを発足させたという報道もありました。それをお願いします。","respondent":"和田河川下水道課長","answer":"区としての今後ですけれども、桟橋の活用につきましては、今度、五反田リバーステーションを今後数年かけて整備していく予定ですけれども、この活用も含めて、東京都の動きとも連携して舟運の活性化に向けて積極的に検討を進めていきたいというふうに考えているところです。","voiceIndex":394,"id":"exchange-173"},{"speaker":"渡辺委員","kind":"質問","question":"そんなものも今は５カ所ですが、拠点の具体名も挙げられましたが、まず２０２０年という節目に向けての抱負みたいなもので、最後、伺えればと思います。水辺をどうやっていく、具体的にどうやっていくか。そしてもちろん品川だけでなく、規制もあります、国や東京都と、やはり地域と一体となって、これぞまさにオール品川で臨んでいくものと思うのですが、その辺の方向性を教えてください。","respondent":"和田河川下水道課長","answer":"基本的には、庁内連携して、商業、ものづくり、それから文化・観光、この辺もあわせて河川下水道課もハード整備という任務を背負っておりますけれども、ソフトについては各課連携のもとで、今後、舟運が活性化するように区としても頑張っていきたいというふうに考えてあります。","voiceIndex":396,"id":"exchange-174"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1412#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":120633,"voices":398}},{"id":"h27-20151014-4","meetingId":"h27-c-settlement","date":"2015年10月14日","dateIso":"2015-10-14","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時２５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を174件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 ただいまから、決算特別委員会を開会いたします。 平成２６年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 ただいまから、決算特別委員会を開会いたします。 平成２６年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問","question":"おはようあります。よろしくお願いします。私からは、成果報告書の１６９ページの８３運動経費、関連しまして家庭訪問についてお伺いします。家庭訪問についてお聞きいたします。","respondent":"村尾教育総合支援センター長","answer":"家庭訪問についてです。今、委員がおっしゃられたとおり、家庭訪問ですが、まさに子どもたち、児童・生徒理解を深めるという点、そして学校と家庭との連携を図るという点です。現在、実情といたしまして、品川区では基本的に全小・中学校において家庭訪問を実施しています。","voiceIndex":4,"id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問","question":"具体的に現在の状況といいますか、全校、学校によって同じことを、家庭訪問をやっているのか、やっていないのか、その辺のところを教えてください。","respondent":"村尾教育総合支援センター長","answer":"具体的な実施の方法ですが、学校によって多少の違いがあります。例えば、各家庭によって玄関先で家庭訪問をするという方法、それから、実際に家庭の中に入ってそれぞれお話を聞くというような、さまざまな状況があると認識しています。","voiceIndex":6,"id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そういった中で、その中で教員同士の家庭訪問についての状況の把握とか、そういった情報交換はできているのでしょうか。これがまず一点と、また保護者から家庭訪問の辞退があったときの措置はどうしているのでしょうか。よろしくお願いします。","respondent":"村尾教育総合支援センター長","answer":"２点目、保護者の辞退につきましては、いずれにしても予定変更して、できるだけ家庭へ訪問を行っておりますけれども、それができない場合につきましては、後日、学校のほうに来ていただくなり、またどうしても時間がとれないという方につきましては。","voiceIndex":8,"id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問","question":"旗台小学校で言いますと、家庭訪問のときに玄関先まで行きまして、いらっしゃらない場合は、お留守なのでというメモ書き、メッセージを入れておくということなのですけれども、再度お聞きするのですけれども、全校において、そういうやり方、同じやり方ではないという理解でよろしいでしょうか。","respondent":"村尾教育総合支援センター長","answer":"ほかの学校につきましては、事前に保護者に時間帯設定を伝えて、そこにお伺いするということで、それぞれ学校でやり方は少し違いがあります。ただ実際には、保護者の要望というか保護者の意見を十分聞いた上での家庭訪問を心がけているところです。","voiceIndex":10,"id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問","question":"家庭訪問というのは、品川区として同じ取組み方という、同じことというのはできるのでしょうか。それともできないのでしょうか。当然、大規模校、小規模校がありますけれども、その辺を含めて今後の対応をお聞きいたします。","respondent":"村尾教育総合支援センター長","answer":"それぞれ学校の規模、また学校選択をしていますので、やはり広範囲にわたるということで、時間設定等も大変学校のほうでは苦労している部分がありますけれども、やはり家庭、保護者の方とお話をしたり、また一つには子どもたちの状況、また家庭への学校の情報等を伝えるため。","voiceIndex":12,"id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ、今後も保護者と顔合わせをしていただいて、これからも指導、児童理解に役立てていただきたいと思います。よろしくお願いします。続きまして、１６９ページの８３運動経費についてお伺いいたします。２００５年から活動している８３運動、私も当時、ＰＴＡ会長でした。小学校ＰＴＡ連合会のお声がけで始まった８３運動の現在の活動状況、ＰＴＡ活動について教えてください。","respondent":"品川庶務課長","answer":"自転車で交通事故等が起こったときもございまして、そういう意味もありまして、自転車用の安全シールというものをつくっております。それ以前につきましては、缶バッジとかリストバンドとか、そのようなものをつくりまして、この運動の啓発に努めているところです。","voiceIndex":14,"id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問","question":"今おっしゃられた自転車用シールというのは、全校、全児童に配布しているものなのでしょうか。お聞きします。よろしくお願いします。","respondent":"品川庶務課長","answer":"対象ですが、区立小学校の全員の児童に対してこのシールを配っているというものです。","voiceIndex":16,"id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問","question":"時間が少しあるので、１６９ページ、校庭開放についてお聞きいたします。そうしますと、やっぱり保護者の方が２名、見守りとか当番でいらっしゃいまして、実際、来ているのは二、三人程度。前もお伺いしたときにも二、三人程度という、非常に何か少ない状況なのですけれども、これは今後の対応をどういうふうに考えているのでしょうか。よろしくお願いします。","respondent":"品川庶務課長","answer":"校庭開放の件ですが、ＰＴＡ等、いろいろな方々が中心となって校庭開放をしている状況です。参加人数が少ない等、そういう課題等ありましたら、いろいろこちらのほうでも役員・校長会等も通じまして検討していきたいと考えております。","voiceIndex":18,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"私からは、１６７ページ、プラン２１推進事業、１６９ページ、特別支援教育費について質問いたします。先日も衛生費のところで、がん検診の受診率のことを質問いたしました。そこで３点、質問いたします。そして３つ目には、品川区が現在使用しております小・中学校の教科書の中の、がんについてはどのような内容で、その学習時間はどれぐらいを要しているのか、教えていただきたいと思います。","respondent":"村尾教育総合支援センター長","answer":"それで、がん教育に関する予算というのは具体的に計上はしておりませんけれども、今後、本年度、それぞれ研修、また研究を進めながら、どのような形で進められるか、そこにもし予算が発生するのであれば、予算要求を考えているものです。","voiceIndex":21,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"会派といたしましても、がん教育、一般質問等でも取り上げている中で、なかなか進んでいない現状に残念な思いがいたします。例えば東京では、豊島区が平成２２年にがん対策推進条例を制定しております。品川区でも、学校の授業と、そのがん教育とともに、このようながん教育が開催できることを要望いたしますが、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"今、委員のほうからご案内があったとおり、がんについて、本年度、先ほど申し上げたとおり、ＤＶＤを使いながら学校のほう、特に養護教諭を中心に、どのような学習形態がとれるか、またどのような、テキストまではいかないのですけれども、指導案をつくったり。","voiceIndex":23,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"今後、この義務教育の時代に、がんのことを知っていく、また予防の大事さをしっかりと学ぶ場をつくっていただきたいと思います。次に移ります。特別支援教室についてお伺いいたします。事務事業概要に、本年度、モデル実施をするということが出ておりましたけれども、このモデル実施をされての現状と、また課題がありましたら、教えていただきたいと思います。","respondent":"村尾教育総合支援センター長","answer":"そうすると、週１回の通級の学習だけではなく、それ以外の授業においても、授業中の担任の声がけや対応の仕方等も、それぞれ通級の先生からの助言等がありまして、子どもたちにとって大変よい環境づくりが進んでいるというふうに聞いているところです。","voiceIndex":25,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"先日、私は、こんの委員とともに、大阪市住吉区の市立大空小学校を視察してまいりました。ここは、映画にもなりました『みんなの学校』のモデルとなった小学校で、全ての子どもに居場所がある学校をつくりたい。今後、品川区は、障害のある子と健常者が同じ教室で学ぶという特別支援教室でありますけれども、どのような方向性を持っているのか、どのようにしていきたいのかお聞かせいただきたいと思います。","respondent":"村尾教育総合支援センター長","answer":"区といたしましては、当然、来年度から特別支援教室を各学校に配置し、まず第一段階として、個々の発達障害等、配慮の必要なお子さんに対して、個別のニーズ、どのようなニーズが必要であるか、またそのためには学校の組織、また区。","voiceIndex":27,"id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"全ての子どもたちが、この学校生活の中で、伸び伸びと生活ができる。そのような、東京の中でも先進事例となるような学校づくりを要望いたしまして、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、１６５ページ、教育委員会運営費にかかわって教育大綱について、１６６ページのプール指導費にかかわって伊藤学園プールの一般開放再開を求めて質問したいと思います。統廃合についてですが、これまでに総合教育会議が２回開かれました。教育委員会定例会において、この素案の案について議論を行う、議論を深める、こうした定例会というのは予定されているのか伺いたいと思います。","respondent":"柏原企画調整課長、品川庶務課長","answer":"総合教育会議での発言ですけれども、今、委員のご指摘のあった部分について、特別何かそこの議論といいますか、意見が出たというところはございません。教育大綱の素案につきましては、教育委員会のほうでも議論をしている状況です。","voiceIndex":31,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"教育委員会定例会の中で、この素案の案について議論をする、議論を深める、そうした議案というのか議題というのか、そういう予定があるのかという点を伺ったので、後でご答弁いただきたいと思います。総合教育会議に教育長も出席していますが、ここの「検討します」について、つまり中島教育長は学校統廃合を進める考えなのか、それとも違うのか、ここを伺いたいと思います。","respondent":"品川庶務課長","answer":"今後の学校の統廃合のあり方ですけれども、昨今、就学人口の動向もいろいろ変化しています。それから、校舎の老朽度、それから国や都の動向ですね。こういうものによりまして、学校の配置のあり方というのは検討していくものだと考えています。","voiceIndex":34,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"この大綱の計画期間は３年間です。今、検討しますということですけれど、要するに案にある、「良好な教育環境の確保のため、就学人口の動向を見据え、校舎改築や学校配置のあり方について検討します」とは、一体何を検討するのか。中島教育長は学校統廃合を進める考えなのか、それとも違うのか、検討の中身をご説明いただきたいと思います。","respondent":"品川庶務課長","answer":"こういった学校改築も、今後、就学人口の動向や周りの状況等も見てやっていかなければいけないということで、そういう中で、国や都もどのように動くかという動向もやっぱり見ていかなければいけないということで、そういう面を総合的に判断しまして。","voiceIndex":36,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"配置のあり方の検討というのは、学校統廃合を検討しているということなのか、そこを伺いたいと思います。","respondent":"品川庶務課長","answer":"あくまでも、教育大綱に書いてありますように、配置のあり方です。","voiceIndex":38,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"配置のあり方とは何かと伺っているので、ご説明ください。","respondent":"品川庶務課長","answer":"教育大綱の中には、統廃合というような記載は特にございません。あくまでも配置のあり方という記載をしています。","voiceIndex":40,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"かつて、学事制度審議会の設置が教育委員会定例会で議論されたとき、「小規模校にレッテルを張るものだ」との議論が教育委員より出された経過があります。審議会の答申は出ましたが、当時の教育次長は、「答申は小規模校の学校を廃校しろ、統廃合しろということを基調に書かれているものではない」との答弁です。これは今も変わらないのか伺いたいと思います。そういうことです。","respondent":"品川庶務課長","answer":"現在の小規模校のあり方についてですが、例えばＩＣＴタブレットを配付するとか、そういった小規模校支援というのを現在行っているところです。学事制度審議会というものですが、これもやはり今後の就学人口等の動向を見ながらやっていくものだと考えております。","voiceIndex":42,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"いまいち教育委員会が何を考えているのかよくわからないのですけれども、今度、パブリックコメントも今月から始まります。この「検討します」について、良好な教育環境の確保のために校舎改築や学校配置のあり方を検討する必要がある問題とは一体何か。古くなった建物を新しくすることはよくわかります。この学校配置のあり方を検討する必要がある問題とは何か。そこをご説明いただきたいと思います。","respondent":"品川庶務課長","answer":"こういったものを改築していくということをまず一つ挙げているものと、それから、昨今の就学人口の動向等、いろいろ世の中の動き、そういうものがあったときにどうしていくかを検討していくというものです。","voiceIndex":44,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"それをなぜこの３年間の計画期間で行うのか、そこを伺いたいと思います。つまり、「良好な教育環境の確保のため」と書きながら、一体何が問題なのかが不明なままに、学校配置のあり方などと、要するに統廃合を進めるような議論は、私は行うべきではないと思いますけれども、いかがでしょうか。ぜひ削除を求めるべきだと思いますが、あわせてご説明ください。","respondent":"品川庶務課長","answer":"就学人口について、増えたらどう、減ったらどうというものを明記するものではございません。これはあくまでも社会情勢をもとにして、今後どのように学校の配置のあり方をやっていくかということを考えていくと。そのような表記としてこのような書き方をしています。","voiceIndex":46,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"社会情勢とは何か。一体何が問題で進めようとしているのか。ここが不明なまま進めるとは、私は統廃合ありきの議論ではないかと思いますけれども、その社会情勢とは何かご説明いただきたいと思います。","respondent":"品川庶務課長","answer":"今後の世の中の動きですので、これをどうこう予想してというところはあるかとは思いますが、これがどのように動くかというようなものはわかりません。そういった動きを見ながら統廃合というか学校の配置のあり方について考えていくと。このような表記をしているものです。","voiceIndex":48,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"私は、大義も、何が問題かも説明できない、こうした統廃合ありきはやめるべきだと思います。子どもの人口は、今の人口を下回るのは四半世紀先です。それで、この３年間の大綱に統廃合を検討する必要は私は全くないと思います。ぜひ総合教育会議に出席している中島教育長は、この一文の削除を総合教育会議で発言すべきではないかと思いますが、いかがでしょうか。","respondent":"品川庶務課長","answer":"今後３年間というところで、これに関しましては、いろいろな計画等、それに合わせた形で更新していくというふうに考えております。ですので、今後これは、本当に繰り返しになりますけれども、就学人口等、いろいろな情勢を見ながら考えていくものと考えています。","voiceIndex":50,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"いろいろご説明していますけれども、就学人口については先ほど言ったように四半世紀後のことだと指摘をすると、「人口の問題ではない」と言い、社会情勢が問題だと言って、それは何かと言ったら、「どのような動きになるのかわからない」と言い、結局、一体何が問題で検討が必要なのかしっかりとご説明いただきたいと思います。","respondent":"品川庶務課長","answer":"これは、社会の動きがわからないと判断ができない部分もあります。そういったところも予想して書いている表記です。","voiceIndex":52,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"そろそろまとめますけれども、そんな一般論で子どもから学校を奪わないでほしい。地域から学校を奪わないでほしい。これまで学校が果たしてきた、子どもへの役割、地域への役割、そこを、もちろん現場でいろいろかかわっている方は、私は強くいろいろ感じているとは思うのですけれども、そんなことを、そんな一般論で統廃合を進めるなんて私は間違っていると思いますので、改めてこの点を伺いたいと思います。","respondent":"品川庶務課長","answer":"これは解釈の問題になるかもしれませんが、とにかく、「統廃合」というような表記は一切しておりません。今後の学校の配置のあり方についてという表記をしておりますので、そこの部分をお間違えないようにしていただきたいと考えています。","voiceIndex":54,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"そんな一般論で子どもや地域から学校を奪うような統廃合はぜひやめていただきたい。その議論はやめていただきたいと強く要望して次に行きたいと思います。今年２月の本会議で、私は、「建物全体を直さない限り抜本的な解決は難しい。そこで改めて一般開放再開について、まずは学校が使っている時期について、夜や土日などあいている時間の一般開放を求めますけれども、いかがでしょうか。","respondent":"品川庶務課長","answer":"ある時期について一般開放するというのは、非常にこれは区民にとって混乱を生じやすいやり方かと思います。通年開放できるようなやり方で区民に開放する。このようなやり方が一番よろしいのではないかと考えております。","voiceIndex":56,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"ある時期だけ開放すると混乱すると言ったのは、その根拠は一体何なのでしょうか。私の母校でもある冨士見台中学校は、いつも夏、夕暮れどきも含めて、毎年のように一般開放を地域の人にやっておりますけれども、その根拠を伺いたいと思います。ぜひ再開を改めて求めますが、いかがでしょうか。","respondent":"品川庶務課長","answer":"それで、かわりにこれは豊葉の杜学園のプールを一般開放しまして、代替えというような形で区民の方にはプール施設の開放をしていますので、伊藤学園のほうのプールの開放を今後する予定はございません。","voiceIndex":58,"id":"exchange-027"},{"speaker":"木村委員","kind":"質問","question":"私からは、１６６ページの中央にあるスクールカウンセラー等派遣費についてお聞きいたします。スクールカウンセラー１７名、５,４６０万円余となっていますけれども、どのようなシステムになって１７名を派遣するのか教えてください。","respondent":"村尾教育総合支援センター長","answer":"スクールカウンセラーのお尋ねです。１７名の配置につきましては、平成２６年度におきましては、各小学校に週１回配置し、児童・生徒へのカウンセリング、また教職員、保護者に対する児童・生徒理解に関する助言等々の業務を行ってきたところです。","voiceIndex":61,"id":"exchange-028"},{"speaker":"木村委員","kind":"質問","question":"９歳から１２歳の子どもたちですから、どのような悩みを持って、またどのような相談事が大変多いのかということもお聞かせください。認識しておりますけれども、いかがでしょうか。小学生はとても繊細で、何事も吸収し成長していく大変大事な時期ですから、大変扱いづらいのかもしれませんけれども、どのようなことに注意し、子どもたちに対応しようと考えているのでしょうか。お聞かせを願いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"平成２６年度の結果なのですが、一番多いのは、自分の性格とか、そういうことについての相談をするケースが多く、その次には、雑談というのですか、話し相手になってほしいということで話しにくるという、その対応が多くございました。","voiceIndex":63,"id":"exchange-029"},{"speaker":"木村委員","kind":"質問・要望","question":"頑張っていただきたいと思います。協議内容等を、差し支えない程度でお話しいただきたいと思います。いじめは今始まったことではありませんけれども、学校でのいじめ防止対策には、先生方の関与というものが大変必要だと考えていますけれども、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"いじめ根絶協議会についてです。これは、平成２５年度に設置いたしました、年３回、各学期ごとで実施しているものです。","voiceIndex":65,"id":"exchange-030"},{"speaker":"木村委員","kind":"質問","question":"少し話がそれますけれども、私たちの頃の先生方というものは、私たち生徒に対する態度が大変、毅然としていたと思います。規律を守らない生徒や、いじめをはじめとする諸問題に対し、だめなものはだめ、態度が悪いと怒られ、言うことを聞かないと殴られたりもしました。先生の役割とは学問だけを教えていればいいというものではないと私は思っていますけれども、お考えをお聞かせください。","respondent":"村尾教育総合支援センター長","answer":"同時に、いじめ防止だけではなく、やはり思いやりや優しさというところもすごく重視しながら、教師は子どもたちと日常的に意図的に積極的に声がけをしたり、また放課後、少し相談に乗るような場面も多くつくりながら。","voiceIndex":67,"id":"exchange-031"},{"speaker":"木村委員","kind":"質問・要望","question":"先生だけが悪いと言っているわけではございませんし、もちろん家庭での両親のしつけが一番大事。教育長にお伺いしたいのですけれども、教育長自身が子どもの頃ご両親や先生方から厳しく育てられた、教えられたことが、社会人としての土台になっていることと思います。ぜひ、少しでも昔の強い先生、学校教育を復活させていただきたいと思いますが、教育長のお考えをお聞かせ願えれば大変うれしく思います。","respondent":"村尾教育総合支援センター長","answer":"保護者の、やはりさまざまな方がいらっしゃいます。それに対して学校も当然いろんな部分で対応に苦慮する場面もありますけれども、ただ、やはり子どもたちの姿を見ながら、保護者もわかってくれるというふうなところで進んでいるところです。","voiceIndex":69,"id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"私からは、１６６ページ、いじめ防止対策費、１６７ページ、マナーキッズ教室、１６９ページ、グローバル人材育成塾、１７５ページ、給食食材放射性物質検査費についてお伺いしたいと思います。いじめ防止対策費についてお伺いします。対策前と比べて、その効果はどのぐらい出たのでしょうか。いじめ認知件数は減ったでしょうか。お伺いいたします。","respondent":"村尾教育総合支援センター長","answer":"ただ、これはあくまでも認知件数でございまして、いじめはやはり、いつどこでも起こり得るという前提に立つべきものであると考えておりますので、今後とも、このいじめ防止については進めて取り組んでいこうと捉えております。","voiceIndex":72,"id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひともよろしくお願い申し上げます。今後も、こうした区の取組み強化を含めて継続していただきたいと思います。続いて、マナーキッズ教室についてお伺いしたいと思います。それには、道徳、マナー教育が有効と考えております。したがって、マナーキッズ教室を行うことは大変よいことだと考えておりますけれども、このマナーキッズ教室の内容およびその効果を簡潔にお聞かせください。","respondent":"村尾教育総合支援センター長","answer":"マナーキッズ教室の実施の内容ですけれども、実際には、まず１点目として、小笠原流の師範の方が基本的に中心で来られまして、おじぎ、また挨拶の仕方、またその心構え等を子どもたちに指導していただきます。","voiceIndex":74,"id":"exchange-034"},{"speaker":"筒井委員","kind":"提案","question":"大変よい教室だと考えています。提案ですけれども、社会のグローバル化、そしてオリンピック・パラリンピックもありますので、一歩進んで、西洋式マナーや国際マナーも取り入れるような工夫をぜひとも行っていただきたいと考えております。そこで、現在のカリキュラムを拝見しましたけれども、もう一歩進んで、もっと日本の歴史・文化の講座を取り入れてみてはいかがでしょうか。","respondent":"渋谷指導課長","answer":"ただ、本区では、市民科等で、例えば全員で、茶道を学んだりだとか、また琴を学習したりだとか、そういう機会を通して、日本を愛する心、伝統文化を守る心というものをしっかり育てておりますので。","voiceIndex":76,"id":"exchange-035"},{"speaker":"筒井委員","kind":"質問・要望","question":"総合的にコラボレーションを進めて、そうした品川区からグローバル人材を育てていっていただきたいと考えております。そして最後に給食食材放射性物質検査費についてお伺いいたします。私、この項目を見て、正直、非常に驚いたのですけれども、原発事故の本当に根深さを今もって痛感しております。そこで、まずこの検査内容と、他の区の実施状況をお伺いします。簡潔にお答えをお願い申し上げます。","respondent":"野呂瀬学務課長","answer":"各区の状況ですけれども、ヨウ素とセシウム測定につきましては、ちょっと２３区の状況は手元にないのですけれども、城南６区、品川を含めた近隣の区は全てやっているという状況です。それで、ストロンチウムにつきましては、これは品川区のみが実施しているというものです。","voiceIndex":78,"id":"exchange-036"},{"speaker":"筒井委員","kind":"質問","question":"ストロンチウムまで検査していただいて、本当に頼もしいことだと考えております。この放射性物質検査はいつから行われるようになったのでしょうか。検査導入の経緯、理由をお伺いいたします。","respondent":"野呂瀬学務課長","answer":"検査の導入時期ですけれども、先ほど申しました要素とセシウムの検査につきましては平成２３年度、いわゆる３・１１直後からやっております。ストロンチウムにつきましては平成２６年度からやっているものです。","voiceIndex":80,"id":"exchange-037"},{"speaker":"筒井委員","kind":"質問・要望","question":"親御さんもそのことを大変心配していると思いますので、今後も引き続き積極的にやっていただきたいと考えております。やはり、この日本は脱原発に向かって進むべきだと、私個人は考えております。品川区でも、脱原発依存に向けての環境づくりということで、再生可能エネルギーの促進を行っていただきたいと考えておりますけれども、品川区の再生可能エネルギーの普及の取組み状況はいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-038"},{"speaker":"筒井委員","kind":"質問","question":"そうですか。そうした自然再生可能エネルギーの、そうしたら、では教育はいかがでしょうか。再生可能エネルギーの区の教育。","respondent":"野呂瀬学務課長","answer":"再生可能エネルギーは、所管は環境課だと思うのですけれども、教育分野でも、例えば教育、学校の中で太陽光発電とか、それは普及しておりますし、昨今出来上がった御殿山小学校の中でも再生可能エネルギーに取り組むということで、品川区全体、一丸となって。","voiceIndex":84,"id":"exchange-039"},{"speaker":"筒井委員","kind":"質問・要望","question":"どうも失礼いたしました。どうもありがとうあります。ぜひともそうした教育に今後とも積極的に取り組んでいただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"そして１６７ページ、１項３目、小中一貫教育推進経費、そして１６６ページ、いじめ防止対策費について伺います。ＩＣＴ機器を活用した学習活動の推進について伺います。世界保健機構、ＷＨＯは２０１１年、携帯電話等の無線端末の電磁波と発がん性との関連性について、限定的ながら可能性があるとの見解を示しています。それで質問です。タブレットを使った授業の頻度はどの程度ですか。","respondent":"野呂瀬学務課長","answer":"昨年、タブレットを導入しまして、今年度ですけれども、１学期のタブレットの１日平均時間は大体６０分、約１時間ぐらいというふうに聞いております。","voiceIndex":88,"id":"exchange-041"},{"speaker":"田中委員","kind":"質問","question":"無線ＬＡＮを利用していることを保護者や生徒はご存じですか。","respondent":"野呂瀬学務課長","answer":"当然、これは昨年度やるとき、こういう形でやっていくということで、もちろん児童・生徒と、もちろん保護者にも周知したところです。","voiceIndex":92,"id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"無線ＬＡＮを利用している学校での無線ＬＡＮの設置場所が、２教室ごとに１台という間隔で廊下へ配置している。そして無線ＬＡＮを、先ほど１日平均６０分とのことでしたが、常時つけっ放しで、オフにすることはないということを伺いました。そして、電磁波を避けるためのルールを教育委員会として定め、学校に徹底してほしいと考えますが、教育委員会のお考えを伺います。","respondent":"野呂瀬学務課長","answer":"ですけれど、授業なので、その頻度とか何かにつきましては、電磁波一つに絞るのではなくて、全体の中で活用していくような形で、今でも学校はそれは考えておりますし、今後もそういう形で進めていきたいと思います。","voiceIndex":94,"id":"exchange-043"},{"speaker":"田中委員","kind":"質問","question":"今、電磁波の話をしていたので、電磁波のことを伺いました。電磁波を避けるためのルールを教育委員会として定めていただけたらうれしいです。次に、小中一貫校の推進について伺います。平成２６年１０月に小中一貫教育全国サミットにおいて、全国連絡協議会代表幹事としての区の取組みを全国に発信したとありますが、品川区の方針に対する全国からの評価はどのようなものでしたか。簡単に教えてください。","respondent":"渋谷指導課長","answer":"品川区ですが、今、小中一貫教育は全国に広がりつつあります。多くの地方自治体の方が品川区にお見えになって、品川区が考えている小中一貫教育のあり方について、さまざま評価の声をいただいているところであります。","voiceIndex":96,"id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"生活者ネットワークは卒業生の聞き取りを過去にも求めています。最後に、いじめ防止対策について伺います。平成２５年度に、いじめ根絶協議会が発足されましたが、先ほどの木村委員との質問ともかぶるかもしれませんが、どのような目標を掲げて何を協議する協議会なのかをお聞かせください。そして、協議会のメンバーの中に弁護士の方はいらっしゃいますか。それも重ねてお願いいたします。","respondent":"村尾教育総合支援センター長","answer":"先ほども申しましたとおり、昨年度はスマートフォンを使ったいじめ防止ということで、やはりＬＩＮＥ等、さまざま社会的にも問題になっている部分をテーマに協議してまいりました。メンバーの中に弁護士は特には含まれてはおりません。","voiceIndex":104,"id":"exchange-045"},{"speaker":"田中委員","kind":"確認","question":"そうなのですね。では、目安箱や相談電話については先にヒアリングで確認させていただいたところ、両方とも数は減少していたということでした。そして、いじめに関しての相談は、トータル的に見て少ないとも伺いました。そのことについては、どう受けとめておられますか。いじめが減少したと受けとめるか、それともその逆か、どうでしょうか。","respondent":"村尾教育総合支援センター長","answer":"ただ、目安箱の数が減ったからといって、イコール、いじめが減少しているというふうには捉えているところではございません。引き続き、やはりいろんなアンテナを高くしながら、子どもたちのいじめ防止に向けて進めているところです。","voiceIndex":106,"id":"exchange-046"},{"speaker":"田中委員","kind":"提案","question":"私も正直、いじめが減少したとは考えにくいと、やはり考えています。だから、できれば毎月１回、全校生徒が一斉に投稿する日をつくり、実施することを提案したいと思います。みんなが一斉に投稿する日を決め、投稿したら、誰が何を密告、そういうことも判断しにくくなりますので、子ども的にはすごく、目安箱に対する抵抗も和らぐと考えるのでいかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"委員のおっしゃる、一斉に投函ということは、ちょっと今、考えている部分はないのですが、やはり目安箱だけではなくて、子どもたちには生活アンケートであったり、さまざまなところで、実際に言い方、目安箱には入れられないのだけど、これだったら先生に伝えられるとか。","voiceIndex":108,"id":"exchange-047"},{"speaker":"田中委員","kind":"意見","question":"なので、本当に子どもの視点から、子どもが本当に相談しやすい環境づくりというのを、今後もつくっていってほしいと思います。そして先ほど、協議会の中に弁護士の方がいらっしゃらないということだったのですけれども、子どもたちがいじめについて議論する機会や、人権・法律について学ぶ機会を増やしてほしいと考えます。そのために、法律のプロ、弁護士の協力が必要だと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":110,"id":"exchange-048"},{"speaker":"横山委員","kind":"質問","question":"私からは、１６６ページ、スクールカウンセラー等派遣費、いじめ防止対策費、１６８ページの国際理解教育、１６９ページ、特別支援教育費、図書館経費についてお伺いいたします。図書館経費についてお伺いいたします。利用件数を教えてください。","respondent":"木村品川図書館長","answer":"障害者サービスのお問い合わせです。具体的に対象といたしましては、肢体不自由の方、歩行困難等のご理由により来館が困難な方という形になっております。昨年度の利用実績ですが、合計で９８３冊の自宅配本を行っておるところです。","voiceIndex":112,"id":"exchange-049"},{"speaker":"横山委員","kind":"質問","question":"来館が困難な方ということで、幅広く、今、定義をいただいたのですけれども、昨年は９８３冊ということでお伺いいたしました。区民の方より、来館が困難な高齢者ですとか、有料サービスでの宅配サービスを実施してほしいという声をいただいておりますけれども、区の考えをお聞かせください。","respondent":"木村品川図書館長","answer":"今のところは有償での宅配のサービスというところは考えていないところですけれども、そういうお声をこれからいろいろお聞きしながら、まだ研究を続けていきたいと思いますので、よろしくお願いいたします。","voiceIndex":114,"id":"exchange-050"},{"speaker":"横山委員","kind":"質問・要望","question":"声をお聞きして研究を続けていただけるということで、高齢者の方で、どうしても図書館のほうに伺えない方ですとか、お困りになっている方もいらっしゃいますので、ぜひ前向きに研究をしていただけたらと考えています。次に、特別支援教育費についてお伺いいたします。特に発達障害の特性のぶつかりに関して、どのようにモデル実施の際には対応していたのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"そういうところと連携を図りながら、それぞれの対応する内容、それから指導の方法について考えているところです。発達障害の部分です。","voiceIndex":116,"id":"exchange-051"},{"speaker":"横山委員","kind":"質問","question":"発達障害の特性のぶつかりの部分なのですけれども、特性が違う児童が１名の方から同時に指導を受けるというケースというのはあるのでしょうか。それで、その場合、もしあるのであれば、特性の違いによる対応を時間差でしていただくとか、何かそういった対応はしていらっしゃるのかお聞かせください。","respondent":"村尾教育総合支援センター長","answer":"実際に個別対応というのを基本に来年度から考えておりますけれども、やはり学校におきましては、１人の教員に対して複数で対応することも十分考えられます。","voiceIndex":118,"id":"exchange-052"},{"speaker":"横山委員","kind":"質問・要望","question":"それぞれの個性、特性を捉えていただきまして、個別の対応を丁寧にお願いできればと思います。要望だけします。次に、スクールカウンセラー等派遣費についてお伺いいたします。研修、またケース会議や連絡会など、参加する会議の違いによって、知識の差が出てくるかと思うのですけれども、福祉部門と教育部門との連携という視点からもご説明をお願いいたします。","respondent":"村尾教育総合支援センター長","answer":"ただ、区のスクールカウンセラーにつきましては、もちろん区の教育委員会からの派遣ということがありますので、実際に区が取り組んでいる特別支援教育、特にインクルーシブに関係する合理的配慮等、その辺を十分、踏まえた上で。","voiceIndex":120,"id":"exchange-053"},{"speaker":"横山委員","kind":"質問・要望","question":"区費のカウンセラーの方、都費のカウンセラーの方、それぞれお持ちの資格の違いなどもあるかと思いますので、区の大事な情報ですとか、そういったもの、十分、連携をとっていただけるように、今後ちょっと強化していただきたいのですけれども、もう一度その点をお願いいたします。","respondent":"村尾教育総合支援センター長","answer":"巡回相談員、こちらからさまざまな、発達障害を含めて、これからの特別支援教育についての考え方を伝えておりますので、巡回相談員から都費のスクールカウンセラーに、いわゆる伝達講習みたいなものも今後とも進めていこうと考えているところです。","voiceIndex":122,"id":"exchange-054"},{"speaker":"横山委員","kind":"質問","question":"学校の保護者会などでは、携帯電話の利用のルールを家庭できちんとお話しになってくださいというようなプリントですとかご案内、学校からのご説明もいただいてはいるのですけれども、家庭と学校が一体となって、携帯電話やスマートフォンを利用したいじめを防止するために、家庭と学校、それぞれの役割を、品川区はどのようにお考えになっていますでしょうか。","respondent":"村尾教育総合支援センター長","answer":"教員につきましては、全学校の情報担当教諭を集めて、情報モラル研修も行いながら、学校、それから子どもたちへの教育を行っているところです。","voiceIndex":124,"id":"exchange-055"},{"speaker":"横山委員","kind":"質問・要望","question":"要望だけします。最後に、国際理解教育についてお伺いいたします。平成２７年５月１４日なのですけれども、第７次提言において、これからの時代に求められる資質・能力と、それを培う教育、教師の在り方についてということで、国際バカロレア認定校を大幅に増加させるです。","respondent":"渋谷指導課長","answer":"今後、国の学習指導要領が改訂されまして、そのときにどんな扱いになるのか、そういったものを注視しながら、私どもも十分に研究してまいりたいと考えているところです。","voiceIndex":126,"id":"exchange-056"},{"speaker":"横山委員","kind":"意見","question":"こうした国の国際バカロレアに対しての動きにも注視していただきまして、例えばなのですけれどもグローバル人材育成塾ですとか、国の動きに先んじて、何か品川区でも一部のプログラムですとか、また国際的な視野を持つ人間の育成、英語の教育だけではなくて、英語を使った人間教育、人間性の教育という視点で、今後ちょっと検討していただけたらなと思うのですけれども、その点もお聞かせください。","respondent":"渋谷指導課長","answer":"玉川学園中等部・高等部、それから東京学芸大学の附属の国際中等教育学校、また都立国際高校等、いずれもやはり選抜を経てきた子どもたちを対象にしたプログラムで、品川区の中でグローバル等を希望する子どもたちにそういったものが提供できるのかどうかということも。","voiceIndex":128,"id":"exchange-057"},{"speaker":"横山委員","kind":"質問","question":"中学校におきまして、英検の補助のほうをしていただいているかと思います。ちょっとまだ始まったばかりかと思うのですけれども、その導入によってどのぐらい件数が変わっているのか、パーセンテージでも構いませんけれども教えていただけたらと思います。","respondent":"野呂瀬学務課長","answer":"これは補正予算で組んで、今、１０月、先週の土日で試験があったので、これから結果が出ると思いますので、それを見守っていきたいと思います。","voiceIndex":130,"id":"exchange-058"},{"speaker":"横山委員","kind":"質問・要望","question":"１０月と、あと３学期にもまた試験があるかと思いますので、その辺、保護者の方からすごく喜びの声が入っております。そちらのほう、ぜひ今後とも進めていっていただけたらと考えています。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-059"},{"speaker":"つる委員","kind":"質問・要望","question":"１６５ページ、教育指導費について伺っていきたいと思います。先ほど前半戦の議論の中で学校の配置がどうこうというような議論もある中、ハード面、そこがどうこうというよりも、あくまでも視点は、子どもたちにとって最善の環境がどうあるべきなのか。非常にすばらしいなと思いました。そうした意味において、今現在、品川区がどのような形で主権者教育に取り組んでいくのか、そのあたりを教えてください。","respondent":"村尾教育総合支援センター長","answer":"７年生については、市民としての義務や責任、また８・９年生においては、社会の一員としての活動ということで、市民科の教科書の単元２６番には、「品川区議会だよりを読んだことがありますか」からスタートし、子どもたちに学習、こういう社会、また政治について。","voiceIndex":134,"id":"exchange-060"},{"speaker":"つる委員","kind":"質問","question":"すみません。１個だけ具体的に、憲法の学習というのはどの段階でされるのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"憲法ですけれども、憲法につきましては、６年生の社会科、私たちの暮らしと憲法はどのようにつながっているかという６時間扱いの単元で憲法というものは最初に出てきます。同様に、市民科の中においても、憲法が保障する基本的人権等の単元もあります。","voiceIndex":136,"id":"exchange-061"},{"speaker":"つる委員","kind":"確認","question":"これも既に取り組んでおられると伺っております。質問させていただいている、平成２６年度は社労士の方をお招きして、６年生を対象に行ったり、また市民科で、今ご答弁いただいたような社会とか税の仕組みについてもやっているということでありますが、改めて平成２６年度の取組みと、それから今現在、今年度、どういうふうにして取り組んでいるか教えてください。","respondent":"村尾教育総合支援センター長","answer":"実際には平成２７年度は３校の学校で、社労士の方を迎えての社会保障、また税の部分につきましては租税教室ということで全校で実施しながら、さまざまな、社会保障の部分については、小学校、また中学校の段階ですので基礎だとは思いますけれども、進めているところです。","voiceIndex":140,"id":"exchange-062"},{"speaker":"つる委員","kind":"質問・要望","question":"なかなか社会の仕組み、税の仕組みというのは、大人が聞いても難しいと思います。本当にわかりやすい授業をこれからもやっていただきたいと思います。これは社会保障教育の欠如による一因なのだと。最後に、教育指導費という枠の中で、教育現場で笑いを活かす、また活用する、そうした取組みがあるかどうか教えてください。","respondent":"村尾教育総合支援センター長","answer":"その点で言いますと、市民科等で感情のコントロール、そういうような学習を含めてストレスを発散する。教師も同じく、やはり職員室内での人間関係も含めて、それはすごく大事かなというところはあります。","voiceIndex":142,"id":"exchange-063"},{"speaker":"つる委員","kind":"質問","question":"先ほど、どのような人材を輩出していくことが公教育のポイントなのかと冒頭伺ったのですが、ある元外交官の方が、やはり外交の場においても笑いのセンスというかユーモアのセンスは非常に外交交渉の中では重要なのだと指摘されておりました。私は、先ほど来出ているいじめの課題についての対応策の中で、自分の知り合いの芸人、いつでも呼んでくれと。これは私、すばらしい視点かなと思いました。","respondent":"渋谷指導課長","answer":"そういう中で、ユーモアに富んで、きちっと子どもたちに伝える能力、そんな観点から先生方の質・能力向上を図るような研修等々、検討できないかということを、また我々も考えていきたいと思っています。","voiceIndex":144,"id":"exchange-064"},{"speaker":"つる委員","kind":"質問・要望","question":"若い先生たちにはその番組を見るように勧めているというコラムが、品川区教育委員会、ある小学校の校長先生のコラムでかつて出されておりました。これを参考にしていただきたいと思いますし、いずれにしてもとにかく、繰り返しますけれども、教師こそが最大の教育環境だということで、どこまでも子どもの幸福のために、これからも教育委員会に頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"学校の隅々まで差別のない教育環境を整えていくために、日常的に障害者権利条約を位置付けていただきたいと願っています。インクルーシブ教育システム構築モデル事業、３年目になりますけれども、知的の特別支援学級の保護者から、同じ学校にいるのだから、もっと交流と共同の学習をして増やしてほしい。交流と共同学習の実践についてですけれども、具体的内容と課題をお知らせいただきたいと思います。","respondent":"村尾教育総合支援センター長","answer":"インクルーシブ教育を含めての交流、そして共同学習についてのお尋ねです。品川区においても、ご案内のとおり、平成２５年度からインクルーシブ教育をはじめ、品川区内での特別支援教育にすごく力を入れてきているところではあります。","voiceIndex":148,"id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問・要望","question":"課題も伺ったので、後で教えていただきたいと思います。実践の際の課題のところ、先に私、言ってしまいますが、ここに書かれていたのが、通常の学級の児童の障害者理解のための指導がすごく重要であるということと、人的な支援、これも大事ですよね。もう一点は、重要な教員の方々なのですが、教員の方々の障害への理解、資質の向上、どのようになっているか教えてください。","respondent":"村尾教育総合支援センター長","answer":"その教員が中心となりまして、研修を教育委員会で行って学校に戻り、その教員が今度、指導者ということで、それぞれ生活指導主任会であったり、また職員朝会等をうまく使いながら、さまざまな障害についての部分、特に間違えた対応をすることによって。","voiceIndex":150,"id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ですので、個別指導と小集団指導とを適切に組み合わせて教育を受けられるように、小集団の指導を大事にしていただきたいという声が届いていますので、これを一つお願いしたいのと、あと教育条件なのですけれども、拠点校が４校から８校に増えますけれども、この８校の学校の環境なのですが、東京都が独自につくってきた通級指導学級と同様の教員の配置。","respondent":"村尾教育総合支援センター長","answer":"１点目、質を落とさないでということは、まさに言われるまでもなく、それぞれ教育委員会として特別支援教室、平成２８年度から実施する部分につきましては、やはり今の通級よりもより一層、個々に応じた指導ができるようにということで、現在、それぞれの設置校の校長先生。","voiceIndex":152,"id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問・要望","question":"このことをよろしくお願いいたします。特に教員配置なのですけれども、現状のところを伺ったら、１０名で１学級という単位で、学級数掛ける１プラス１人の先生ということで、私が聞いたところは３人の教員の方で１０名の子どもを見て、学年が１年生から６年生までですので、いろいろなお子さんがいらっしゃる。それで、伺ったのですけれども、この点は大丈夫なのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"一つの教室に何名程度というところなのですけれども、これは学校によって、来年度どれぐらいの教室についての申請があるか、ちょっとまだわからないところがありますけれども、例えば１時間目から６時間目までというような単元でやっていきますので、毎日２時間目に３人。","voiceIndex":154,"id":"exchange-069"},{"speaker":"飯沼委員","kind":"確認","question":"教職員のところの配置は全く同じ考えでやられるということですよね。そういったことでは、一つの学校に、該当するお子さんがたくさん増えたりしたら、当然増えるという考えで、今のところ１８名で減ることはないとおっしゃったのですが、事によっては増えるという解釈でよろしいのでしょうか。ちょっとそこを確認させてください。","respondent":"村尾教育総合支援センター長","answer":"今後、教室についての申請の子どもたちが増えますと、当然、今の１８名、いわゆる１８０名になりますけれども、それ以上、増えた場合については、当然、加配の教員が区のほうに配置されると考えています。","voiceIndex":156,"id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問・要望","question":"多分、子どもたちは今、増えているという状況なので、その辺も予測して体制をとっていただきたいと思うのですが、８校に増えますけれども、拠点校以外の特別支援教室は、専用の教室とか、また息抜きできるような複数の教室の配置などあるのでしょうか。ちょっとその辺を教えていただきたいと思います。その辺はいかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"これについては各学校でいろいろ工夫をしながらということで、今言われたとおり、週２回しかつかない子もいるし、週に３回つく子もいますので、その障害状況に応じるということで、今、配置をしています。","voiceIndex":158,"id":"exchange-071"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、成果報告書１７４ページの学校給食費に関連して、学校における食物アレルギー対応についてと、１６９ページの病院内学級維持費負担金に関連して、さいかち学級についてお尋ねいたします。一部を再読いたします。ということは、品川区の学校における食物アレルギー対応は、食器の購入などの給食費以外にはほとんど経費をかけていないというふうに理解してもよろしいのでしょうか。","respondent":"野呂瀬学務課長","answer":"予算はついていないですが、アレルギー対応につきましては、全校一丸となって一生懸命やっている状況です。","voiceIndex":163,"id":"exchange-072"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"ご説明はわかりました。しかし、現在、小学生の２.８％が食物アレルギーを有しており、その最重症形であるアナフィラキシーを起こしたことがある児童・生徒も０.１５％と文部科学省より報告されております。区のほうにその点、十分ご配慮するように要望いたしまして次の質問に移ります。エピペンについてお尋ねいたします。今年度、エピペン講習は既に何回ぐらい実施されているのでしょうか。","respondent":"野呂瀬学務課長","answer":"６月末の時点で、小学校３１校、中学校が７校、校内研修の中で講習済みで、そのほかの学校につきましては、今年度、これからやっていくというふうに把握しております。","voiceIndex":165,"id":"exchange-073"},{"speaker":"鈴木（博）委員","kind":"質問","question":"知識を定着し深めるためには食物アレルギー研修会を定期的に継続的に何回も開催することが必要ではないでしょうか。研修後のアレルギー調査やアンケート調査や自己研修の記録というのは研修会の評価や参加者の意識の調査としても重要なデータになると思われますが、現在そのようなアンケートとか自己研修の記録提出というのは行われているのでしょうか。","respondent":"野呂瀬学務課長","answer":"研修した後のアンケートですが、これにつきましては、例えば小規模校、大規模校、それと除去食対応の児童・生徒数の数とか、これは学校によってまちまちで、学校によって差がありますので、アンケートについて統一的なものは実施しておりませんが。","voiceIndex":167,"id":"exchange-074"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今の課長のご答弁も踏まえて次の質問をしたいと思います。エピペンを誰が打つか、どのように管理するかは生徒・保護者だけに任せるのではなく、学校内アレルギー対応委員会が保護者、本人と話し合い決定するべきと思います。アレルギー対応委員会の役割が非常に重要と考えますが、品川区では現在どのようにこれは各学校で対応されているのでしょうか。","respondent":"野呂瀬学務課長","answer":"アレルギー対応委員会は全校で設置するように決まっているものですけれど、決して、委員がおっしゃった事例のように子ども任せとか児童・生徒任せにはしておりません。","voiceIndex":169,"id":"exchange-075"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それで、先ほどの課長のご答弁もそれに一致した結果だと理解しました。さいかち学級の小児がん、心臓病、それから脳神経疾患、ぜんそくなど、慢性に経過する病気の児童と、肺炎など短期で入院する急性の病気の児童で、さいかち学級に学ぶ児童の比率というのは、今見ると非常に少なかったみたいなのですが、簡単に、雑駁でよろしいのですが、どれぐらいの比率なのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"さいかち学級の入院している子どもの病状ですけれども、急性等で入院している子が全体の１２４名に対して４９名、それに対して慢性期等で入院している子どもたちは４７名、残り、その他ということで、子どもたちは入級しております。","voiceIndex":175,"id":"exchange-076"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、今のお話だと、大体１対１だというふうに理解してもよろしいでしょうか。それぞれの児童の特性を活かすという理解の上でどのような観点から教育をされているのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"当然、同じ教室で同じような学習内容ができるということはありませんので、特に慢性的な子どもについては、ベッドサイドでの学習等、その子に応じた個別対応を現在しています。","voiceIndex":177,"id":"exchange-077"},{"speaker":"鈴木（博）委員","kind":"質問","question":"品川区教育委員会が統括するさいかち学級と、実際、治療を行っている昭和大学病院の小児科とはどのような関係でどのような連携で子どもに接しているのでしょうか。簡単にご説明をお願いします。","respondent":"村尾教育総合支援センター長","answer":"そこにおいて、実際に昭和大学と教育委員会とで連絡協議会を設けたり、またそれぞれの状況に応じて、清水台小学校の担任２人を含めまして、子どもたちの今の現状、それから今後どのような形で必要な教育ができるかということにつきましては、まさにそれぞれ。","voiceIndex":179,"id":"exchange-078"},{"speaker":"鈴木（博）委員","kind":"質問","question":"病弱・身体虚弱な子どもは、病気・治療への不安、親や兄弟から離れて生活することへの不安、行動や生活が制限されていることへの不満、授業についていけるかどうかの不安というような、幾つかの不安・不満というのを抱えて生活しております。病弱・身体虚弱児と称される子どもが希望を持って明日に向けて生活できるよう、品川区のさらにきめ細かい対応をお願いして質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":181,"id":"exchange-079"},{"speaker":"西本委員","kind":"質問","question":"１６５ページの教育指導費の中から、不登校の実態についてお聞きします。これは国の予算の動向であるとかということが関係すると思うのですが、国の動向を踏まえて、理科教育に対しての品川区の見解をお聞きします。そして３つ目は１７５ページの給食食材放射性物質検査ですが、これの検査結果はどういう傾向にありますかということと、なぜ必要なのでしょうかということを聞きたいと思います。","respondent":"村尾教育総合支援センター長、渋谷指導課長、野呂瀬学務課長","answer":"私から、不登校の子どもたちの状況についての説明をさせていただきたいと考えています。現在、固有教員は、英語教育、それから市民科教育、理数教育という３つの分科会に分かれて、独自に品川区の理数教育の充実に根差した研修を実施しています。それと、なぜ必要かという部分は先ほどもお答えしましたけれど、やはり給食食材ですので、安全なものが出回っているという前提ですけれども、食材ですので。","voiceIndex":183,"id":"exchange-080"},{"speaker":"西本委員","kind":"質問・要望","question":"それで教員の採用もそれを中心にということで、将来的には品川区はやはり、理科教育、ものづくりというところでの大きな柱をつくってもいいのではないのかなというぐらい、理科教育には力を注いでいただきたいと考えていますので、これは要望としたいと思います。なぜやる必要があるのですか。２３０万円も税金をかけてやる必要はないと私は思っておりますが、それについてのご意見をお聞きします。","respondent":"村尾教育総合支援センター長、野呂瀬学務課長","answer":"一方的に登校刺激をあまり与えすぎるのもまた逆効果ということも、いろんな場面で考えているところです。この辺につきましては、本当に専門家というか心理職等を含めまして、こちらで本当に対応については考えていこうと考えています。今後につきましては、もちろんいろいろ社会状況を見ながら、適時適正に判断していきたいと考えております。","voiceIndex":187,"id":"exchange-081"},{"speaker":"西本委員","kind":"質問・要望","question":"不登校については、本当にこれからいろいろ考えていただきたいと思います。安心・安全と、それはわかるのです。弊害もあるんだということもしっかり考えていただいて、これは教育の場ですから、これからやるべきか、やらなくて済むべきなのか。これは社会情勢はもちろんありますが、しっかりとした判断のもとで対策をとっていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":190,"id":"exchange-082"},{"speaker":"大倉委員","kind":"質問・要望","question":"私から、１６６ページ、スクールカウンセラー、ソーシャルワーカーに関連して、あと体育館の非構造部材の耐震化で少し伺いたいと思います。子どもへの暴力防止プログラム、また時間があれば別途お伺いしたいと思います。体育館の非構造部材耐震化なのですが、現在、どのぐらいの学校が終わっていて、これからまた冬休みにかけて行われると思うのですが、どのぐらいされるのか教えていただきたいと思います。","respondent":"品川庶務課長、村尾教育総合支援センター長","answer":"非構造部材の耐震化ですが、現在のところ、契約の件数で申し上げることはできるのですが、夏場の工事としましては１６件、それから秋の工事として１３件となっております。スクールソーシャルワーカーが介入した等の件数ですけれども、実際には５０件程度、それぞれ各児童・生徒にかかわっている部分があります。","voiceIndex":192,"id":"exchange-083"},{"speaker":"大倉委員","kind":"質問・要望","question":"こうした中で、例えば中学３年生、９年生であれば、やっぱり１年間の最後の大会とか、こういったところに臨む部分においても、今、モチベーションや今までの成果を残そうといったところで、こうした耐震化、これは耐震化ですから必要ですが、なかなかそういう部活ができなくなってしまうようなことがないようにしていただきたいなと思っているのですが。","respondent":"品川庶務課長、村尾教育総合支援センター長","answer":"小学校は部活動はありませんので、そういったところで場所を借りたりなどして、いろいろ各学校間で工夫しながらこの部活動に対しては対応しています。それぞれの学校へのかかわりという部分を最初になのですけれども、例えばその学校には都費のスクールカウンセラーが１名、それぞれの学校に配置されていて。","voiceIndex":195,"id":"exchange-084"},{"speaker":"大倉委員","kind":"質問","question":"だから、利用率というところで、日中というと、結構わりとあいているのかなというところで、そういった区有施設との連携というのは考えられているのかどうか教えてください。子どもへの暴力防止プログラムについても伺いたいと思いますが、これは子どもと親というのが一緒に受けるということはできないのでしょうか。","respondent":"品川庶務課長、村尾教育総合支援センター長","answer":"非構造部材の関係で、ほかの区有の施設を使えないかというご質問ですが、非構造部材の耐震化を始める前にあたりまして、区有施設を使えないかどうかもいろいろ調整をしてみたのですが、やはり区有施設はかなり利用率が高いということで。それで、子どもと親についてはもともとプログラム内容が若干違うということで、メニュー等を一緒に行うということは多分難しいのではないかと考えています。","voiceIndex":198,"id":"exchange-085"},{"speaker":"大倉委員","kind":"質問・要望","question":"子どもへの暴力防止プログラム、わかりました。内容が違うのでなかなか難しいというところで言うと、これは、プログラム内容によっては契約時に精査し、時勢に沿った内容に更新していくということが、平成２５年度の事務事業評価とか、子どもへの暴力防止プログラムに載っているのですが、契約時というのは何年に１回などというのは教えていただけますか。","respondent":"村尾教育総合支援センター長","answer":"契約のときに、やはり現状、なかなか踏まえた上で、それぞれプログラムの、例えば時間設定であったり、また内容の変更等については伝えてはいるのですけれど、プログラム自体が一つ固まったパッケージとして成っておりますので、なかなか正直なところ難しいというのが現状です。","voiceIndex":201,"id":"exchange-086"},{"speaker":"大倉委員","kind":"質問","question":"プログラムが固まっていて難しいということで、内容については非常にいいものだというのも伺っているのですが、毎回同じもので受けているというところがマンネリ化につながっているというご指摘がありました。そういった中で、例えば人が集まるというのも非常に大変だという中で、例えば学校間合同とか、近い学校と連携して一緒にやるなどということはできないのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"そのような課題を克服するという一つの方策として、今、委員のご提案の、合同でどのような形でできるか。これも一つの選択肢として少し考えてみることはできるかなと考えています。","voiceIndex":203,"id":"exchange-087"},{"speaker":"大倉委員","kind":"質問","question":"時間があるので一点だけちょっとお伺いしたいのですが、これは平成２７年度の監査になってしまうのですが、小・中学校の警備業務委託について、私もよく夜、運動などで走っていたりすると、学校の前に警備の車、セキュリティと書いた車がよくとまっているのですが、これは循環なのですか。","respondent":"品川庶務課長","answer":"これは戸締まりだけではなく、機械のほうの故障で呼び出しをするという場合もありますので、いろいろな事情があるというものです。","voiceIndex":205,"id":"exchange-088"},{"speaker":"大倉委員","kind":"質問・要望","question":"すみません。これは非常に多く見かけたので、もしその一回一回の、契約がどうなっているかちょっとわからないので教えていただければと思いますが、できるだけこういったことがないようにしていただきたいなと思っての質問なので、最後にそれだけ教えてください。","respondent":"品川庶務課長","answer":"警備の契約ということで、委託しているものです。今後、このようなことがないように、学校全体として戸締まり等もしっかりして業務のほうを進めていきたいと考えています。","voiceIndex":207,"id":"exchange-089"},{"speaker":"こんの委員","kind":"質問","question":"その理解でよろしいかというところと、この事業の取組みについて現状をお聞きしてまいりたいと思いますが、改めてお伺いしますけれども、事業の目的、研究テーマの設定の仕方、それから発表する学校の選定の経緯や根拠など、取組みの実態や様子をお知らせください。","respondent":"村尾教育総合支援センター長","answer":"研究学校です。教育委員会といたしましては、本区が実施している小中一貫教育の成果を検証するというのが一つ大きな目標になります。その中で、それぞれ学校教育の質の向上を図るとともに、その研究内容がそれぞれ他の学校にも波及的に広がっていく。","voiceIndex":210,"id":"exchange-090"},{"speaker":"こんの委員","kind":"意見","question":"教育委員会のほうから、この研究をされる学校ということで、学校から手を挙げていただくという方式だということは初めて知りました。なので、学校が、ご自分たちの学校の課題を、こういう研究を通してお子さんたちを見ていく。こうしたことへの働きかけと、できるだけその研究をしていただいて、学校の教育の質を上げていただく。こうした目的だという、大変すばらしい事業だと思います。お知らせください。","respondent":"村尾教育総合支援センター長","answer":"その原因を明らかにすることによって、子どもと担任が、そのつまずきをもとにした新しい考え方とか問題の解き方、その辺を進めていくということで、独自の考え方としては、個別学習相談という仕組みをその学校は取り入れています。","voiceIndex":212,"id":"exchange-091"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうなると、ちょっと細かいことですが、そうした担任の先生のほかに配置されるというような、いわゆる研究成果の先、これが実際に教育現場の中で行われる場合、そうした配置はいわゆる予算の中で、学校が要望するとつけていただけるもので、これがきちんと具現化されるものなのか、そこら辺のところもちょっと後で教えていただきたいのですけれども、要はこうした研究成果は。","respondent":"村尾教育総合支援センター長","answer":"この成果を大きく波及するということで、今回、この研究発表には、各学校からぜひ１名または３名以内で先生方に来ていただいて、実際に見て、そして関係する指導案等も持ち帰っていただきながら、自分の学校でどこが使えるか、またどのような形で今度。","voiceIndex":214,"id":"exchange-092"},{"speaker":"こんの委員","kind":"質問・要望","question":"各学校から参加をぜひ呼びかけていただきたいと思いますし、改めてこの取組みのすばらしさを実感いたしました。こうした姿勢で、まだまだほかにも課題はあると思いますけれども、ぜひこの研究学校、これからも頑張って進めていただきたい。何かございましたら、後でこのことについてお願いしたいと思います。市民科・各教科充実経費でありますけれども、特に市民科についてお伺いしたいと思います。","respondent":"村尾教育総合支援センター長","answer":"具体的な授業といたしましては、ステップ１から５ということで、問題解決、問題を発見し、そして大切な道徳的な価値観を学び、そして実際に体験、スキルトレーニングを行いながら、日常生活で実際に使えるような、そういうものをこの学習で今進めているところです。","voiceIndex":216,"id":"exchange-093"},{"speaker":"こんの委員","kind":"質問・要望","question":"ご説明ありがとうございました。教師が子どもにかかわる。ここからしか始まらないという点ですので、どうかこれからも市民科の授業に対しては頑張っていただきたい。エールを送って終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":218,"id":"exchange-094"},{"speaker":"沢田委員","kind":"質問","question":"成果報告書の１６９ページの家庭教育力向上支援のところと、今まさにこんの委員から出ました、１６７ページの市民科で、道徳の教科化について聞こうと思います。今こんの委員から質問されたので、続けてまず道徳の教科化のほうからお伺いしようと思うのですけれども、今まさにお話しされたとおり、３月に道徳の教科化が発表されました。","respondent":"村尾教育総合支援センター長","answer":"今後の考え方というか流れなのですが、実際に道徳の教科化が国で始まったとしても、品川区は市民科という形でこの学習はそのまま継続していこうということで考えておりますので、道徳の教科化がされたといって、品川区に道徳があって、また市民科があるという形ではなく。","voiceIndex":220,"id":"exchange-095"},{"speaker":"沢田委員","kind":"質問・要望","question":"続きまして、家庭教育力向上支援のほうを伺わせてください。具体的な親の疑問に対する対策、それから子育てに関するちょっとしたコラムとかヒントですね。品川区も親育ちということでいろいろ取り組まれてきましたけれども、そういった部分があると思うのですけれども、改めて現状の認識と、それから家庭教育ブックの作成に至った経緯とお考えというか、その辺をお聞かせください。","respondent":"品川庶務課長","answer":"作成に至りましては、検討委員会等ももちまして、いろいろやりとりをしながら今回の家庭教育ブックを作成しています。今後はＰＴＡの委託事業、例えば家庭教育学級とか、あと地域健全育成協議会、それから学校内では家庭訪問のときに必ず先生がお渡しして説明すると。","voiceIndex":222,"id":"exchange-096"},{"speaker":"沢田委員","kind":"意見","question":"使い方を聞こうと思ったのですが、ありがとうあります。近所の子どもに対してもこういった言葉をかけてあげるという気持ちを地域の方でもみんなで持っていきたいなと思えるような、本当に優しい、本当にすばらしい内容だったので、そのあたりの、もうちょっと今度、感想をもらって、またさらにこういうのを改訂していったりとか、その辺のお考えというか、どういうお考えかお聞かせください。","respondent":"品川庶務課長","answer":"そういった部分を、保護者の方から意見を集約しまして、変えていく機会があればまた変えていくというような形で、長年使っていただけるような家庭教育ブックになればいいかと考えています。","voiceIndex":224,"id":"exchange-097"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、１７４ページの就学援助費に関連して質問します。生活保護費が３年間にわたり合計約１０％引き下げられてきました。来年度も生活保護の引き下げと連動させず、教育を安心して受けられるように、この基準を維持していっていただきたいと思いますが、いかがでしょうか。もし生活保護費の引き下げられた額を基準にすると、対象から外れてしまう子どもは何人ぐらいいるのか教えてください。","respondent":"野呂瀬学務課長","answer":"今年に同じような形で当てはめたら５９５人、ほぼ同じぐらい、その基準にしたら認定が受けられない子どもが出るというシミュレーションで出しております。","voiceIndex":227,"id":"exchange-098"},{"speaker":"のだて委員","kind":"質問","question":"引き下げられた場合の人数、当てはめると５９５人の方が対象外になるということでした。やはり、昨年よりも生活保護費を引き下げられて、２５人分、増えてしまうということだと思います。親の経済状況も決してよくなっていないですし、子どもが安心して教育を受けられるように、就学援助は拡大こそすべきだと思いますが、いかがでしょうか。","respondent":"野呂瀬学務課長","answer":"１.２５ということでやっております。それで、ほかの各区では１.１、１.２が主流で、１.２５というのは、品川区はかなり手厚くやっているなという、自覚していますので、今後これを拡大するという考えは今のところございません。","voiceIndex":229,"id":"exchange-099"},{"speaker":"のだて委員","kind":"質問・要望","question":"品川区は１.２５倍で、ほかの区よりは拡充しているということでしたけれども、今後も拡大するお考えはないということでしたけれども、生活保護引き下げに連動させることなく、現在の基準を維持し続けていただくように要望いたします。品川区においても現在の７月支給ではなく、入学前からの支援をしていくべきだと思いますが、いかがでしょうか。現在、１回目の支給が７月下旬になっている理由を伺います。","respondent":"野呂瀬学務課長","answer":"それで認定された方については就学援助費を支給していくです。それで、なぜ７月かということなのですが、これは１学期ごとに支給するということで、１学期については７月ということで支給しております。","voiceIndex":231,"id":"exchange-100"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったことでもう７月になっているということでしたけれども、ほかのところでは、入学前からもう実施することができています。品川区として、入学前からの支援の必要性をどのように捉えているのか伺いたいと思います。せめて希望者ぐらいは区の工夫で何とかできないものでしょうか。そして、それができなくとも、少なくとも７月ではなくもっと早く支給を早めていく。いかがでしょうか。","respondent":"野呂瀬学務課長","answer":"その全体の中で就学援助を行っておりますので、それプラス、またそれぞれの品目、あそこの自治体がやっているからというような形で合わせるというのは、これは品川区の実態に合わないということで、今、考えておりません。","voiceIndex":233,"id":"exchange-101"},{"speaker":"のだて委員","kind":"質問・要望","question":"品川区の実態に合わないということですけれども、品川区の入学前からの支援の必要性をどう捉えているのかということもお聞きしましたので、あと早くできないかと、その辺も検討していただきたいと思いますので、改めて伺います。","respondent":"野呂瀬学務課長","answer":"先ほど申しましたとおり、６月の税の所得の判定を待って認定しておりますので、それ以前にやるということは難しいと考えています。","voiceIndex":235,"id":"exchange-102"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、できるだけ早く、やはり入学する前から準備金がかかってきますので、支給できるようにしていっていただきたいと思います。そして、現在、制服については一律２万円の支給となっています。これでは約１万円が持ち出しになってしまいます。制服というのは学校に通うため必要なものなので、家庭の持ち出しにならないよう実費支給にしていただきたいと思いますが、いかがでしょうか。","respondent":"野呂瀬学務課長","answer":"これは、今、制度上、実費支給というのは給食費相当だけですので、３万円かかるというところもありますし、かからないところもありますので、これはその状況の中で一律、今、２万円という形で設定しておりますので、この品目についても、今現在。","voiceIndex":237,"id":"exchange-103"},{"speaker":"のだて委員","kind":"質問・要望","question":"３万円いかないところもあるということですけれども、そうであれば、最低限の額だけでも拡充していっていただきたいと思います。こういった塾代、クラブ活動費、生徒会費、ＰＴＡ会費も品川区として項目の拡大をしていただきたいと思いますが、いかがでしょうか。","respondent":"野呂瀬学務課長","answer":"適切に判断してまいります。","voiceIndex":239,"id":"exchange-104"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１６５ページの就学事務費、１６９ページの特別支援教育費、１６９ページ、ＰＴＡ関係経費をお尋ねします。特別支援教育費なのですが、民生費のところでも発達障害児のことをお尋ねしました。どのようにして成り立たせているのか。インクルーシブの流れの中で、今後、区はどのようにして対応していこうと考えていらっしゃるかお尋ねします。","respondent":"村尾教育総合支援センター長","answer":"昨年度までは１人に対して１人の学習支援員という配置ではございましたけれども、本年度からは５人以内ということで、１人の学習支援員が５人の子どもたち、クラスの中で対応できるというような仕組みをとりまして、担任が対応できない部分については学習支援員が対応するのだと。","voiceIndex":242,"id":"exchange-105"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"きめ細かな指導ということで、ぜひお願いしたいと思います。先ほどの文部科学省の調査は、品川区立の小学校の校長先生も入られて行われたものですので、ぜひ今後の指導に役立てていただきたいと思います。次に就学事務、就学相談のことをお尋ねしますけれども、平成２６年度の相談件数等、実績等について簡単にご説明いただきたいと思います。","respondent":"村尾教育総合支援センター長","answer":"就学相談のお尋ねです。平成２６年度につきましては、小学校で言うと１００名、それから中学校では３７名、計１３７名の児童・生徒がこの就学相談のほうにかかって、それぞれの子どもに応じた学校を勧めているところです。","voiceIndex":244,"id":"exchange-106"},{"speaker":"高橋（し）委員","kind":"質問","question":"１３７名ということで、大変多い数の相談を受けていらっしゃるということですが、何らかの就学相談のほうで相談を受けなかった、あるいは制限したなどということはあったのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"保護者の中には、就学相談を受けずにそのまま小学校に入学した、または中学校に入学したというケースも当然あります。","voiceIndex":246,"id":"exchange-107"},{"speaker":"高橋（し）委員","kind":"質問","question":"受けたいという保護者の方のリクエストを、何というのですか、それはと言って、数の面からとか、受けなかったということがありますか。","respondent":"村尾教育総合支援センター長","answer":"失礼いたしました。希望者は全て相談を受けております。","voiceIndex":248,"id":"exchange-108"},{"speaker":"高橋（し）委員","kind":"質問","question":"それで、今お話があったように、就学相談を受けないということはないと考えてよろしいでしょうか。","respondent":"村尾教育総合支援センター長","answer":"今回は特別支援教室の設置に伴って、大変、数が急激に多くなってきているという現状はあります。ただ、実際にはすぐに相談を受けられないとは思うのですが、必ず年内には何らかの形で相談のほう、申請があればどうにか対応したいと考えているところです。","voiceIndex":250,"id":"exchange-109"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"年内にはどうにか、ぜひ必ず受けていただき、ご相談に乗っていただきたいと思います。ところで、実は文教委員会で配付された同様の資料にはこの一文が入っていませんでした。それで、そこで議論にはならなかったのです。これは保護者の方に配る資料よりも後に文教委員会があったのですが、その資料にこの一文が載っていなかったのですが、それはどういったご事情なのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"これは、文教委員会にはゲラ刷りというか案の形でお示しして、その間に業者にかけている原稿に多少の追加があったため前後したところがあります。本当に申し訳ございませんでした。","voiceIndex":252,"id":"exchange-110"},{"speaker":"高橋（し）委員","kind":"確認","question":"今、多少のとありましたが、その一文は非常に重要なところでありまして、ただ、今、年度内に必ず相談を受けて、そして切実な思いを持たれている保護者の方の解決をぜひやっていただけるということをここでお約束していただければよろしいかと思うのですが、もう一度確認します。","respondent":"村尾教育総合支援センター長","answer":"繰り返しになりますが、何らかの形で、こちらのほうでも十分対応させていただきたいと考えています。","voiceIndex":254,"id":"exchange-111"},{"speaker":"高橋（し）委員","kind":"質問","question":"ぜひよろしくお願いします。次にＰＴＡのほうなのですが、ＰＴＡの方たちのホームページのことについてなのですが、学校との接続ができないということで、役員が個人的にサーバーと契約し、そしてこれは、それでＰＴＡの会費から支出しているということなのですが、この現状について学校のほうでは何らかの支援ができないでしょうか。","respondent":"品川庶務課長","answer":"ホームページの件ですが、現状なかなか把握し切れていないところがありますので、少し学校等にも聞いてみまして、その辺の現状をまず把握しまして、その後、校長会、それから役員・校長会等も通じまして検討していきたいと思っています。","voiceIndex":256,"id":"exchange-112"},{"speaker":"高橋（し）委員","kind":"質問","question":"システムの構築は平成２４年度は２５０万円、システム利用料はケーブルテレビを使っての部分、月２,０００円でしょうか。そういった形です。全て教育委員会のほうで利用料を払うのが、支援となると思いますが、それは一部、ＰＴＡと話し合って、どのように分担していくかということを考えて、そういう支援の方法があると思うのですが、いかがでしょうか。","respondent":"品川庶務課長","answer":"ＰＴＡの組織自体、こちらが基本的には学校と保護者が集まってやる団体というふうになっております。ここから、教育委員会がどのように支援できるかというところはなかなか難しい点もあるかと思いますので、まず現状を把握しまして、その辺、少し検討したいと考えております。","voiceIndex":258,"id":"exchange-113"},{"speaker":"高橋（し）委員","kind":"意見","question":"コミュニティ・スクールという形が進んでいく中で、ＰＴＡとの関係も新しい形を担っていくと思います。ぜひ検討をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":260,"id":"exchange-114"},{"speaker":"渡部委員","kind":"質問・要望","question":"だけれども、学校がこのままだと受入可能数は１,０００人です。適正配置、いわゆる、そこの地域の子どもたちがそこの学校にちゃんと通える仕組みというのをしっかりつくっていかなければならないと思うのですが、改めて、これから学校配置等のあり方について、これはもう、３年後、４年後にこういう数字が出ているのですから、早急に取り組んでいかなければならないと思うのですが、いかがでしょうか。","respondent":"品川庶務課長","answer":"そういった点も含みまして、教育委員会としましては、御殿山小学校の改築、それから今進めております芳水小学校の改築、こういう改築を進めまして人口増に対応しているというような状況です。","voiceIndex":262,"id":"exchange-115"},{"speaker":"渡部委員","kind":"質問","question":"それで、今後３年、４年後にどうなるかといっても人数はさほど変わらない。増えても５％というような感じであって、いや、それが、いい、悪いではないです。だけれども、これから改築をしなければならない学校がどんどんあるのも間違いないわけですから、そういった場合に、やはりどういうふうにこれから先を見据えてやっていかなければならないのか。荒川区だったでしょうか。","respondent":"品川庶務課長","answer":"そういった視点から見ましても、今後のあり方、国の動向、それから都の動向などもあります。それから近隣区の動向もあるかと思います。そういった動向も見据えまして、今後の配置のあり方については考えていきたいと考えています。","voiceIndex":264,"id":"exchange-116"},{"speaker":"渡部委員","kind":"質問・要望","question":"ですので、それだけにやはり精度の高い学校案内というものをこれからまだつくっていただきたい反面、選択制について、３割以上の方が選択してくるわけですから、自由度の高いものに。家庭の事情でやはり行けない方がいるのでしょうか。そして、１人当たりの確認ですけれども、参加費というのはあくまでも交通費、食費、宿泊費といういわゆる実費だったでしょうか。ちょっとその辺を教えてください。","respondent":"渋谷指導課長","answer":"勉強合宿です。平成２７年度は宿泊のものとしては日野学園、八潮、荏原平塚学園、それから品川学園というものがあったです。","voiceIndex":266,"id":"exchange-117"},{"speaker":"渡部委員","kind":"質問・要望","question":"相当いいものだと認識しています。品川区はやはりすごいよねという話になるのですが、これはやはり、いわゆる人のパワーを使わなければいけないというところで、なかなかほかの学校に広げるのは難しいのかなという気はいたしますが、実際、ほかからの要望、ほかの中学校ですね、小中一貫校だからできるというような感じなのかなと思うのですが、どうなのでしょう。全校でやれたらいいのになとは思うのですが。","respondent":"渋谷指導課長","answer":"ただ、今、受け入れていただいている国立女性教育会館のキャパの問題等もありますので、今後、宿泊場所等については改めて検討していかなければいけないと考えているところです。","voiceIndex":268,"id":"exchange-118"},{"speaker":"若林委員","kind":"質問","question":"推進委員会経費ですが、この委員会は平成２５年度に文部科学省のほうから、小中一貫教育校による多様な教育システムの調査事業、この研究委託を受けたということで、３年間ですから今年度で終わりという事業を委託される中で、翌平成２６年度に小中一貫教育の推進委員会が設置されたという経緯だと伺っております。こういう４つの考え方があると思うのですけれども、これについてお話を伺いたいと思います。","respondent":"渋谷指導課長","answer":"第２部会につきましては地域部会ということで、地域との連携をいかに図っていくのかという観点で検討していく。それから第３部会は３番目にご指摘いただいた９年間の学びをということで、小中一貫教育ならではのカリキュラムのあり方について検討しています。","voiceIndex":273,"id":"exchange-119"},{"speaker":"若林委員","kind":"質問","question":"特に今年度、平成２７年度は、浜川中学校、浜川小学校、鮫浜小学校というモデルを設定して、品川版学校運営協議会および地域支援本部のあり方を、今、研究しているですので、まずその３校、エリアの指定の理由を一つお聞きしておきたいのと、学校と地域双方で支援をしたり、また貢献をしたりという、今まさに仕組みづくりが研究されているのですけれども。","respondent":"渋谷指導課長","answer":"体制部会でさまざま検討していく中で、国の動向もあるのですけれども、小中一貫教育というものを考えたときに、一つのやっぱり中学校区というふうなものを単位にして９年間の義務教育を考えていくというのは。","voiceIndex":275,"id":"exchange-120"},{"speaker":"若林委員","kind":"質問・要望","question":"これは、次期学習指導要領の改訂を踏まえということが一つ前提になっているのですが、まだ当然、改訂が来年、再来年度ですか、というスケジュールの中で、学習指導要領の改訂、文部科学省のほうから諮問されましたけれども、その内容を見ますと、おそらくこういうことが、今、重点的に取り組まれていくのかなということで、まずは主体的に取り組む意欲ですとか、多様性を尊重する態度。","respondent":"渋谷指導課長、村尾教育総合支援センター長","answer":"それで、品川区独自で進めている英語ですとか市民科、またＩＣＴ教育については、これは継続しながら次の学習指導要領の改訂を踏まえた、品川区の新たな指導要領、教育要領。療育支援ネットワークにつきましては、本当に今後、教育委員会と、それから関係部署と、十分、連携を図りながら、やはり子どもたち、また同じく保護者の支援のほうも必要だということで。","voiceIndex":277,"id":"exchange-121"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それと１６７ページ、市民科になると思うのですが動物飼育について、それと１６８ページ、国際理解教育、外国人の英語講師学習指導についてお伺いします。初めに１６６ページのＩＣＴ、１７１ページのＩＣＴについて伺います。１６６ページのＩＣＴを活用した教育活動の研究ですが、この１年間を通して研究結果、どのようなものがあったのかお知らせいただきたいと思います。よろしくお願いします。","respondent":"村尾教育総合支援センター長、野呂瀬学務課長","answer":"ＩＣＴを活用した教育活動の研究です。これは、先ほどの研究学校と同じく、２年計画の、今年２年目に当たる研究です。当初はいろいろ、何というのですか、まだ使い勝手がわからないとか、いろいろあったのですけれども。タブレットを、特別支援学級、知的の固定級、また通級に配置していただいて、現在進めているところです。","voiceIndex":284,"id":"exchange-122"},{"speaker":"石田（し）委員","kind":"質問","question":"それと、約１年通して実際に使ってみて、今後どのようにこれを展開していくのか、もしその展望があればお知らせください。次に市民科でありますが、現在、小・中学校において学校内での動物飼育を行っている学校等の現状をお知らせください。動物を、実際に動物介在教育としての活用というのがされているのか、あわせてお答えください。よろしくお願いします。","respondent":"野呂瀬学務課長、渋谷指導課長、村尾教育総合支援センター長","answer":"私のほうから、教師へのサポート体制といいますか、そういうところなのですけれども、プロジェクター、使いやすいと回答したのは、ほぼ全員ということだと。実際に使っている先生方の受けとめ方ですが、例えば源氏前小学校の５年生の担任の先生は。各学校に獣医が訪問し、それぞれ各学校で飼っている動物の触れ合い方とか、また命の大切さ等も、実際には、平成２７年度で言うと。","voiceIndex":288,"id":"exchange-123"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ＩＣＴはぜひ進めていただければなと思います。動物飼育なのですが、最近もテレビ報道で、さまざまな地域で動物たちの虐待死というのですか、そういったものが本当に多く報道されている中で、やっぱり命の大切さというものが、教育の中でも非常に大事なテーマになっているのかなと思います。","respondent":"村尾教育総合支援センター長","answer":"まさに命の大切さという部分については、学校教育でも大変重要な部分だと考えているところです。まさに今子どもたちが置かれている現状は、ゲーム等で命がリセットされるとか、または、なかなかリアルな世界を体験できないままバーチャルな中で生きてしまっている。","voiceIndex":292,"id":"exchange-124"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひよろしくお願いします。要望で終わります。１６８ページの国際理解教育について、まずこの平成２６年度の外国人英語講師学習指導について内容をお知らせください。","respondent":"渋谷指導課長","answer":"これはいわゆるＡＬＴ、Assistant Language Teacherということで、外国人に委託して学校の英語の授業に入っていただくというふうな事業です。","voiceIndex":294,"id":"exchange-125"},{"speaker":"石田（し）委員","kind":"意見","question":"いろいろな事情があって一回やめられたと思うのですが、改めて今後、この友好都市の教員交流について区のお考えをお知らせください。","respondent":"渋谷指導課長","answer":"ただ、平成２６年度から、今度は友好協会との連携で、中学生の語学派遣をするというようなことがありました。そういったこともありますので、今年度からまたオークランドの先生には来ていただくような取組みを開始したところです。","voiceIndex":296,"id":"exchange-126"},{"speaker":"石田（秀）委員","kind":"意見","question":"１人ぐらい、ちょっとと思う人はいるけれども、だけれども本当に押しなべてよくやっているなと思っています。それは教育委員会は、校長先生とか職員の方々が今、プラン２１を含めていろんな品川の教育についてどういう評価をされているのか、よくやっているなと思っているのか、そこら辺のまず評価を聞きたいと思います。","respondent":"渋谷指導課長","answer":"大変難しい質問ではありますが、視察等で他の自治体の方から、教育プラン２１のご説明をして、どうだというふうな評価をするときに、私は自慢するのは、品川区の管理職の質の高さは他の自治体に誇れますということは常々申し上げています。","voiceIndex":301,"id":"exchange-127"},{"speaker":"石田（秀）委員","kind":"質問","question":"どうしてこういうことを聞いたかというと、例えば、どうしても学校というのはいろいろなことが起きるので、危機管理はいろいろ、いじめのことがあったりいろいろすると危機管理をするようになる。忙しいことばかりでという。ですから、やはりそこら辺の信頼関係はお持ちになっていて、高めるためにこういうふうにしていこう。その意識を常にお持ちなのかどうかというのは改めてお聞かせください。","respondent":"渋谷指導課長","answer":"今、中島教育長になって、役員・校長連絡会等々を毎月実施しまして、校長会と教育委員会との連携を密に図っているところです。その中で常々、中島教育長が申し上げているのは、とにかく危機管理というのは知識ではなくて意識だ。","voiceIndex":303,"id":"exchange-128"},{"speaker":"石田（秀）委員","kind":"質問","question":"ぜひよろしくお願いします。その学校運営費の中でちょっと一つだけお伺いしたいのは、校章とか校歌をどうやって決めるかというのは教育委員会の中であるのでしょうか。伺います。","respondent":"品川庶務課長","answer":"校章関係につきましては、基本的には学校の中で決めるというような形になっております。検討委員会等を立ち上げて決めているというような経過が多いかと思います。","voiceIndex":305,"id":"exchange-129"},{"speaker":"石田（秀）委員","kind":"質問","question":"作詞などは公募にしてくれないかと。それで、みんなで選ぶと。それは誰が書いたとか書かなくていいわけですから。多分これはずっと残ることになるので、校章は終わったのでいいのですけれど、校歌などはそういう話というのはぜひ、教育委員会から言うのか、ちょっと微妙なのだけど、こっちが直接、校長先生とそういう話をするというのは、どっちがいいのかわからないのですが、これの考え方を教えてください。","respondent":"品川庶務課長","answer":"委員からのご要望であれば、教育委員会からとして、一つこのような方法はどうかというようなことを、学校、それから選定委員等に話すというようなことはできるかと考えております。","voiceIndex":307,"id":"exchange-130"},{"speaker":"石田（秀）委員","kind":"質問","question":"ぜひよろしくお願いします。それで、見つかったのだけれども、そういうのを校長先生が歴代継いでくれないと、それはわざわざ前の木造校舎のそういうのを残して寄贈して、みんなでつくったものが、何かどこかに行ってしまったみたいなのは、校長先生はそれぐらいは各学校で、教育委員会からも言ってもらって、ちゃんと継いでいってほしいのだけど、そこら辺もちょっと考え方を教えてください。","respondent":"品川庶務課長","answer":"多分、地区の方、それから校長先生等、さまざまな思いがあるかと思います。そういう思いをいろいろ聞きまして、教育委員会のほうで何かできる方法はないかということを考えていきたいと考えています。","voiceIndex":309,"id":"exchange-131"},{"speaker":"石田（ち）委員","kind":"質問","question":"私は、１６６ページ、いじめ防止対策費に関連して、品川区いじめ防止対策推進条例について伺いたいと思います。条例がつくられるのだなということを、ちょっと初めて知ったのですけれども、もう案が出ているのに、議会または委員会に出されていないのはなぜか伺いたいと思います。それと、この条例をつくる理由と、案をつくるにあたって何がどう進められてきたのか、今後のスケジュールも教えてください。","respondent":"村尾教育総合支援センター長","answer":"それを受けまして、東京都がつくったわけではありますけれども、品川区としては、やはり平成２４年度に自殺案件がございまして、区として今まさにオール品川でいじめを取り組んでいる中で、区としてもやはり推進条例をつくるべきではないかということで考えてきているところです。","voiceIndex":312,"id":"exchange-132"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、丁寧につくっているということですけれども、議会のほうにはいつごろ出されてくるのかということは、まだ見通しは立っていないということなのでしょうか。お聞かせください。","respondent":"村尾教育総合支援センター長","answer":"現在の予定ではありますけれども、第１回定例会のほうに提案する、今の予定です。","voiceIndex":314,"id":"exchange-133"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。子どもの命を守るための対策を進めるということですので、私たちも十分に議論に参加していきたいなと思っています。子どものいじめ問題は生命にかかわる深刻な事態、全国各地で今、生じています。こういった立場を明らかにするなど、いじめ克服を願う区民と子どもたち、そして教師の支えになるような条例にしていくべきだと思うのですけれども、区の認識はいかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"この、いじめ防止対策条例をつくる背景も、先ほどお話ししたとおり、言うまでもなく子どもたちの命を守るために、当然、その学校に勤めている教員、そして保護者も一緒に、この部分につきましては力を合わせて、今後二度といじめにより命を絶つ。","voiceIndex":316,"id":"exchange-134"},{"speaker":"石田（ち）委員","kind":"質問","question":"その一つが、いじめの禁止と厳罰での取り締まりです。第４条には、子どもはいじめを行ってはいけない。こういった規定があります。そして第２５条、第２６条では、いじめをした子どもの懲戒や出席停止の規定、こういったことが盛り込まれています。区の条例はどのようになっていくのか。この国の法律、いろいろ問題も指摘されているこの法律に準じたものになっていくのか、伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"当然、子どもたちの命を守るという部分については、やはり一定の基準を設けなければいけないと考えておりますし、区としての条例については、当然、国の法に準拠した形で進めていこうと考えております。","voiceIndex":318,"id":"exchange-135"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"品川区のいじめ防止対策推進条例がこのような立場に立ち、禁止や厳罰、押しつけではなく、各地の経験や教訓に学び、いじめ問題に詳しい専門家や被害者団体、ＮＰＯなど、現場の意見聴取や参加もしてもらって、子どもの命を守る実効性のある対策が進む、そのための条例にしていただきたいと思いますけれども、そういった具体的なところではどうお考えでしょうか。","respondent":"村尾教育総合支援センター長","answer":"当然、品川区では、道徳教育ではなくて市民科の中で、子どもたちのいじめ防止だけではなく、人には優しくしなければならないとか、または相手に思いやりを持たなければいけない。そういう心の育成も十分図りながら進めていこうと考えているところです。","voiceIndex":320,"id":"exchange-136"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"なので、こういった押しつけや禁止や厳罰ではなくて、一定の基準が必要だとおっしゃっていましたけれども、そういった立場ではなく、子どもたちに親身に寄り添って、そして養護教諭だったりスクールソーシャルワーカーやスクールカウンセラーの増員、そして正規職員化といったこともさらに進めていかないと、子どもたちを支える大人たちが疲弊していくという状況では。","respondent":"村尾教育総合支援センター長","answer":"言うまでもなく、今、品川区の先生方、品川区だけではないと思いますけれども、先生方は子どもたちと十分向き合って、今、進めているというのを私は感じております。","voiceIndex":322,"id":"exchange-137"},{"speaker":"たけうち委員","kind":"質問・要望","question":"もうご覧になったかと思うのですが、これは報道なので、私も確認はもちろんできないのですけれども、なかなか読解力とか数学力の向上には結びつかずに、逆に低下しているというような報告がされているという中で、ＩＣＴの使い方をやっぱり工夫していかないといけないのではないかというような報道になっているのですけれど、これについての見解を教えていただきたいと思います。","respondent":"渋谷指導課長、品川庶務課長、村尾教育総合支援センター長、野呂瀬学務課長","answer":"私どもが取り組んでいる小中一貫教育全国協議会は、あくまでも自治体単位で小中一貫教育を推進していく上での情報交換であったり。すまいるスクール等と協力しまして、地域の小学校３年生から６年生の子どもに、文化財の散策をするツアーを開いているような状況です。地域の方々と連携を図りながら、今後もこの文化創造については進めていこうと考えておるところです。それと２点目の、１.２５にした判断の基準ですけれども、申し訳ございません、これについては。","voiceIndex":325,"id":"exchange-138"},{"speaker":"たけうち委員","kind":"質問","question":"子どもたちがやっぱり将来５年後、ある程度の大人になって外国の方と触れ合ったときに、品川の魅力は何ですかというときに、伊藤博文の墓と例えば聞かれても、あ、そんなのあるのというのではやっぱり寂しいのかなと思うので、その辺をもう一重、どうやって取り組むのかなということをお聞きしたいと思います。ただ、公表されているからいいのだと思うのですけれど、足立区あたりは１.１なのです。","respondent":"品川庶務課長、野呂瀬学務課長","answer":"品川区の中には、明治時代に活躍した方のお墓が大分、数多くあります。こういったものをどのように活用していくかというところは、オリンピック・パラリンピック担当と協働しながらやっていきたいと考えています。その考えは、その要綱の中にも定めておりますので、今後とも引き続き取り組んでまいりたいと思います。","voiceIndex":330,"id":"exchange-139"},{"speaker":"たけうち委員","kind":"質問","question":"わかりました。一点、子どもたちの文化財に対する取組み、これをちょっと後で教えてもらいたいのと、もうちょっと拡充してもらいたいという角度です。最後に子どもと文化財の取組みについての、子どもたちのだけ教えてください。","respondent":"品川庶務課長","answer":"子どもに対する文化財の取組みですが、現行行っている子ども文化財散策ツアー等も利用しまして、さまざまな形で子どもに品川区の文化財を伝えていくというような活動をしていきたいと考えております。","voiceIndex":333,"id":"exchange-140"},{"speaker":"本多委員","kind":"質問","question":"１６７ページの市民科・各教科充実経費について質問します。それで、教材を見てみますと、１・２年生の挨拶で気持ちよい１日から始まりまして、８年生・９年生の進路計画と生活設計、体験学習まで、本当に中身の濃い充実した内容になっていると思います。","respondent":"村尾教育総合支援センター長","answer":"そのときの部分ですけれども、各学校から、やはり力のあるという言い方も変なのですけれども、市民科学習について大変、実践が伴っている、そういう方々を、市民科、いわゆる教科カリキュラム研究・検討部会のほうに入っていただいて、低学年、１・２年生、そして３・４年生。","voiceIndex":336,"id":"exchange-141"},{"speaker":"本多委員","kind":"質問・要望","question":"今後のさらなる充実を求めまして、よろしくお願いいたします。もう導入して５年目になります三木小学校、３年目になります浅間台小学校、城南小学校、２年目になります旗台小学校、現在４校で取り組まれていると思うのですが、この間の、もう一番長いところで三木小学校ですので、５年間、５年目ということなので、検証ですとか分析等されていると思うのですが、その成果についてお聞かせください。","respondent":"村尾教育総合支援センター長","answer":"具体的な成果の部分なのですけれども、やはり子どもたちの中に語彙力が増えた、表現力というものの進展が見られたという部分、また子どもたちの学習態度においては、集中力であったり、きちっとした座り方できちっとした学習を進めているところですので。","voiceIndex":338,"id":"exchange-142"},{"speaker":"本多委員","kind":"質問","question":"表現力、集中力が高まるということで、すばらしいと思います。親の、保護者の意見は今いただきましたので、児童・生徒の声ですとか先生の声というものはどういう感じでしょうか。","respondent":"村尾教育総合支援センター長","answer":"先生方については、やはりこれが継続して続いている部分で、子どもたちにとって、このサントレが、やはり高学年が今度、低学年に伝え、また新しい子どもたちが先輩を見ながら新しい形でこのサントレに取り組んでいくというような部分で。","voiceIndex":340,"id":"exchange-143"},{"speaker":"本多委員","kind":"意見","question":"高学年から低学年ということで、本当に幼少期でもすごく効果があると思うのですけれども、以前、三木小学校の隣の保育園の分園でも実施されていたと思うのですけれども、今はやっていないと思うのですが、その辺、区立幼稚園であったり就学前での取組みというのは検討されるのかどうなのか、現在のところをお聞かせください。","respondent":"竹田保育課長","answer":"今も継続的に品川保育園のほうではサントレを行っております。ほかの園でも園長の裁量で自主的にやっているところもあるのですけれども、今後、拡大するかどうかについては検討してまいりたいと考えています。","voiceIndex":342,"id":"exchange-144"},{"speaker":"本多委員","kind":"質問・要望","question":"この中で、「文部科学省では各大学における大学改革の取組みが一層推進されるよう、さまざまな事業により特色・個性のあるすぐれた取組みを選定・支援しています」ということで、立正大学の教育改革、学びたくなる環境、社会に求める学びの機会ということで、地域や地域の企業とのつながりを公表しているのですけれども、そういったつながりをさらに発展していっていただきたいなと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":344,"id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"それから親から子への貧困の連鎖を防ぐ狙いがあって、厚生労働省ではひとり親家庭学習支援事業、生活保護費の中では受験生チャレンジ支援貸付、そして今年１０月からですか、奨学金を塾代に使っても生活保護費から削られないというような、こういうふうに厚生労働省では、やはり学力が足りない、だから、支援するから頑張ってよというメッセージがあると思うのです。ちょっとご見解をお聞かせください。","respondent":"渋谷指導課長","answer":"ひとり親支援ですとかチャレンジ貸付というものの、そもそもの対象が、学力のない方とか学力の定着が十分でない方という観点ではなくて、福祉的な側面から経済的に援助が必要な方たちへの支援策だと考えています。","voiceIndex":346,"id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"実際、大変です。だから、僕はなぜ教育をもっと頑張らないといけないか。でも、現実は違うじゃないですか。この人たちだって、学力をつけなかったらどうするんですか。それがやっているのがフィンランドだと思いますけれど、日本もこれだけの品川区、先駆的な教育をやっているとおっしゃるなら、僕はそういうことをきちっとやるべきだと思うのですが、もう一度ご見解をお聞かせください。","respondent":"渋谷指導課長","answer":"委員ご指摘のとおり、教育委員会として子どもたちに確かな学力をつけるというのは重要な責務だと考えているところです。","voiceIndex":348,"id":"exchange-147"},{"speaker":"須貝委員","kind":"質問","question":"それはきちんと把握してほしい。そうじゃないではないですか。だって、これだけの授業をやって、これだけ宣伝して、どうして増えないのですか。これは校長が学校に１人。それで、施設分離型においては、もし小学校・中学校が別々の校長がいて、品川区のように小中一貫教育をしたら、これは小中連携教育という扱いになり、小中一貫教育という扱いにならないとも言われていますが、これは事実ですか。","respondent":"渋谷指導課長","answer":"それから既存の小・中学校と同様に市町村による就学指定の対象として入学者選抜を実施しないというものです。それで、今、委員のご指摘にあった連携型というものについては、これは別途、省令を定めて、その中身について議論をするというふうに聞いているところです。","voiceIndex":350,"id":"exchange-148"},{"speaker":"須貝委員","kind":"質問・要望","question":"小中連携教育であるというようなことを、今、何か指し示しているように書いてあります。だけど、もう実験校ではないのですから、私はしっかりした法に基づいた、やはり制度設計をしていただきたいと思います。これは実際、何年間大丈夫なのですか。それと、前も申し上げましたが、先生というのは３年たったら異動できますよね。本当に大丈夫なのですか。その辺ももしあれば教えてください。","respondent":"渋谷指導課長","answer":"そういった中で、小中一貫教育全国協議会の幹事区として、義務教育学校としての法制化を品川区が率先して求めてきて、それが１０年たってようやく認められたということですので、今、委員ご指摘のように。","voiceIndex":352,"id":"exchange-149"},{"speaker":"須貝委員","kind":"質問","question":"次にちょっと施設整備についてお聞きしたいと思うのです。それで、小学校、中学校と同様に、義務教育学校施設の、今言った新築・増築に関しては、経費の２分の１を国が負担するとあります。でも、実験校として、もう６校つくってしまいました。そうすると、総額でも三百数十億円ですか。２分の１は国が負担したのか何かというふうな計算になりますが、これについてどのようなご見解をお持ちでしょうか。","respondent":"品川庶務課長","answer":"当然、建設にあたっては、その状況においての補助を最大限に利用して建てているものです。今後、こういった補助がありましたら、利用できるものであれば利用していく。そういうような考えで、今後も施設の建設等を進めていきたいと考えております。","voiceIndex":354,"id":"exchange-150"},{"speaker":"須貝委員","kind":"質問","question":"でも、区内には分離型というのはこれからやっていけると思うのですが、そうすると、２分の１もらえるということならば、この義務教育学校の制度を利用して、どこかとどこかの小学校と中学校がくっついて、そして新しくどっちかを建て直しして、教員と校長を一緒の場所に置く。そういうような仕組みづくりを今後考えていくのでしょうか。その辺について、もう先々考えているのでしょうか。","respondent":"渋谷指導課長","answer":"施設費の負担法に関する部分で、ちょっと誤解があるようなので確認しておきますが、現行制度ででも、校舎、屋内運動場の新増築については、公立学校施設整備負担金により原則２分の１の負担をいただいております。","voiceIndex":356,"id":"exchange-151"},{"speaker":"須貝委員","kind":"質問・要望","question":"それはもう一度きちっとお答えしていただきたい。それは間違いないですね。では今までの。というのは、我々が聞いていた、すみません、誰とは言わないですけれど、今、これから建てるところは、やっぱり補助が出ないから、皆さん、日本全国、苦労していますよね。では２分の１は確実に出ているから、今まで施設一体型もどんどんやってきた。それでも国としては半分はきちんとくれたということですか。","respondent":"渋谷指導課長","answer":"実験校というふうなご認識ですが、今、既存である小中一貫校、日野学園は、第二日野小学校、日野中学校という設置条例に位置付けられた単独の小・中学校が合体した施設ですので、現行の施設負担法の適用を受けているものです。","voiceIndex":358,"id":"exchange-152"},{"speaker":"須貝委員","kind":"質問","question":"実際ちょっと、私の認識不足かもしれないですけれど、ですが現行の小学校、中学校と言うならば、校長は２人いなければいけない。教員も小学校の先生と中学校の先生、教員をちゃんと敷居をしないといけない。そういうことをやっていてはいけないわけではないのですか。それでも正規でなくても、そういうふうにきちんとおりてきたということでいいのですね。","respondent":"渋谷指導課長","answer":"施設整備の問題と、実際、指導の教育課程の問題とは別物です。人事上の措置につきましては、東京都教育委員会との協議の上で、校長１人、副校長３人というものを品川区として認めていただいているというものです。","voiceIndex":360,"id":"exchange-153"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後に、先ほどほかの委員からもありました。今、品川区は大都市の中にあって、非常に本社、オフィス街が近くにあり、交通便利な品川区です。ならば、やはりそういうところ、子どもたちがちゃんと受けられる施設というのですか、それはやはり考えていかないといけないと思います。このままいったら大変なことになると思いますので、私はしっかり見ていただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":362,"id":"exchange-154"},{"speaker":"あべ委員","kind":"質問・要望","question":"私からは、引き続き小中一貫校の法制化の話、それから１６８ページ、インクルーシブ教育と、その次の特別支援に関連しての質問、それから１６９ページのグローバル人材育成塾について、時間があれば学校保健などについても少しお伺いしたいと思います。小中一貫教育です。何点か質問させていただきたいと思います。それがどのようにお考えなのか。その２点をまず教えてください。","respondent":"渋谷指導課長、村尾教育総合支援センター長","answer":"私からは義務教育学校に関してのご質問にお答えします。１点目ですが、実際の教育活動、またその仕組み等について変更点はあるかですが、基本的な中身については変更点はないと考えているところです。実際に地域ごとにそれぞれ各教室に分かれてということの避難の部分ですけれども、実際に入れてもらえないという認識をもし持たれるのであれば、十分、保護者への説明が必要かなと思いますけれども、実際、子どもたち、教員が。","voiceIndex":364,"id":"exchange-155"},{"speaker":"あべ委員","kind":"確認","question":"確認ですが、管理職については、校長プラス副校長が、規模から言って２人にさらにプラスの副校長３人ということでよろしいですね。それから、前期課程修了、この卒業式なのですけれども、義務教育学校の形を重んずるあまりに、６年生で出ていくお子さんがあまり簡素にならないようにご配慮をいただければと思います。今はどのように考えていらっしゃるかお伺いいたします。","respondent":"渋谷指導課長","answer":"ただ、この事業の目的として、例えば一つには東京オリンピック・パラリンピックが実現したときに、このグローバル人材育成塾で学んだ品川の子どもたちが実際ボランティアで活躍していただけるような、そういうことにつながっていけばというふうな思いでおりますので。","voiceIndex":367,"id":"exchange-156"},{"speaker":"あべ委員","kind":"質問","question":"この事業は２,６００万円というのは、品川区のいじめ対策費の２倍なのです。かなりやはり大きい数字だと考えています。少し時間がありますので、２点お伺いしたいと思います。それからもう一つ、学校建設に関しまして、御殿山小学校の校舎の跡地は、解体後は定期借地という扱いになっているかと思いますが、年間お幾らでお貸しする予定になっているのか、ざっくりしたところを教えていただければと思います。","respondent":"野呂瀬学務課長、柏原企画調整課長","answer":"脊柱側弯検診のことですけれども、これにつきましては、今まで視診・触診でやっていたのですけれども、委員ご指摘のとおり、これはモアレ検査というのが大変有効だということ、それで放っておくと。御殿山小学校の隣地といいますか、隣の部分の貸付のところだと思います。現在では、プロポーザルで選定したときの段階の考えですけれども、年間１,７００万円ほどというような想定をしています。","voiceIndex":369,"id":"exchange-157"},{"speaker":"あべ委員","kind":"質問","question":"今の段階でちょっと１,７００万円が高いか安いかというのは、私も手元に資料を持ち合わせていないのですが、またこれについては引き続き、別の機会でお伺いしたいと思います。ただ、先日、御殿山小学校で運動会がありまして、既に非常にもう校庭が狭い状態でした。この敷地、子どものために使おうという議論もこれまでにあったのかどうかだけ教えてください。","respondent":"柏原企画調整課長","answer":"こちらのほうの地域が教育に資する部分というところはありますので、そういった議論もあったというのは事実です。","voiceIndex":372,"id":"exchange-158"},{"speaker":"安藤委員","kind":"質問","question":"私からは、１６６ページ、スクールカウンセラー、いじめ防止対策費にかかわって、ＬＧＢＴの学校現場での取組み、そして１６９ページ、図書館経費と、１７６ページ、芳水小学校改築基本設計委託にかかわって、大崎図書館の移転問題について伺います。以下、そう呼ばせていただきますが、主に学校現場での配慮を強めてほしいとの質問です。そこで伺います。教えてください。あわせて伺います。","respondent":"村尾教育総合支援センター長","answer":"区といたしましては、既に巡回相談員に対して全体説明会で、このセクシャルマイノリティーの対応についての周知徹底、それから各学校におきましては、特別支援コーディネーターを集めての連絡会、また人権教育の一つでもありますので、人権に関する研修会で各校１名。","voiceIndex":375,"id":"exchange-159"},{"speaker":"安藤委員","kind":"提案","question":"相談のところですが、明確な事例はないと。そこで具体的な取組みを提案します。そして、人権問題としてＬＧＢＴの問題を直接扱う授業を実施することを求めますがいかがでしょうか。２つ目ですが、教職員の研修にはＬＧＢＴがいるということを前提として児童・生徒に接することができるようになる、そうしたプログラムを盛り込むことを求めたいと思います。それぞれ求めますが、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"この部分につきましては大変潜在性を確保しながらやっていかないと、やはり子どもが、誰の話だということで、若干やっぱり子どもたち自身も不安になったり、また本当にあらぬ当事者探しみたいなものが行われるという危険性も大変高い状況ですので。","voiceIndex":377,"id":"exchange-160"},{"speaker":"安藤委員","kind":"質問・要望","question":"次に大崎図書館の移転の問題ですが、区が、３年後の平成３０年までに大崎図書館を御殿山小学校西側敷地に移転させると打ち出した計画に対して、利用者は猛反発しています。今年４月には図書館の存続と利用者や住民への説明会の開催を求める陳情を５０８人分、区長に出されたのですが、ここでも区長の回答は、説明会すら開かないということでした。老朽化がどうして移転になるのか、きちんとご説明ください。","respondent":"木村品川図書館長","answer":"繰り返しのご答弁になると思います。第２回定例会でご説明させていただいたとおりです。施設の老朽化、それからビジネス機能の移転に伴うもの、これが大きな理由です。","voiceIndex":379,"id":"exchange-161"},{"speaker":"安藤委員","kind":"質問","question":"ちょっとひどいのではないでしょうか。私が聞いたのは、老朽化は、それは３０年たてば老朽化しますよ。それは移転の理由にならないのではないかと。建替え、あるいは必要な修繕を行えばいいということですので、老朽化がどうして移転になるのか、飛躍があるのではないか、きちんとここら辺をご説明ください。","respondent":"木村品川図書館長","answer":"実際に、かなり、いろんなところで、そういう老朽している部分が出てきたものですから、実は移転先という形で新しいところを探していたところです。そのタイミングとして、そういう新しい部分が出てきたですので、このような全体計画になったものです。","voiceIndex":381,"id":"exchange-162"},{"speaker":"安藤委員","kind":"質問","question":"移転先をすぐ探すという、何といいますか、早いというか、何でそんな諦めるのだと。ですから、それを、ちょっと予算要求していたということでしたけれども、なぜ移転先を考えてしまうのかと。私が聞いたのは、ちょっと繰り返しになりますけれども、補修をすればいいのではないですか。それがあることが必要だという地域の声が出ているわけですから、しっかりと説明してください。","respondent":"木村品川図書館長","answer":"申し訳ございません。繰り返しのご説明になってしまいます。今までご説明したとおり、ご答弁したとおりです。","voiceIndex":383,"id":"exchange-163"},{"speaker":"安藤委員","kind":"質問","question":"私は、地域の利用者の方、中心とした地域の方が、その説明では絶対納得いきません。それは言いたいと思います。それで実際、品川区は代替施設と称して、大崎駅西口再開発ビル内、建替え後の芳水小学校２ヶ所に取り次ぎサービスコーナーと閲覧コーナーを設けると。これを代替施設にして地域に配慮すると説明しました。これが図書館の代替施設なのでしょうか。広さは何平米でしょうか。お答えください。","respondent":"品川庶務課長","answer":"これは間違いないようにお願いいたします。それから芳水小学校の件ですが、今、地下に委員からおっしゃったとおり６００平米の広さを設けてあります。地域開放スペースとして６００平米設けています。その中で、図書施設としましては５００平米を確保しようと考えています。","voiceIndex":385,"id":"exchange-164"},{"speaker":"安藤委員","kind":"質問","question":"広さ、狭さを問題にしているだけではないのです。図書館のかわりになるのですかということなのです。これが、蔵書、本を選べるのですか。この人は読み聞かせとか、あるいは自分で本を、ああ、今日はこれを読みたいと、その場で選んで読んだり、そういった、図書館のかわりになるのですかということを聞いたのです。これが図書館のかわりなのですかというのを一つお伺いしたいのと、移転の理由です。","respondent":"品川庶務課長","answer":"大崎図書館と同等の機能として芳水小学校にはスペースを確保しているです。それから、老朽化のみではなく、先ほどから図書館長が申しておりますように、理由は全て述べております。その中での総合判断ですので、ご理解をいただきたいと思います。","voiceIndex":387,"id":"exchange-165"},{"speaker":"安藤委員","kind":"質問・要望","question":"地域住民は、今の説明では納得いたしません。区の姿勢に不信を強める一方だと思います。このままごり押しするならば、反発はさらに強まると思います。理由なき移転、この跡地は道路の代替地にしようという話もあります。道路推進のために地域の環境と文化を壊す大崎図書館の移転計画は白紙にし、現地で存続するよう強く求めて質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":389,"id":"exchange-166"},{"speaker":"浅野委員","kind":"質問・要望","question":"家庭学習の機会が若干増えたという答弁がありましたが、若干というのがどの程度かわかりませんけれども、効果があるのであれば、今後、タブレット端末を支給していないといいましょうか、持っていない子の学校についても少しずつ拡大していくとか、そういうことも検討されてはどうかなと思いますが、いかがでしょうか。ホームページの更新頻度などについて確認されているのか教えてください。","respondent":"村尾教育総合支援センター長、野呂瀬学務課長","answer":"これは来年度、特別支援教室のほうに配備になるという部分ですけれども、現在のところ、この配備状況、またタブレットを使った学習等については、まさに先生方と一緒に考えながら進めている、現在検討中です。今後の配備計画につきましては、現在のところ未定ですけれども、導入した成果を見きわめて検討していくということになると考えております。","voiceIndex":391,"id":"exchange-167"},{"speaker":"浅野委員","kind":"質問・要望","question":"ホームページについてですけれども、そもそもアクセス件数がとれるようなシステムになっているかどうかという、こちらの問題もあるかと思いますが、できればそういうところまで調べていただきたいと思います。それに向けて、各学校のホームページの直近のチェックというのでしょうか。そういうのはされたのかどうか。そして、どのような学校なのかなということも確認していると思います。","respondent":"村尾教育総合支援センター長","answer":"今ご指摘された部分ですが、学校説明会の前に、やはり各学校は保護者のほうに通知するため、一つの大きなツールとしてホームページ、本当に大きく利用している部分だと感じております。","voiceIndex":394,"id":"exchange-168"},{"speaker":"浅野委員","kind":"質問・要望","question":"ぜひとも親御さんの期待に応えられるホームページを提供していただきたいと思います。１７３ページの外壁点検調査。平成２６年度の新しい事業ということで出ておりました。点検の内容ですけれども、こちらについて伺いたいと思います。やっと、平成２６年度に行われたということで、４年たってこういう状況かなと思います。こちらのほう、点検を行いまして、どのような問題があったのか教えてください。","respondent":"品川庶務課長","answer":"外壁の点検の内容ですが、モルタル等のタイルの落下防止の点検を行っている状況です。幾つか点検しまして、危険な箇所につきましては、今後、改修の工事を行っていくと、そのような考えです。","voiceIndex":396,"id":"exchange-169"},{"speaker":"浅野委員","kind":"質問","question":"東日本大震災のときに質問した中で、私の家の近くの小学校の外壁がぼろぼろとこぼれ落ちまして道路に散らばったということも例に挙げて質問させていただいた記憶があります。全て完璧にというのは、なかなかこれは無理があることではありますけれども、やはり子どもたちの安全、そしてまた地域の学校としての信頼性も含めまして、これからの取組みを強めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":398,"id":"exchange-170"},{"speaker":"渡辺委員","kind":"質問","question":"１６７ページの合同部活動実施経費を中心に伺いたいと思います。最近、体力向上という目標があります。その逆を言えば、特に都会、東京都が体力低下が課題であるがゆえに新たな目標ともとれますし、もちろんオリンピック・パラリンピックへ向けた流れもあるかと思います。なくても構わないです。さらに東京都の中で、では品川区の位置付け、小学生、中学生、どんな傾向があるのか、まず教えてください。","respondent":"村尾教育総合支援センター長","answer":"ただ、全体的に東京都の中では真ん中なのですけれども、都道府県で言うと、東京都はやっぱりまだ下の段階でいますので、どのような形で品川区自体、子どもたちの体力アップをしていくかというのはまだ課題ではありますけれども、本年度から体力向上プランということで。","voiceIndex":400,"id":"exchange-171"},{"speaker":"渡辺委員","kind":"確認","question":"いろいろな取組み、体育の時間もそうですし、この運動会シーズン、いろんなところで活発にやはり注目度もある中で、いろんな学ぶ場であると。その中で、やはり部活動への評価。端的に、導入から何年かたった中で、現状の合同部活動という点の成果と課題を改めて確認させてください。これは文化部の傾向だとか運動部の傾向も交えてコメントをいただければありがたいです。","respondent":"村尾教育総合支援センター長","answer":"合同部活動の現在の状況ですけれども、昨年度の実績から言いますと、合同部活動、いわゆる中学校を拠点として、ほかの中学校の他の生徒がそこに入部できるというような制度ですけれども、実際には現状としては中学生で言うと。","voiceIndex":402,"id":"exchange-172"},{"speaker":"渡辺委員","kind":"確認","question":"その辺の確認もしたいと思うのです。というのは、放っておいたら、やはり社会環境も変わっている。国や東京都がどう支えていくのか。あるいはその考え方が何か示されているのか教えてください。その中で、では現状、どんなことから手をつけていこう、あるいは、何でしょう、核となるものが、まず１つでも２つでも、新たなスタイルというものもあるのかなと思うので、この辺の考え方を教えてください。","respondent":"村尾教育総合支援センター長","answer":"中学生を特にターゲットとして、さまざまな、子どもたちが放課後、いろんな形で運動に取り組めるようなものと、それからこの合同部活動というものを何かしら対応ができないかどうか、また同じような活動が違う形でとれないかどうかということにつきましては。","voiceIndex":404,"id":"exchange-173"},{"speaker":"渡辺委員","kind":"質問・要望","question":"その検討にすごく注目するのと、幅の広い観点でもいいのかなと思っています。というのは、やはり公共がやるべきことがあると思うのです。やはり公共がなすべきことも存分に部活動であるかと思います。そして大学や企業力も都会ならではのやり方を、この品川区でぜひ発信していただきたいと思いますが、そういうのも踏まえて、今後の新しいスタイルというものでお考えを聞きたいと思います。","respondent":"村尾教育総合支援センター長","answer":"そのような大きな構想で、今後とも進めていこうと考えています。","voiceIndex":406,"id":"exchange-174"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1414#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":125477,"voices":408}},{"id":"h27-20151020-4","meetingId":"h27-c-settlement","date":"2015年10月20日","dateIso":"2015-10-20","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時４０分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を120件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"初めに、オリンピック・パラリンピック関連のことでお伺いしていこうと思います。いよいよ、２０２０年、東京オリンピック・パラリンピックまで、あと５年を切りました。ホッケー競技が開催される大井ふ頭中央海浜公園の競技会場建設のスケジュールと、それからビーチバレー競技が開催される潮風公園の建設のスケジュールをお聞かせください。","respondent":"安藤文化スポーツ振興部長","answer":"平成２８年度中には実施設計に着手し、平成２９年度のいずれかに工事を開始する予定で、平成３１年度のテストイベントまでには竣工予定という見込みです。次に、潮風公園のビーチバレー競技ですが、仮設のビーチバレー競技場でもあります。","voiceIndex":2,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"特に大井ふ頭中央海浜公園は日常的に多くの区民が利用しております。平成３１年のテストイベントまでに完成ということですけれども、完成後は、オリンピック開催前・後とも、しっかりと区民優先での利用ができるように求めていきたいと思いますけれども、改めてお考えをお聞かせください。大井ふ頭中央海浜公園競技場のオリンピック・パラリンピック終了後の後利用についてもお聞かせください。","respondent":"安藤文化スポーツ振興部長","answer":"競技場の建設に当たっての区民への影響ですが、現行の利用者への、影響ができるだけ少なくなるように、これまでも東京都に要望してまいりました。今後も都からの情報収集に努め、利用者への周知についても早目に行うよう働きかけてまいります。","voiceIndex":4,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"また第２回定例会の一般質問でも行いましたけれども、障害者スポーツの振興は高齢者スポーツの振興にもつながり、障害者がスポーツを楽しめるグラウンドや体育館の整備は、高齢者にとっても同じようにスポーツに励む環境が整備されるということで、超高齢化社会を迎え、健康寿命を延ばしていくためにも、これもある意味、オリンピック・パラリンピックのレガシーとして。","respondent":"安藤文化スポーツ振興部長","answer":"先日行われましたホッケーフェスタの総括ですが、フェスタを実施するに当たりまして、ホッケーの認知度を高めるために、さまざまな仕掛けをしてきました。区内の４地域でホッケー教室を実施いたしまして、区民の皆さんに周知してまいりました。","voiceIndex":6,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"ホッケーフェスタはまだ初めてということで、これからしっかりと、ホッケーの認知度はまだまだ区民の中でも低いと思いますので、これから４年半後に向けて、しっかりと盛り上げていっていただきたいと思います。あわせて、既に区内在住・在勤のトップアスリートや、将来有望な少年少女選手を把握して支援していく仕組みがあってもいいのではないかと思うのですけれども、改めてお考えをお聞かせください。","respondent":"安藤文化スポーツ振興部長","answer":"そんなことから、区としては東京都の動向を今後ゆっくり見守りたいと考えています。そしてもう一つ、区内の将来有望なアスリート、特に少年少女のアスリートと申しましょうか、少年少女につきましては、何らかの形で支援していけるように検討してまいります。","voiceIndex":8,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"防災対策についてお伺いいたします。１週間で考えると半分以上の時間を占める夜間・休日に発災した場合、総合庁舎から震度５弱で６キロメートル圏内に居住している職員が参集し、震度５以上で全ての職員が応急対策をとるということになっていますけれども、そのうち、そもそも現在、職員の何％ぐらい、何人ぐらいが６キロメートル圏内に居住しているのでしょうか。","respondent":"曽田災害対策担当部長","answer":"優先順位の高い業務に対して、参集してきた職員を逐次割り振って、応急対策を実施していくということになります。続きまして、各地域センターに参集する職員でありますが、これはセンターによって異なりますが、１０名から４０名の職員が参集いたします。","voiceIndex":10,"id":"exchange-005"},{"speaker":"沢田委員","kind":"意見","question":"そのためには、やはり初期のマンパワーが大変重要で、今、４０％、１,０００名の職員ということでしたので安心しましたけれども、まず４０％の職員で、これで大丈夫、初期の段階では大丈夫と考えていらっしゃるのかお聞かせください。被害状況の把握には、やはり地域の力が欠かせないと思います。町会長、自治会長に配ったタブレット端末を活用した訓練というのはどのように行っているのかお聞かせください。","respondent":"曽田災害対策担当部長","answer":"大規模震災発生時に初動対応をするのは、やはり、委員ご指摘のように、６キロメートル圏内に居住する職員が中心になると考えております。","voiceIndex":12,"id":"exchange-006","title":"町会・自治会支援"},{"speaker":"沢田委員","kind":"質問・要望","question":"やはり、大震災がいざ起きたとき、当然、緊急車両は各地で起きる全ての火災現場に向かうことはできません。町会はもとより消防団、区民消火隊のさらなる活性化、訓練の充実、支援の拡充が求められています。震災直後のような緊張感を持って継続的に訓練や支援の拡充を図っていくべきだと考えますけれども、お考えをお聞かせください。","respondent":"曽田災害対策担当部長","answer":"今後も各種防災訓練においては、より実際的なシナリオのもと、緊張感を持って実施できるよう工夫するとともに、さまざまな支援もあわせてしっかりと取り組んでいきたいと考えております。","voiceIndex":14,"id":"exchange-007"},{"speaker":"沢田委員","kind":"質問・要望","question":"一部の区の防災計画との整合性も気になるところですし、そういった部分で、各消防署で『東京防災』活用のためのセミナーをやられていたかと思うのですけれども、先週まででそれも終了したということですけれども、区内のセミナー参加者はどの程度いたのか、またオリジナル防災マップが作成できますけれども、区としてはこの『東京防災』をどのように捉えて、どう活用していくべきと考えているのか。","respondent":"曽田災害対策担当部長","answer":"品川区内の消防署に連絡して確認したところ、このセミナーには２種類ありまして、各消防署で実施するもの、それから消防署員がまちの行事に出向いて実施するセミナーの２種類がありまして、このセミナーの合計の実施回数が２６３回。","voiceIndex":16,"id":"exchange-008"},{"speaker":"沢田委員","kind":"質問","question":"災害時の医療救護所についてお伺いいたします。９月１日、昭和大学病院と品川区が初めて合同で実施した医療救護所訓練がありました。私も見学してまいりましたけれども、さまざまな課題があったと考えますけれども、この訓練の概略と、区としての大まかな総括というか、簡単な総括をいただければと思います。","respondent":"矢野健康推進部長","answer":"９月１日の医療救護所開設訓練は、昭和大学病院と第二延山小学校を会場として実施し、訓練参加者数は総勢約１,２００名で、区職員は２１名が参加しました。","voiceIndex":18,"id":"exchange-009"},{"speaker":"沢田委員","kind":"質問・要望","question":"大変重要な訓練であったと思います。これからもしっかりとしていかなくてはいけないという中で、幾つか課題について質問させていただきたいと思います。区としての考え方をお聞かせいただきたいと思います。高度なシステムを、区や医師会などと共有化を図っていくということができないのかということ、このあたりのお考えをお聞かせいただければと思います。","respondent":"矢野健康推進部長","answer":"昭和大学のシステムについてですが、昭和大学が使用するタブレット端末を使用したトリアージシステムについては、今回初めて見せていただき、病院内の活用において大変有効であると思い、参考とはさせていただきたいと思いますが、区や医師会などとの共有化については。","voiceIndex":20,"id":"exchange-010"},{"speaker":"沢田委員","kind":"質問・要望","question":"医師会、薬剤師会、歯科医師会の具体的な役割について、どのようにお考えを持たれているのか。地域の方との連携も欠かせないと思います。今回の訓練には地域の方が学校医療救護所のほうには参加されていませんでしたけれども、今後、学校医療救護所における、町会、地域の方も含めた訓練の実施が必要ではないかと思いますけれども、お考えをお聞かせください。","respondent":"矢野健康推進部長","answer":"今後の課題として、町会や地域の方々を含めた医療救護所開設訓練実施は重要と認識しております。今後は開設訓練の実施を積み重ね、課題の検証による計画の実効性の担保、追加配備などを行いながら、よりよい災害時医療体制の構築に努めてまいります。","voiceIndex":22,"id":"exchange-011"},{"speaker":"沢田委員","kind":"意見","question":"緊急医療救護所となり得る病院が近隣にない学校医療救護所は、まず区内にどれぐらいあって、その場合、重症者の搬送手段はどのように考えられているのか、またその場合、学校医療救護所への医薬品等の備品の配備はある程度充実していかなくてはいけないと思うのですけれども、お考えをお聞かせください。","respondent":"矢野健康推進部長","answer":"重症者の搬送体制については、救急車の出動、庁有車、雇上げ車両等により搬送する計画ですが、民間救急の活用など新たな方策も検討してまいります。","voiceIndex":24,"id":"exchange-012"},{"speaker":"沢田委員","kind":"質問・要望","question":"なかなか区内、大きな災害拠点病院とか緊急医療救護所が設置できるような病院が少ないということもあるかと思うのですけれども、学校医療救護所でも的確なしっかりとした医療救護が行えるような体制の充実を、これからもしっかりと進めていっていただきたいと思います。小規模な病院は閉まっているということを周知していくという必要があると思うのですけれども、そのお考えをお聞かせください。","respondent":"矢野健康推進部長","answer":"災害時医療救護体制の周知につきましては、重要性は認識しておりますので、引き続き、災害医療連携会議等において課題を協議し、計画が固まった段階で周知していく予定です。","voiceIndex":26,"id":"exchange-013"},{"speaker":"沢田委員","kind":"質問・要望","question":"初期の段階の医療救護所というのは大変重要だと思います。次に、東日本大震災後の、区としての被災地支援に関してお伺いします。４年半が過ぎました。現在、発災直後から区として職員派遣や、区営住宅・区民住宅への被災者の受入れ、被災地支援応援ツアーなど、さまざまな形での被災地支援を行っていますけれども、現在の被災地側のニーズはそれぞれどのようになっているでしょうか。","respondent":"田村総務部長、安藤文化スポーツ振興部長","answer":"仕事内容につきましては８名全員、仕事内容が異なりますが、主な内容を説明しますと、水産施設、これは漁港のことなのですが、水産施設等の災害復旧事業に携わっている職員。品川区は被災地の復興支援のために、被災地応援ツアー事業を平成２３年度より継続して実施しています。平成２７年８月２５日、東京都の実施している被災地応援ツアーにて不正受給の事実があったことを確認いたしました。","voiceIndex":28,"id":"exchange-014"},{"speaker":"沢田委員","kind":"質問・要望","question":"今後もこの思いは変わらないですし、これからもしっかりと、これをきっかけに、真面目にこの事業に取り組んでいた事業者が委縮することがないように、また今後もしっかりと継続して、この被災地支援、また被災地支援事業をしっかりと行っていっていただきたいと思います。この事業のしっかりと再構築を図っていただきたいと思います。以上で私の質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-015"},{"speaker":"渡部委員","kind":"質問","question":"沢田委員に続き、総括質問を始めます。初めに、今年度、地方教育行政の組織及び運営に関する法律の一部改正がありました。概略については理解していますが、改めてこの法改正が行われた背景と、品川区がこれに伴って行っている施策についてお教えください。","respondent":"田村総務部長","answer":"改正のポイントですが、いろいろありますが、ポイントだけ説明しますと、１つは、先ほどお話しした、責任の明確化を図るということと、２点目が、迅速な危機管理体制の構築を図る。","voiceIndex":33,"id":"exchange-016"},{"speaker":"渡部委員","kind":"質問","question":"それで、ここでお伺いしますが、この総合教育会議の中で、教育大綱の策定と、いわゆるそのほかに教育条件の整備等、重点的に構ずべき施策の協議・調整というのが掲げられていますが、いわゆるこの教育大綱というのはどのような内容となっていくのかお教えください。そして、品川区では、重点的に構ずべき施策の協議・調整はどのように取り組まれていくのかをお教えください。","respondent":"中山企画部長","answer":"大きく現状等を踏まえて基本理念と方針というふうになっておりますけれども、方針といたしまして大きく５つ掲げておりまして、就学前教育の充実、学校教育の充実、そして青少年教育の充実、生涯学習の充実、最後に文化芸術の振興というのが５つの方針となっております。","voiceIndex":35,"id":"exchange-017"},{"speaker":"渡部委員","kind":"確認","question":"第１回の会議の内容等も確認させていただきました。教育委員の皆様から活発な発言がなされていたことを確認しています。保護者の立場から、いじめの諸問題、教育者の立場から小中一貫教育や市民科について、地域の立場から地域や保護者、学校とのかかわりなどが多数発言されていますが、これらのご意見等は、今申されましたような大綱のほうに、しっかりと方針に反映されているのでしょうか。","respondent":"中山企画部長","answer":"ご意見の例ですけれども、例えば第１回、これは骨子を示して意見をいただいたという段階でありますけれども、「地域、家庭、学校の連携による教育環境の充実、それから地域の歴史・文化を学ぶ大切さ、それから学力向上。","voiceIndex":37,"id":"exchange-018"},{"speaker":"渡部委員","kind":"質問","question":"方針の中、この大綱の中で、品川らしさも多数掲げられているということで、大変すばらしく思います。さっきの款別審査でも申し上げましたように、向こう３年間を見ましても、地域によっては児童数の増加が、本年比で約１９％が見込まれているような地域もあり、喫緊の課題と考えています。それで、適正配置に対する考え方をお伺いいたします。","respondent":"本城教育次長","answer":"よりよい教育環境を実現するための学校配置の在り方につきましては、このような総合的な検証・検討を実施していくことが必要であると考えるものです。","voiceIndex":39,"id":"exchange-019"},{"speaker":"渡部委員","kind":"質問","question":"配置の在り方もありがとうあります。さまざまな問題を抱えると思います。老朽化の進んでいる学校もあると思いますので、よろしくお願いいたします。総合教育会議についていろいろ伺ってきました。区長が設置します会議です。これからの展望、品川区の取り組むべき姿について、最後に区長よりお話しいただけますでしょうか。","respondent":"濱野区長","answer":"総合教育会議を設置いたしまして、教育委員会とさまざまな協議を進めているところであります。常々、私は申し上げていることは、教育には２つの役割がある。","voiceIndex":41,"id":"exchange-020"},{"speaker":"渡部委員","kind":"質問","question":"続けて教育について伺っていきます。これは、品川区がこれまでの間、独自に行ってきた教育改革プラン２１が国を動かした結果だと考えます。そこで伺いますが、品川区教育委員会として、国における小中一貫教育の法制化への評価、ならびに現在の施設一体型小中一貫校から品川区立義務教育学校への移行についてどのような検討がなされ、どのような手続で進められるのかお答えください。","respondent":"本城教育次長","answer":"地域との連携をさらに進めまして、ともに教育を考えていく仕組みをつくり、その中におきましてグローバル人材の育成、そして体力の向上等の新たな課題に対応していきたいと考えているところです。","voiceIndex":43,"id":"exchange-021"},{"speaker":"渡部委員","kind":"質問・要望","question":"今、概略等も伺いました。小中一貫校６校がスムーズに品川区立義務教育学校へ移行されることを切に願います。小中一貫校に対する評価、これも伺いました。そして、平成２８年２月に品川区教育フォーラムが開催されると伺っています。これらの目的と意義をお示しいただくとともに、内容についてお教えください。参加される方はどのような方々なのでしょうか。あわせて教えてください。","respondent":"本城教育次長","answer":"内容についてですが、義務教育学校の開校を踏まえました品川区の今後の教育体制、そして地域協働の仕組みとしての品川版のコミュニティ・スクール、あるいは道徳の教科化や小学校英語等、教育課題への対応について提言を行うものです。","voiceIndex":45,"id":"exchange-022"},{"speaker":"渡部委員","kind":"質問・要望","question":"２月のフォーラムの盛会を願っています。これらの団体が地域の核として学校を捉えて、多くの場面で協力をいただいている。かねてより、品川区議会自民党・子ども未来では、コミュニティ・スクールや付随する地域支援学校本部の設置を要望してまいりました。国においても、平成２７年３月の教育実行再生会議、第６次提言の中で、「全ての学校がコミュニティ・スクール化に取り組まれたい」とされています。","respondent":"中島教育長","answer":"私どもといたしましては、今後はこれらの成果とか課題を十分踏まえて、他地域でも拡大していくよう、積極的に検討していきたいと考えております。","voiceIndex":47,"id":"exchange-023"},{"speaker":"渡部委員","kind":"質問・要望","question":"教育長、ありがとうございました。これからいろいろ進めていただきたい。それぞれにそれぞれの方法が必要なのかなとも思うのですが、共通の取組みこそがまた必要なのかとも思います。特段注意しなければいけない点、留意する点を挙げていただくとともに、逆に今までのこの制度の中で行われています外部評価委員会制度をはじめとした各種施策との整合について、お答えいただければと思います。","respondent":"中島教育長","answer":"他地域への拡大ですけれども、それぞれの学校単位に、この品川版のコミュニティ・スクールの協議会と学校支援地域本部という、これらを設置していきたいと考えております。","voiceIndex":49,"id":"exchange-024"},{"speaker":"渡部委員","kind":"質問・要望","question":"そこに制度として、国の求めてきた制度。もともと品川はやっていたことを今度、制度に乗せてやるということで進めていただきたい。この質問は終わります。次に、区民の健康について伺います。こうした状況の中、本年４月にしながわ健康プラン２１が策定されました。ここで質問しますが、今回、１２年ぶりに健康プランの改訂に至った背景と、旧プランと新プランとの相違点、改善点についてご説明ください。","respondent":"矢野健康推進部長","answer":"新プランでは、国の健康日本２１に示されている、「栄養・食生活」、「身体活動・運動」、「飲酒」、「喫煙」、「歯・口腔の健康」、「糖尿病」、「循環器病」、「がん」という生活習慣病など９つの分野設定との整合性をとり、その取組みを積極的に進めていくこととしました。","voiceIndex":51,"id":"exchange-025"},{"speaker":"渡部委員","kind":"質問","question":"今回策定したしながわ健康プラン２１を着実に実践し、実りのある成果を上げていくためには、区民への積極的な啓発と行政からの十分な支援が必要となってくると考えますが、区はいかがお考えでしょうか。特に健康への関心が薄いと言われる若年層への周知や啓発はどのように行うつもりかご説明ください。","respondent":"矢野健康推進部長","answer":"企業との連携も進め、企業が持つ健康づくりに関するノウハウを活用し、多様な事業展開を図る予定です。具体的には、企業との連携により、がん検診受診啓発や禁煙啓発などの準備を進めております。","voiceIndex":53,"id":"exchange-026"},{"speaker":"渡部委員","kind":"質問","question":"生活習慣病の若年齢化についてですけれど、たびたびこれは警鐘が鳴らされているところであります。それで、平成２５年度より開始された「３５歳からの健康診査」は、この低年齢化傾向にある生活習慣病の予防のために始まったと、ある意味、私は理解しているのですが、この健診の意義と受診率、そしてここから見えてくる現状と課題についてご説明をお願いします。","respondent":"矢野健康推進部長","answer":"より多くの方に受診していただくことももちろんですが、もっと若い世代からの生活習慣病対策の働きかけを検討する必要があると考えているところです。","voiceIndex":55,"id":"exchange-027"},{"speaker":"渡部委員","kind":"提案","question":"しかし、今の回答を伺っていますと、やはり男性も少ないですし、健診内容をしっかりと見直した上で、高い数字がありますし、今、答弁もいただきましたが、これはこの際、２０歳から健康診査を行う重要性と必要性というものが非常に強く感じられます。改めて、２０歳からの健康診査を自民党・子ども未来は提案いたしますが、区としてのご見解はいかがでしょうか。","respondent":"矢野健康推進部長","answer":"現在、区では、「女性の健康診査」と「３５歳からの健康診査」を事業として実施しておりますが、ご提案の２０歳からの健診の実施につきましては、現在の事業の状況と課題を踏まえ、検討してまいりたいと思います。","voiceIndex":57,"id":"exchange-028"},{"speaker":"渡部委員","kind":"質問・要望","question":"成人歯科検診においては、我が会派からの要望により歯のクリーニングを導入されたことは、さらなる受診率の向上、健康意識の高まりに寄与することと大変期待しております。さらなる意識の高まりを目指すとともに、治療より予防といった観点から、例えば２０歳の記念に歯科検診、３０歳の歯科検診など、区民の健康増進に向けたさらなる取組みについて重ねて要望します。","respondent":"矢野健康推進部長","answer":"記念イベントでの検診実施などのご提案も踏まえ、今後の検討課題としますが、当面は歯のクリーニングの実施により、少しでも多くの方に歯科検診を受けていただきたいと考えておりますので、この動向を注視していきたいと考えております。","voiceIndex":59,"id":"exchange-029"},{"speaker":"渡部委員","kind":"質問","question":"医療費はこれから先、どんどん増大するもの。これをどのようにしていくか。予防のためにはやはり検診をというところがありますので、これからもどうぞよろしくお願いいたします。以上で健康についての質問を終わります。次に、品川の環境と公園について伺います。ここでお伺いしますが、今まで区では動植物調査をどのように行ってきたのかお教えください。生物多様性について、区のお考えをお示しください。","respondent":"藤田都市環境部長","answer":"こうしたさまざまな取組みとあわせて、旧来からの日本の生態系を守るようなことをしっかりと進めていく必要があると考えてございまして、オオキンケイギクあるいはミドリガメと言われたミシシッピアカミミガメなど、従来は特に影響がないとされていたものも。","voiceIndex":61,"id":"exchange-030"},{"speaker":"渡部委員","kind":"質問・要望","question":"都市部だからこその課題などもあると思います。区民の方々を巻き込んでしっかりとやっていただきたいという思いもあります。みどりの実態調査、自然調査等に、多くの区民の方々に呼びかけて、我がまちの自然環境を知っていただくのにいい機会と捉えるのですが、協力してしっかりやっていくようなことはできないでしょうか。ちょっとお考えを。","respondent":"藤田都市環境部長","answer":"こうした取組みもあわせて進めることで、自然環境への関心を高めていきたいと考えています。","voiceIndex":63,"id":"exchange-031"},{"speaker":"渡部委員","kind":"提案","question":"さまざまな活動をされていて、施策をどんどん推し進めていただくことも要望しています。これを踏まえて、公園の利活用について伺います。地域の知恵と力を活用し、魅力ある公園づくりを進めていただくこと。いわゆる、この自然環境の部分で提案していきます。区民公園の利活用について、この部分で提案いたします。この公園へ、どのような形で改築を進めていただけるでしょうか。よろしくお願いします。","respondent":"松代防災まちづくり部長","answer":"例えば、しながわ中央公園では、ＮＰＯ団体と連携した自然観察会が行われ、多くの方々の参加をいただいておりまして、これからも地域の知恵と力を発揮できる場として公園を活用していただけるよう取り組んでまいります。","voiceIndex":65,"id":"exchange-032"},{"speaker":"あくつ副委員長","kind":"提案","question":"私は、区議会公明党を代表して、若林議員とともに総括質問を行います。初めに、品川区立障害児者総合支援施設と障害者の芸術活動について伺います。かつて糸賀一雄氏が提唱した、「この子らを世の光に」という理念は、滋賀県の障害者福祉全体の特徴をあらわしており、今回の参入に当たり、その理念を大きく品川区にも導入していただきたいと思いますが、ご見解を伺います。","respondent":"榎本福祉部長","answer":"（仮称）障害児者総合支援施設の位置付けですけれども、この施設は、知的障害、身体障害をはじめ、精神障害や、手帳を持たない発達障害などにも対応した施設ということで、障害のある方が地域での生活を継続するための拠点施設として位置付けているものです。","voiceIndex":69,"id":"exchange-033"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"「この子らに世の光を」ではなくて、「この子らを世の光に」という非常に大事な視点だと思いますので、ぜひよろしくお願いしたいと思います。視察の際、グローの理事長から、今、週に１回から２回は上京して、円滑な施設運営を行うために所管課と意見交換を意欲的に行っていると伺いました。反面、共同事業であり地元ではないゆえに、一層のコーディネートとコントロール機能が品川区には求められます。","respondent":"榎本福祉部長","answer":"その際、区におきましては基幹型の相談支援センターを持っておりまして、区内障害者福祉施策の全体調整の機能を持つ２法人に加えまして、新たな法人とともに連携し、区は全体のコーディネートとしてさらに力を注いでいきたいと考えております。","voiceIndex":71,"id":"exchange-034"},{"speaker":"あくつ副委員長","kind":"質問","question":"アール・ブリュットやダンスなど、障害者の芸術活動について伺います。今後、障害者の福祉現場においても、美術大学等と連携したり、福祉職員がワークショップに参加することなどを通じて、芸術分野の人材と交流し、芸術に対する理解を深めるとともに芸術活動を支援する方法を学んだり、福祉教育の現場において障害者の芸術活動に触れる機会をつくることが必要であると考えますが、いかがでしょうか。","respondent":"榎本福祉部長","answer":"それから２点目のアール・ブリュットのほうの福祉の現場の職員にとっても、やはり言葉でのコミュニケーションが難しい障害者に対する意識を変えることができるということや、ワークショップにおきましては、福祉職員だけではなくて大学等と連携することで。","voiceIndex":73,"id":"exchange-035"},{"speaker":"あくつ副委員長","kind":"提案","question":"その流れで続けますが、品川区立障害児者総合支援施設のプロポーザル案の中にはアール・ブリュット美術館が提案されています。最後に、障害者の芸術活動、繰り返しになりますが、芸術性が高く、力強い魅力を持っていますので、今後、区民芸術祭のプログラムとして位置付けることも含め、品川区の芸術運動の大きな柱の一つとして育成していただきたいと思いますが、いかがでしょうか。","respondent":"榎本福祉部長、安藤文化スポーツ振興部長","answer":"まちとコラボレーションした企画展などについても、積極的に実施していきたいという考えです。私からは、区としてアール・ブリュット等の文化プログラムに参加を、またアール・ブリュット等を品川の文化芸術の柱にして品川区民芸術祭との連携をというご質問についてお答えいたします。","voiceIndex":75,"id":"exchange-036"},{"speaker":"あくつ副委員長","kind":"質問","question":"子どもの貧困について伺います。昨年、厚生労働省が発表した平成２５年国民生活基礎調査による子どもの相対的貧困率は過去最悪の１６.３％で、１７歳以下の子どもの６人に１人、３００万人余りが貧困状態にあるとされ、全国にショックを与えました。品川区として数が出せないのであれば、その理由と、できる限り子どもの貧困の実態を調査する必要があると考えますが、いかがでしょうか。","respondent":"榎本福祉部長","answer":"ひとり親家庭につきましても、自立支援相談員等により、相談の中で把握しているということで、そういったきめ細かな相談の中で把握しているという形で進めていきたいと考えております。","voiceIndex":78,"id":"exchange-037"},{"speaker":"あくつ副委員長","kind":"質問","question":"わかる数値も若干はあるということでしたが、そういうことについては、もし時間があれば、後ほどまた調査については伺いたいと思います。品川区の就学援助とはどのような制度であるか。受けられる対象、所得の目安の基準額を教えてください。後ほどで結構です。就学援助の対象ではない、私立・国公立等の小中学校の児童・生徒数も含めた、平成２６年度７月時点での学齢期の子どもの全人口数を教えてください。","respondent":"本城教育次長","answer":"就学援助の制度についてですが、こちらにつきましては、経済的困難と認められる区立の小中学校の保護者に対しまして学用品等の援助を行うものでございまして、義務教育を円滑に実施することを目的としているものです。","voiceIndex":80,"id":"exchange-038"},{"speaker":"あくつ副委員長","kind":"意見","question":"品川区は生活保護の基準に１.２５を掛けた課税所得を準要保護世帯としております。次に、品川区でこの就学援助を受けている小中学生の児童・生徒数は４,７１３人です。これは、今ご答弁があったとおり、全区立小中学校の児童・生徒数の２５.５％であり、全国平均の１５.４％と比較しても高い数字です。この段階で、品川区の区立小中学校生の４人に１人以上が就学援助を受けている。","respondent":"榎本福祉部長","answer":"訪問支援ということで、アウトリーチという形でも相談は開始しておりますので、そういうものも工夫しながら、いろいろと進めていきたいと考えています。","voiceIndex":82,"id":"exchange-039"},{"speaker":"あくつ副委員長","kind":"質問","question":"分析と評価というところで、今後の対策についてのお考えを伺いました。次に、品川区の子どもの貧困に対する対応について伺います。先ほど一部は伺いました。今までも各所管ごとに誠実に対応されてきたことと思いますが、品川区の子どもの貧困に対し、全庁的にどう取り組んでいかれるのか、その決意を伺います。品川区としてその責任をどの部署に置くのか教えてください。","respondent":"榎本福祉部長、金子子ども未来部長","answer":"相談その他の低所得者向けの受験生チャレンジ支援ですとか、生活保護受給者への塾代の支援等、親に対しての就労支援による就労相談等に応じておりまして。私どもでは、ひとり親家庭の支援について所管しておりますので、ひとり親家庭の支援についてご説明申し上げます。現段階では新たな組織編成等はしておりませんけれども、中心となる部署におきましては、法制度などの動向を踏まえながら、福祉部、子ども未来部。","voiceIndex":84,"id":"exchange-040"},{"speaker":"あくつ副委員長","kind":"質問","question":"２００８年に発見された理念、考えというふうに言われていますけれども、ぜひ、どこかが責任を持つという形でしっかり取り組んでいっていただき、現段階ではないということでしたけれども、今後はよろしくお願いします。地域の第三者がキャッチした場合、ときには貧困状態にある子ども自身がどの窓口にアプローチすればよいのか、周知方法の工夫が必要だと考えますが、教育委員会も含めご所見を伺います。","respondent":"榎本福祉部長、金子子ども未来部長、本城教育次長","answer":"前倒しして各所管でできる拡充策はですけれども、生活保護の関係におきましては、子どもへの支援策として。特に拡充あるいは新規事業ということですけれども、先ほど申しました子どもの学習支援事業につきましては、非常に好評ではありますが。それから今度、子どもへのアプローチですけれども、まず地域の第三者がキャッチした場合ですけれども。教育委員会あるいは学校の中での関係のかかわりですが、まず教育委員会における子どもの貧困への対応に関しましては。","voiceIndex":88,"id":"exchange-041"},{"speaker":"あくつ副委員長","kind":"質問","question":"それぞれご答弁ありがとうございました。以上で私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-042"},{"speaker":"若林委員","kind":"質問","question":"基金のほうから伺いたいと思います。これまでの説明では、学校改築や高齢化など、需要を満たすことができる経費の計画を立てながら積み立てているというふうにご説明がされてまいりましたけれども、その内容についてはまだ伺ったことがございません。款別審査の中では、今後必要な基金を積み上げていくと１,０００億円となるということも今回初めて示されたです。","respondent":"中山企画部長","answer":"これは学校以外の施設・インフラ等の整備ですけれども、区有施設中長期改修計画等でも、今後２０年ぐらいの中でやはり約３５０億円程度の経費が必要になってくるというふうな見込みがありまして、これも同様の考え方で。","voiceIndex":96,"id":"exchange-043"},{"speaker":"若林委員","kind":"質問","question":"１,０００億円の意味が大体わかりました。要するに、この基金を今後どのように活用していくかという観点で、何点かご質問を続けします。教育環境を整備することにより、地域とともにある学校づくり、子どもたちの生き抜く力を育むといった教育政策の面から質問をいたします。受入れ人数を確保して、現状の学校数の中で良好な教育環境を整備するための取組みなどについてお聞きいたします。","respondent":"本城教育次長","answer":"今後の就学人口の増加に対する学校の教育環境の関係ですが、基本的には、既存の普通教室のスペースでは、数では対応が難しい場合については、それら普通教室以外の、例えば多目的室ですとかランチルーム等々について。","voiceIndex":98,"id":"exchange-044"},{"speaker":"若林委員","kind":"質問","question":"一定の適切な規模が必要と思います。今後、コミュニティ・スクールを導入し、学校と地域が相互に支援と貢献をし合う関係を築き、連携して子どもたちを９年間を通して育んでいこうとされていることを款別審査でも伺いました。対応するに当たっては、保護者や地域などの理解と協力のあり方など、地域とともにある学校づくりの考え方、取組みについてもお聞きしたいと思います。","respondent":"本城教育次長","answer":"それとの関係ですが、これから地域とともに歩む学校づくりの考え方に取り組むに当たりましては、そのような品川版のコミュニティ・スクールの取組みにおきましては、学校の地域コーディネーターというものを配置しまして。","voiceIndex":100,"id":"exchange-045"},{"speaker":"若林委員","kind":"確認","question":"今の学校運営協議会と学校との関係が、今、強調されてご説明されましたけれども、一方で、教育委員会といわゆる三角の関係といいますか、３つの組織が出るということで、学校にとっては、教育委員会と運営協議会を両方見ながら進めるというようなイメージもあるかと思うのですけれども、逆にこういったことが、先ほど副校長先生の負担の問題ということもありましたけれども。","respondent":"本城教育次長、中島教育長","answer":"学区域の就学人口の増の関係ですが、そちらあたりは、学校環境を整備するに当たっては、物理的なスペースの確保をできるかどうかが基本的な条件として常に検証していかなければいけないところである。このような形で教科との関連性を重視してこれまでにも取り組んできている状況があります。","voiceIndex":102,"id":"exchange-046"},{"speaker":"若林委員","kind":"質問・要望","question":"くれぐれも、環境の変化に対応してのご配慮は重ねてお願いしたいと思います。今、教育長から、生きる力、生き抜く力についてのお話がありました。そこで、次期学習指導要領の改訂のポイントをお聞きしておきたいと思います。品川区への影響についてですが、これまでの取組みをさらに進めようとするものや、新たに対応が必要になるものなど、今後の取組み、変化についてもお聞かせいただきたいと思います。","respondent":"中島教育長","answer":"この新しい内容につきましては、私どもの市民科と道徳との整合性ですとか、いろいろな課題がありますので、今後、教員を中心とするカリキュラム検討委員会を立ち上げまして、その課題や成果について検証し、来年の夏に示される予定となっている指導要領に合わせて。","voiceIndex":105,"id":"exchange-047"},{"speaker":"若林委員","kind":"質問","question":"続きまして、この中にも出てきますけれども、体づくり、体力について伺いたいと思います。現在、区では、スポーツトライアル、テクニカルアドバイザーの配置、ワンミニッツエクササイズの３つの取組みをスタートさせております。字を書くときに背中を丸める。校長先生が巡回相談に来た作業療法士にお話を伺ったところ、体幹が育っていないこと、生活習慣ができていないことなどを指摘されたそうです。","respondent":"中島教育長","answer":"１分間でできる、日常的に習慣をつくれる簡単な運動を紹介していこうという、もう既に何校かモデル校でやっておりますけれども、親子でのふれあい時間ができたですとか、これは継続させていきたいというような前向きなご意見も頂戴しているところでもあり。","voiceIndex":107,"id":"exchange-048"},{"speaker":"若林委員","kind":"質問・要望","question":"昨年の議会の文教委員会のほうでも福井県に伺って、学力・体力の向上ということについての行政視察を行ったことを伺っております。特別養護老人ホームについて伺います。人口推計では、４０年後の平成６７年に高齢者人口がピークを迎えるということになりました。公共施設等総合管理計画策定以降、特養ホームの検討や計画を立てることについてのお考えもお聞きしたいと思います。","respondent":"榎本福祉部長","answer":"２点目の、特養ホームの整備ですけれども、やはり一定規模の大規模な土地が必要だという形になっております。やはり都市部における土地の有効活用の面からも、やはり他の施設との複合化も含めて検討していきたいと考えております。","voiceIndex":109,"id":"exchange-049"},{"speaker":"若林委員","kind":"質問・要望","question":"ただいまの特養ホームの今後の整備、福祉部長からお答えいただきましたけれども、総合管理計画はまた全庁的な取組みということになると思います。ということは、学校改築もありますけれども、計画を策定した、こういった需要の高い、特別養護老人ホームといった高齢者の施設についての検討も速やかに行っていかなければならないと思いますけれども、企画部長のご答弁をいただきたいと思います。","respondent":"中山企画部長","answer":"さまざまな行政需要の中で、財政状況、基金の積み立て、こういうことを踏まえながら、喫緊の課題、重要な課題である、基幹となる施設の整備ということについても、しっかり区の中で全庁的に、所管とも連携をとりながら考えてまいりたいと思います。","voiceIndex":111,"id":"exchange-050"},{"speaker":"若林委員","kind":"質問・要望","question":"続きまして、高齢者の変化に対応した施策についても伺っておきたいと思います。今までは６５歳以上という高齢者、また前期・後期という分け方がありましたけれども、年齢ではなく身体と認知の面から、高齢者の姿、ありさまを、例えば身体と認知が高い、どちらか一方が高い・低い、そして身体・認知とも低い人と、こういうふうにしっかりと大きな枠組みの中で見直しを進めていっていただきたいと思います。","respondent":"榎本福祉部長","answer":"健康づくり事業等の対象となる年代層のすみ分けですとか、地域の中での介護予防事業の展開の仕方等について検討し、さらなる効果的な介護予防を展開していきたいと考えております。","voiceIndex":113,"id":"exchange-051"},{"speaker":"若林委員","kind":"質問・要望","question":"次に参ります。防災の面から、避難勧告についても１点お聞かせいただきたいと思います。９月９日の夜７時５分に、避難勧告発令等の対象区域６地区１９４世帯に初めて避難勧告が今年出されました。この段階でしっかりと検証を行っておくことが品川区住民の間に必要ではないかと思いますので、今後、この検証することについてのお考えをお聞かせください。","respondent":"藤田都市環境部長","answer":"私どものほうといたしましては、こうした説明会、情報交換会、あるいは戸別の訪問というような形での、直接対話のできるような形で、さまざまな意見をまた改めて地域の方々からいただき、それを検証し、さらなる情報発信の充実を図っていきたいと考えています。","voiceIndex":115,"id":"exchange-052"},{"speaker":"若林委員","kind":"質問・要望","question":"この地域の特徴の一つは、目黒川にかかる桜が名所となっていることであります。そこで、ゆうぽうと跡の新施設の計画が公表されるに当たりましては、まちの雰囲気が、やっぱり計画を発表することでがらりと変わりますので、早目に公表するよう働きかけていただきたいことが一つ、また冬のイルミネーションは水辺広場で終わっておりますけれども、大崎駅広場にも設置していただきたいという要望です。","respondent":"藤田都市環境部長","answer":"これにつきましても、引き続き地域の声をよく確認しながら話し合いを続けていきたいと考えています。","voiceIndex":117,"id":"exchange-053"},{"speaker":"石田（ち）委員","kind":"質問","question":"日本共産党を代表して、飯沼委員とともに総括質疑を行います。羽田新飛行ルートについてです。この計画に反対する立場で、やめるべきだという立場で質問をいたします。安倍政権は、羽田空港増便計画を発表し、２０２０年までに実施しようとしています。関心の強いところですので、改めてこの計画の目的と、どのような計画なのか、飛行ルートや飛行本数、騒音など、影響をご説明ください。","respondent":"藤田都市環境部長","answer":"羽田空港の機能強化についてですけれども、この目的ですが、国際競争力の強化、それから空港ネットワークの活用など、今後、増大が予想される国際線の需要に対応していくことが必要であるということで、この実現のために。","voiceIndex":121,"id":"exchange-054"},{"speaker":"石田（ち）委員","kind":"質問","question":"大井町で３０５メートル、そして八潮で２００メートルと、これだけの低空飛行をするということです。このように、南風時、２本の経路で品川区内を飛行します。双方向の対話を進める、こういうときだからこそ、まさに今、区として反対の意見を国に述べるときではないでしょうか。反対だ」と言うべきだと思いますけれども、いかがでしょうか。そして、区が国に対して態度を示すのはいつになるのか伺います。","respondent":"藤田都市環境部長","answer":"という段階ですので、私どものほうとしてはしっかりと国に対して、その対応、対策についてきめ細かく区民のほうにお話をしていただくというようなことが必要かと考えています。","voiceIndex":123,"id":"exchange-055"},{"speaker":"石田（ち）委員","kind":"質問","question":"これを品川区がどのように考えているかということが、今、重要なのだと思います。区は、品川上空を巨大航空機が飛ぶということをリアルに考えているのかどうか、４点伺います。１点、お祭りです。大井町駅ですから、上空３００メートル、８０デシベルで飛行機が通過すると。どうなると思うか伺います。そして２点目。そして３点目、住民も出ていってしまう。そして４点目。以上、４点伺います。","respondent":"藤田都市環境部長","answer":"個人としての指標の順位付けもありますので、その辺については一概になかなか判断できないのかなと考えています。公共施設等についても、騒音のあり方等については、しっかり国のほうにも伝えていく中で、先ほど申した方策あるいは対策というものがどういうものができるのか。","voiceIndex":125,"id":"exchange-056"},{"speaker":"石田（ち）委員","kind":"質問","question":"こういったことを踏まえてどう思うのかを伺いました。こういった時間帯に、巨大な航空機が８０デシベル以上の音を立てて迫ってくるということを、区はどう思っているのかということを伺っているのです。アパートだけでなくマンション経営や不動産などが成り立たなくなるのではないでしょうか。こういった状況も踏まえて、区はどう思うのか、改めて伺います。品川区がどんなことになるか伺いたいと思います。","respondent":"藤田都市環境部長","answer":"国のほうでは、議会から、東京国際空港における騒音対策を求める意見書というものが昨年１２月に出されておりますが、これについては真摯に受けとめてまいるというような形でお話しいただいておりますので、これらも含めて。","voiceIndex":127,"id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区内でどういう状況になるのか。改めて品川区は国に反対表明することを強く求めて、次の質問に行きたいと思います。次は認可保育園増設について伺います。区長みずからが掲げた公約、待機児ゼロを、来年４月に実現させ、ママ、パパの仕事、生活、そして子育てが成り立つよう、自治体としての責任を果たすべきと質問をいたします。今年４月、待機児ゼロにならなかった原因は何か、そして教訓は何かを伺います。","respondent":"金子子ども未来部長","answer":"これに基づいて私どもも積極的に取り組んできたわけですが、本年４月の待機児童の増加を受けまして、開設計画を前倒しして、３００人の大規模保育施設を含めまして６園の開設を進めるなど、対策を強化しています。","voiceIndex":129,"id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"質問に答えていただきたいと思います。今年、待機児ゼロにならなかった原因、そして教訓は何かお答えください。","respondent":"金子子ども未来部長","answer":"ですので、子ども・子育て計画そのものも改訂しなければなりませんけれども、開設計画をそれに先立って前倒しして、私どもとしましては、平成２６年度で６４５人の枠、また平成２７年度では７１１人の枠を確保しようとして、今、努力しています。","voiceIndex":131,"id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問","question":"原因と教訓を伺ったのですけれども、とてもわかりづらい答弁です。申請が見込みより多かったということなのではないでしょうか。そのうちの０から２歳の受入れ枠は何人か伺います。１０月現在の申請者数を教えてください。来年４月の申請者推計３,０００人は変わりがないか、伺いたいと思います。ですので、来年４月、このままの計画で待機児ゼロになるのか、そして待機児数の見通しはあるのかを伺います。","respondent":"金子子ども未来部長","answer":"それで、来年４月の状況ですけれども、先ほど申しましたとおり、平成２６年度でこれまでにない６４５人の枠の確保、また平成２７年度には７１１人の枠の確保を予定しておりますので、本年よりも待機児童の数は減少するものと見込んでおります。","voiceIndex":133,"id":"exchange-060"},{"speaker":"石田（ち）委員","kind":"質問","question":"さまざま、いろいろ頑張って、今度の待機児は減少するということでしたけれども、待機児ゼロを目標にしているのか。ここをちょっと伺いたいと思います。今年入れなかった１,１５４人、そして現時点で昨年よりも申請も増えているという現状で、どれだけの対策が必要だと考えているのか。待機児数予測をしっかり出し、それに合わせて必要な対策をとるべきと思いますけれども、いかがでしょうか。","respondent":"金子子ども未来部長","answer":"新たに人口の推計をとり直しましたので、それに基づいてこの計画を改訂していかなければならないと考えています。そういう意味で、今後の対応というのは検討している最中です。","voiceIndex":135,"id":"exchange-061"},{"speaker":"石田（ち）委員","kind":"質問","question":"待機児童はかなり減るということでしたけれども、それは来年４月に向けて待機児ゼロを目標にしているのかどうかを伺いたいと思います。それで、今回、国家戦略特区において、都市公園に保育所の設置が認められたと。まだ調査結果は出ていないでしょうか。伺います。そして、またこの調査は、来年４月待機児ゼロに向けて行われているのか伺います。","respondent":"金子子ども未来部長","answer":"公園の活用につきましては、国家戦略特区の活用で保育所を都市公園内に開設しようというふうな検討をしておりますけれども、現在、調査データをまとめているところです。しかるべき時期に、これについては明らかにしていきたいと思います。","voiceIndex":137,"id":"exchange-062"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それが今年だったのではないでしょうか。済まされない事態が今年だったのではないでしょうか。繰り返さないためにも、来年４月待機児ゼロに向けて、もっと大幅にスピードアップして増設していかなければいけないのではないのでしょうか。来年４月待機児ゼロに向けてこういった政策目標が組まれているのかどうか、もう一度伺います。来年４月に向けて緊急対策としてできると思います。いかがでしょうか。","respondent":"金子子ども未来部長","answer":"ですので、今後とも品川区の子ども・子育て計画を踏まえて、就学前の乳幼児人口の動向や入園申込み者の動向といったものを的確に把握しながら、待機児童対策を積極的に、かつ総合的に取り組んでいくという考えに変わりはございません。","voiceIndex":139,"id":"exchange-063"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"来年４月に待機児ゼロにならなければ、では入れなかったママ、パパたちはどうしたらいいのでしょうか。区長みずから掲げた公約、待機児ゼロです。ここにしっかり責任を持ってください。ママとパパはしっかり見ています。あらゆる可能性を活かし、来年４月、待機児ゼロ実現を強く求めて質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-064"},{"speaker":"飯沼委員","kind":"提案","question":"紹介します。ママです。所得が上がらないのになぜ値上げですか。保育園保育料の値上げの中止を求め質問をいたします。夫婦とも給与年収４００万円、Ｄ１０階層、子どもは０歳児１人のモデルですけれども、この表で間違いがないかどうか確認をします。そして、今回の保育料値上げは結構複雑でしたけれども、おおむね１０％の値上げ、そして多子世帯への軽減策と受けとめてよいのでしょうか。伺います。","respondent":"金子子ども未来部長","answer":"２つ目は、今回選んでいただいたケースですけれども、これは多子減額が適用にならないケースですので、今回私どもが強化したものが反映されていないということです。それから３つ目としまして、算定基礎を所得税から住民税に変更しています。","voiceIndex":143,"id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区の説明は、区の歳入に関しての問題ですけれども、文教委員会で示された資料の中に明らかに書かれています。「改正内容、おおむね１０％の保育料の引き上げを行う」。これをなぜ１０％の値上げでないとおっしゃるのか、その辺をもう一回お聞かせいただきたいと思います。これは評価していますけれども、第１子、２子の数え方はぜひ戸籍上の１子、２子にしていただきたいと思います。いかがでしょうか。","respondent":"金子子ども未来部長","answer":"ただ、これは子どもの数なので、世帯として捉えるとかなり多くの世帯がこの恩恵を受けるのではないかと考えているところですけれども、そこのデータは用意してございませんので、想定ということでご了解いただきたいと思っています。","voiceIndex":145,"id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問","question":"先ほども言いましたけれども、おおむね全ての階層で１０％の値上げになります。保護者も訴えていましたけれども、現状の保育料自体が高いという認識があるのでしょうか。別途、延長保育料も加算されるのですから、今回の値上げが家計に大きく負担を与えることを認識してほしいのですが、いかがでしょうか。値上げについて、どこで誰から意見をどのように聞いて決断されたのか教えてください。","respondent":"金子子ども未来部長","answer":"ですので、私どもとしてはいつもご説明申し上げているのが、国基準に対して何％かということで申し上げております。これが現在、５３.７％ということで、今回改定しますと５３.２％程度になるかなというふうな試算をしているところです。","voiceIndex":147,"id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問","question":"私は平成２７年度、今年初めの２３区の保育料の調査をいたしました。これをさらに上げるというのですから、私は２３区の中で飛び抜けて高い保育料になるのではないかと心配しています。２点目、国基準に比較してということですけれども、どこまで値上げをしていくつもりなのでしょうか。いかがでしょうか。増税の中で保育料値上げを、税金の二重取り、子育て支援に逆行すると考えますが、いかがでしょうか。","respondent":"金子子ども未来部長","answer":"こういった方とのバランスも考えなければならないというところで、私どもは現在、先ほど来申し上げている国基準の６０％というところを１つの目標として掲げているところです。","voiceIndex":149,"id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問・要望","question":"在宅子育ての公平と言いましたけれども、先日、区立幼稚園の保育料を上げたではないですか。不公平と言いながらどちらも上げていく。私は本当に、これはおかしいと思います。歳入のことばかりおっしゃっていますが、保護者の側に立って、区民の側に立って考えていただければ、十分、これは値上げなので、ぜひそういう認識を持っていただきたい。とても子育てに冷たい区であると思いますが、いかがでしょうか。","respondent":"金子子ども未来部長","answer":"そういった意味では、多額の経費はかけております。そういうふうな努力をしながら待機児童対策を積極的に進めていくというのが基本的な考えで、そういう意味で、保育料についても受益者の方については一定の負担をお願いするというのが基本的な立場です。","voiceIndex":151,"id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問","question":"お金の問題ですが、２０１４年の決算では納税義務者が増え、住民税は過去最大、２０億円の増収となっています。基金も７７７億円から８１５億円に大幅増です。財源は十分あります。ぜひ、この財源、区民のお金ですから、子どもは社会の宝物、これはどなたも異議、異論がないところです。年少扶養控除の見直し算定をぜひ復活させてください。よろしくお願いします。","respondent":"金子子ども未来部長","answer":"ですので、いずれこちらも解消するのかなとは思っています。そういう意味で、私どもは年少扶養控除の廃止にかわるものとして多子軽減を強化しておりますので、その辺についてはご理解いただければと考えています。","voiceIndex":153,"id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問・要望","question":"次は、元自衛隊幹部の部長級採用は撤回を、の質問をいたします。品川区は、今年４月、陸上自衛隊幕僚など務めた元幹部自衛官を、災害対策担当部長、危機管理担当部長兼務として採用いたしました。お伺いします。質問です。部長が経験してきた戦争のための訓練について、その主なものについて、いつどこでどのような訓練を行ってきたのか、できるだけ具体的に詳しくお答えいただきたいと思います。","respondent":"田村総務部長","answer":"災害派遣訓練などがあります。ご質問の、それをいつどこでというご質問ですが、３２年間、いろんなところで、全てこの活動ですので、それについてはお答えすることができません。","voiceIndex":155,"id":"exchange-071"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は、ご本人がいらっしゃるので、ぜひご本人の口からお伺いしたい。自衛隊の姿は一般の国民にはわからないので、知られざる姿をお伝えしていただきたいと思って、ぜひご本人にご答弁をお願いしたいと思いますが、いかがでしょうか。","respondent":"田村総務部長","answer":"先ほど来ご説明しているように、本会議でもご答弁しましたが、まさに採用するかどうかは区長の専権事項で、人事事項ですから、その都度、採用になった担当部長が答えるというのではなく、人事所管の責任者である総務部長が答えるという形になっております。","voiceIndex":157,"id":"exchange-072"},{"speaker":"飯沼委員","kind":"質問","question":"どういうお仕事をされていた方かというのは判断の重要なところであるのでお聞きしました。今の担当部長のお仕事の具合ではなかなかわからない。質問です。区長は自衛隊の暴走をどう受けとめていらっしゃるのでしょうか。こうした自衛隊との関係を持つことが区民にとって利益になると本当に考えているのでしょうか。伺います。","respondent":"田村総務部長","answer":"それで、災害対策担当部長兼危機管理担当部長を発令していますので、危機管理ですと、例えば具体的に事象を申し上げますと、なければ一番いいのですが、やはり不発弾の処理だとか、あるいはＳＡＲＳ、鳥インフルエンザ、エボラ出血熱あるいは大震災、大雨、ゲリラ豪雨、大雪。","voiceIndex":159,"id":"exchange-073"},{"speaker":"飯沼委員","kind":"提案","question":"私は、自衛隊と自治体との関係についてお尋ねしているのです。区長は危機感を持っていらっしゃらないのでしょうか。共産党はこれまでも防災対策を区政の最も重要な施策として取り上げ、建物の耐震化、不燃化、水害対策、救護体制の強化など、予想される災害に対し、大規模な被害にならないように、自治体が区民からの要請に応えるように求め、またさまざまな具体的提案も行ってきました。いかがでしょうか。","respondent":"田村総務部長","answer":"これもお答えしていますが、今後さらなる活躍に期待しているもので、取り消しの考えはございませんし、４年目以降につきましても引き続き配置していきたいと考えております。","voiceIndex":161,"id":"exchange-074"},{"speaker":"松永委員","kind":"質問","question":"私からは、高齢化対策について、ふるさと納税についてお伺いいたします。品川区の高齢化対策について伺います。現在、品川区の高齢者人口は約７万９,０００人であり、１００歳を超える方は１４５人、そのうち女性は１１９人と伺っております。このくるみぷらんについて、どのような対策なのか伺います。その中に、ご家族、関係者、本人に対し支援を行う取組みはありますでしょうか。あわせて説明願います。","respondent":"榎本福祉部長","answer":"特に本人への支援ということでありますと、今までは認知症の講演会ですとか、あとは介護者教室等をやってきましたけれども、今回のくるみぷらんの中では、認知症ケアパスの構築ということで。","voiceIndex":164,"id":"exchange-075"},{"speaker":"松永委員","kind":"質問","question":"このくるみぷらんの中にある認知症高齢者の徘回対策について伺いたいと思います。２０２５年には患者数はさらに増え、７００万人を超えると予測されております。品川区内の認知症高齢者の人数について伺います。認知症高齢者の方について、今までに行方不明になってしまった事例はありましたでしょうか。あったのであれば、その後、どのような対応・対策をとられたのかお伺いいたします。","respondent":"榎本福祉部長","answer":"要介護認定者のうちの大体４７％ぐらいに当たるというものです。それから、２点目の、事例とその対応ですけれども、やはり行方不明になっている事例は幾つかあります。その中で多いのが、自宅へ戻ってしまう。","voiceIndex":166,"id":"exchange-076"},{"speaker":"松永委員","kind":"質問","question":"品川区でも、認知症高齢者のケア拡充の一つに、ＳＯＳネットワーク事業が行われています。そこで、ＳＯＳネットワーク事業についてお伺いいたします。品川区では平成２４年に事業がつくられ、現在、大井地区を中心に行われておりますが、今までの大井地区の実績について伺いたいと思います。荏原地区、八潮地区、品川地区、大崎地区に関して、今後の取組み・計画についてもあわせて伺いたいと思います。","respondent":"榎本福祉部長","answer":"こういう形で進めてきておりますけれども、今のところ、他地区でも同じような形で、これをモデルに他地区でも広げたいと考えていますけれど、今のところ、また他地区での準備等には入っていないところです。","voiceIndex":168,"id":"exchange-077"},{"speaker":"松永委員","kind":"質問","question":"６５歳以上の高齢者を対象に、事前に名前や住所、写真を登録してもらい、「ふじみ野市」と番号が書かれたステッカーを無料で配付して、靴の側面等に張ってもらう対策がとられているようです。そこで質問いたします。このように早期発見の対策は必要だと思いますが、このふじみ野市が行っている取組みについて、品川区の見解をお聞かせください。品川区独自の今後の取組みについてもあわせてお伺いいたします。","respondent":"榎本福祉部長","answer":"そういった中で、区独自の取組みとしましては、今のところは、徘回高齢者につきましては、ＧＰＳ端末の徘回高齢者の探索システム等の事業をやっておりますけれども、こういうステッカースタイル等のものについては今後の検討課題とさせていただきたいと思います。","voiceIndex":170,"id":"exchange-078"},{"speaker":"松永委員","kind":"質問","question":"こうした課題は品川区のみならず全自治体にかかわることであり、区市町村との連携がとても大事になってきます。次に、ふるさと納税についてお伺いいたします。そこで、東京都の自治体の取組みはさまざまなようでありますが、品川区では平成２６年度においてふるさと納税の影響による税収減があったのか、また年々、寄附をされた方の人数についてどのように推移しているのか、あわせて伺いたいと思います。","respondent":"田村総務部長","answer":"平成２６年度、平成２７年度の増加分を推測して、あくまで予測ですが、平成２８年度については、この伸び率でいきますと、平成２８年度は３億４,０００万円、あくまで予測なので増減はもちろんあると思いますが、人数で言うと１万２９１人ということで。","voiceIndex":172,"id":"exchange-079"},{"speaker":"松永委員","kind":"質問","question":"そのことを踏まえて、次に、ワンストップ特例という新しい制度について伺いたいと思います。平成２７年４月１日以降に行った寄附から適用するもので、平成２８年度以降の住民税、都民税、区民税の税額が控除されると聞いております。そこで、品川区では現在、ふるさと納税についてどのような戦略を立てて対応しようとしているのでしょうか。","respondent":"田村総務部長","answer":"どのような戦略を立てて対応ということからちょっとお答えしたいのですが、ご存じのとおり、委員もご承知のとおり、ふるさと納税は本来、生まれ育ったふるさとや応援したい自治体に寄附できる仕組みというふうに創設されたのですが、委員もご指摘のとおり。","voiceIndex":174,"id":"exchange-080"},{"speaker":"松永委員","kind":"提案","question":"そこで最後に、ホームページ作成に当たり提案があります。例えばＡからＦまでの商品の説明や、その商品に携わった方の風景、または商品の写真、魅力等のメッセージを増やし、一目でわかるものをつくってみてはいかがでしょうか。そこで、品川区と関係している団体、商工会、法人会等に区内事業者の推薦をお願いしていただき、その商品を返礼品としてもらう方法はいかがでしょうか。","respondent":"田村総務部長","answer":"それと、先ほどのホームページについて、例えば、ただ品川縣ビールというのを載せるだけではなく、品川縣とは何なのか、あるいは日本初の酵母というのがどういう形で醸成されて、いつごろの時代に作られたというのを、スペースに限りはあるかもしれないですが。","voiceIndex":176,"id":"exchange-081"},{"speaker":"松永委員","kind":"質問","question":"ぜひよろしくお願いいたします。品川区を、魅力、活気、にぎわいのある区にしていただければと思います。そのためにも、ふるさと納税に関しては、やはり戦略が必要だと思います。東京は一見、恵まれた地域でありますが、今後、受け身の対応にならないよう、よろしくお願いいたします。これで私からの質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":178,"id":"exchange-082"},{"speaker":"あべ委員","kind":"質問","question":"初めに保育の施策についてお伺いいたします。現在、区立・私立の認可保育園は７２園、過去１０年で２０園以上も増えました。認証保育所も２２園に上ります。そこで今回は質の確保を中心にお伺いしたいと思います。区立保育園、私立保育園、認証保育所の保育士の平均経験年数、施設長の平均経験年数はそれぞれ何年でしょうか。把握していないものについてはその旨もお答えください。","respondent":"金子子ども未来部長","answer":"保育園の保育士あるいは施設長の平均経験年数ということですけれども、まず保育士の経験年数は、私立は把握しておりませんが、区立では１４.９年が平均になります。施設長の経験年数ですが、私立の経験年数で言いますと２７.２年、小規模保育が１１.２年です。","voiceIndex":180,"id":"exchange-083"},{"speaker":"あべ委員","kind":"質問・要望","question":"認証は開設前にはスタッフの経験年数、施設長の年数などを把握されていると思いますので、そのように伺っておりますので、ぜひ開設後も定期的に報告を受けるように求めますけれども、いかがでしょうか。そこで伺います。平成２６年度決算では、認証保育所の第三者評価受審費助成の対象は１７カ所となっていますが、受けていない保育園の保育内容を区はどのように評価しているのでしょうか。","respondent":"金子子ども未来部長","answer":"保育の質を中心にしたご質問だと思いますが、委員からもお話がありましたとおり、まず開設時には、どういった保育内容を実施するのかということで、保育計画であるとか、あるいは給食の設備・準備あるいは衛生管理等々、運営にかかわることの内容について全て掌握いたします。","voiceIndex":182,"id":"exchange-084"},{"speaker":"あべ委員","kind":"質問","question":"公立保育園の保育内容向上のためには、区では現場経験がある職員が指導に当たっておりますが、その対象を公立以外にも広げられるよう、スタッフの拡充を図るべきではないかと思いますが、いかがでしょうか。そしてまた私立や認証保育所に対しても、日常的に区立保育園との研修・交流を進めるとともに、保育人材育成プランに基づくような計画的な研修の対象に加えてはいかがかと思いますが、いかがでしょうか。","respondent":"金子子ども未来部長","answer":"交流等々のご提案がございましたけれども、私立あるいは認証保育所については、それ独自の保育の内容をみずから高質なレベルと称してやっている場合もありますので、なかなか相手方のほうの理由にもよるとは思いますけれども、今後。","voiceIndex":184,"id":"exchange-085"},{"speaker":"あべ委員","kind":"質問・要望","question":"区立、私立、認証と形態は違っても、子どもの育つ場の質の確保に区の責任として取り組むことを要望して、この項目の質問を終わります。次に、医療的なケアが必要な子どもたちへの保育について伺います。今、品川区には、医療的ケアの必要な就学前の子どもはおおむね何人ぐらいいるでしょうか。その子たちはどのような就学前施設に通っているのでしょうか。ご説明ください。","respondent":"榎本福祉部長","answer":"医療的ケアが必要な未就学児の人数は２０人です。その通っている就学前施設につきましては、医療型児童発達支援の都立城南分園です。それから、あと就労している場合に保育を行う施設というのは品川区内にはございません。","voiceIndex":186,"id":"exchange-086"},{"speaker":"あべ委員","kind":"質問・要望","question":"一口に医療的なケアが必要な子どもといっても、心身の状況はさまざまです。港区では今年１２月から、医療的ケアが必要な子どもへの居宅訪問型事業、保育事業をスタートいたします。品川区でも今年に入りまして、ご家族の要望を受けて、助成制度を早急に整備したことは高く評価いたします。品川区ではこの点について現在どのような検討をされているのでしょうか。今後の見通しも含めお示しください。","respondent":"金子子ども未来部長","answer":"私ども品川区では、従来から特別支援の保育については、例えば保育に欠けている、今回、保育が必要なというふうに変わりましたけれども、就労支援等の審査、それからその子が集団保育がプラスになるかどうかということを判断しながら。","voiceIndex":188,"id":"exchange-087"},{"speaker":"あべ委員","kind":"質問","question":"要は集団保育が可能かどうかというところがポイントであると思います。そうすると、外形的に判断するよりも、その一人一人の状況を判断した上で、集団保育が可能であれば、ぜひ発達に資するものとして道を開いてあげてほしいと思います。次の質問に移ります。認証保育所の保育料助成について伺います。認証保育所保育料に品川区が助成してきた目的は何でしょうか。","respondent":"金子子ども未来部長","answer":"私ども、現在、認証保育所の保育料の助成をしている理由は、実情として認証保育所のスタイルが変わってきまして、認可保育所の補完というような機能が強くなっているというところから、こちらにやむを得ず通っていらっしゃる方について保育料を助成しようと。","voiceIndex":190,"id":"exchange-088"},{"speaker":"あべ委員","kind":"意見","question":"多子減額の一方で、保育料自体は上げる方向ということですが、子ども１人のみだと値上げになる一方で、２人以上だとトータルの保育料はむしろ安くなることが多いと理解しております。これを解消し、先ほどご説明いただいた目的を果たすためにも、認証保育所の在籍児童にも多子減額を適用するか、あるいは多子減額に匹敵するだけの保育料助成を行うべきだと考えますけれども、区の見解をお聞かせください。","respondent":"金子子ども未来部長","answer":"第２子、第３子について、これが認証保育所に通っている場合には、同じように認可保育園に通っているものとして２分の１減額あるいは免除というような取扱いにしています。","voiceIndex":192,"id":"exchange-089"},{"speaker":"あべ委員","kind":"質問","question":"大変ほっといたしました。その方向を固めていただいたということで、心から高く評価いたします。さて、次に防災についての質問に移ります。ここで質問いたします。区内での過去１０年間の土砂災害の件数と主な被害をお示しください。区は平成２６年度から、土砂災害の危険がある際には避難所を開設し、対象世帯には避難勧告も出しておりますが、件数と延べ避難人数をお示しください。","respondent":"藤田都市環境部長","answer":"避難所開設の状況ですが、これまで平成２６年の台風１８号、１９号、それから本年の台風１８号の計３回、避難所を開設いたしまして、避難者については延べ１２名となっています。","voiceIndex":194,"id":"exchange-090"},{"speaker":"あべ委員","kind":"質問","question":"さまざまに被害があるということがわかりました。品川区には、今、災害の可能性のある崖がどの程度あるのでしょうか。何割ぐらいが民有地なのでしょうか。区と都の調査がどのような関係にあるのでしょうか。民有地の場合、崖による災害防止の方策や擁壁の維持管理、万が一、被害があった場合の復旧作業の責任は誰が負うことになるのでしょうか。ご説明ください。","respondent":"藤田都市環境部長","answer":"東京都が行うとしている調査、それから区との関係ですけれども、東京都のほうでは５メートル以上の崖の調査を行うということで、当初、計画を立てておりましたが、なかなかその時期の見通しが立たなかったこともございまして。","voiceIndex":196,"id":"exchange-091"},{"speaker":"あべ委員","kind":"質問・要望","question":"その際に、崖対策には工事費用の助成だけではなくて、例えばアドバイザーを派遣するとか、あるいは戸建て住宅だけではなくて集合住宅も対象にすること、そしてまた住宅の崖側の壁が堅牢であると被害防止に役立つことから、そういった壁側をＲＣ構造にする、そういった改修などについても助成の対象として検討することを求めますけれども、それぞれの区の見解をお願いいたします。","respondent":"藤田都市環境部長","answer":"都が実施する警戒区域の指定範囲、それから国のほうで補助の制度もありますので、そういったものも踏まえながら、技術的なアドバイスを行う専門家の派遣なども含めて、効果的な支援の在り方について、集合住宅等も含めて研究していきたいと考えています。","voiceIndex":198,"id":"exchange-092"},{"speaker":"あべ委員","kind":"質問・要望","question":"次に防災マニュアルについて伺います。午前中に『東京防災』という冊子の質疑がありまして、それと重ならないように一点のみお伺いしたいと思います。当事者の手元に確実に届いているかどうか、それを区が把握されているでしょうか。もちろん都のものですから、なかなか計画というのは難しいかもしれませんけれども、ぜひ区のほうで積極的に動いていただきたいという思いを込めて質問をいたします。","respondent":"曽田災害対策担当部長","answer":"しかしながら、都から区に対して音声コードつきのものが窓口対応用ということで５００冊配布されてきておりますので、これにつきましては障害者福祉課と連携して、申し出等には適切に対応していきたいと考えております。","voiceIndex":200,"id":"exchange-093"},{"speaker":"あべ委員","kind":"質問","question":"大崎駅周辺の再開発について伺いたいと思います。この９月、北品川５丁目再開発工事がようやく終了し、まち開きを行ったところです。ただ、駅に直結した大崎ニュー・シティと再開発ビルの間の橋の問題は残されたままです。質問をいたします。この橋の通行の予測、そして交通量調査を行っているかどうか。そしてまた信号の設置の予定等についてお伺いしたい。総合的な交通対策についてお伺いいたします。","respondent":"藤田都市環境部長","answer":"現状では、ガードマン等も配置していますので、その辺の在り方等についてもしっかりこの後、安全が確保できるように進めてまいりたいと考えています。","voiceIndex":202,"id":"exchange-094"},{"speaker":"あべ委員","kind":"質問・要望","question":"この件、区長もさらにリーダーシップを発揮されて早期に解決を図ることを求めます。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":206,"id":"exchange-095"},{"speaker":"藤原委員","kind":"質問・要望","question":"オリンピック・パラリンピックについてですけれども、あと５年を切りまして、まさに時宜にかなった施策を品川区として担当部、担当課、これは私はものすごく高い評価をしております。それで、来年はどのようなフェスタを考えているのか教えていただきたいのが１点。そのときには、予算がかかるのですけれども、砂のコートを設置するべきではないかと思うのですけれども、まずその３点についてお伺いします。","respondent":"安藤文化スポーツ振興部長","answer":"今、砂のお話もされましたけれども、ビーチの砂を用意しまして、本格的なビーチバレーのコートを用意して、区民に対して周知事業をやっていきたいと考えています。","voiceIndex":209,"id":"exchange-096"},{"speaker":"藤原委員","kind":"質問","question":"それで、まず１つ。区長が、子どもたちの教育ということで、英語教育、ボランティア等で、オリンピックを肌で感じてもらいたいという意味でされておりますが、オリンピック・パラリンピックが終わった後も、こういう教育等はどういうふうにしていくのかが１点。施設はどういうふうにしていくのかということが２点目。３点目がスポーツ振興。その辺をどう、区として押さえているのか教えてください。","respondent":"安藤文化スポーツ振興部長、本城教育次長、中山企画部長","answer":"この事業は、オリンピック・パラリンピックが契機となってやっていってありますが、競技が終了したからといって、すぐ全てが終了するということでもなく。英語教育の推進の観点ですが、英語教育につきましては、品川区におきましてはかねてより世界に通用する人材の育成ということで。経済動向については、その段階でものを十分、見きわめて、区としての、その時々の経済施策をやっていく。このように考えていくものです。","voiceIndex":211,"id":"exchange-097"},{"speaker":"藤原委員","kind":"質問・要望","question":"府中の大國魂神社から、５月の初めのお祭りに、いわゆるずっとあそこから品川のところまで、お水取りというのでしょうか、そういう伝統が残されている。でも、私は大切な観光資源の一つだと思っているので、その辺についてちょっとお伺いしたいのと、次は品川宿に戻らせていただきますが、各大名の下屋敷があり、維新の前夜には数多くの志士たちが往来し、その足跡を私は残してきた土地柄だと考えています。","respondent":"安藤文化スポーツ振興部長","answer":"大変、勉強不足で恐縮ですけれども、お答えになるかわかりませんが、まず第１点の品川道についてですが、委員ご指摘のとおり、府中の大國魂神社から大井に通じている道というふうに理解しています。","voiceIndex":215,"id":"exchange-098"},{"speaker":"藤原委員","kind":"質問","question":"国から、区への影響といいますか、品川区の財政についてお伺いしたいのですけれども、１兆円を超える借金をどうやって減少させていくかというのは目標の一つにあるのですけれども、どうやって返していいかといっても、手だては今のところ確実なものはないような気が私はしております。この３００兆円はどこかというと、いわゆる株高によって、株を売らないでつけていたというのでしょうか。これは驚きました。","respondent":"秋山財政課長","answer":"国の経済、それから区財政の見通しです。新しい３本の矢が出たということで、今後、この動向というかは見ていかなければいけないと思いますし、今の段階で国の経済について私どものほうから評価するというのはできないのかなとは思っております。","voiceIndex":217,"id":"exchange-099"},{"speaker":"藤原委員","kind":"質問・要望","question":"課長の答弁を伺って、安心はしておりますが、答弁でもありますよね、国の動向を注視していくと。それで、こういうことを思うと、もっとあり得ないことは、品川区は健全財政なのですよ、品川区は日本の中でもすばらしいのですよと、あまりマスコミ等に出てしまうと、今度は品川区一自治体が狙い撃ちされないかということが私は心配なのですけれども、その辺についてお伺いします。","respondent":"秋山財政課長","answer":"財政運営をしている、健全財政ということのご指摘ですけれども、その目的ですけれども、経常経費をなるべく低くして、投資的経費を使える余裕を持っていくということが、区民の諸問題に的確に対応した施策ができるですので、区民の福祉といいますか、それを最大限にするために。","voiceIndex":219,"id":"exchange-100"},{"speaker":"藤原委員","kind":"質問","question":"第９５条。次に、子育て支援という意味で、ひとり親に関してお尋ねしますが、ひとり親の貧困の連鎖です。平均が１３.３ですから、かなり悪く、しかも悪化を続けているとありました。品川区では、ひとり親に対してのさまざまな支援対策を展開していると思いますが、現状の問題点、今後の課題についてお伺いします。特に教育についてですが、学習支援が３年目になりますが、そのことも含めてお伺いします。","respondent":"金子子ども未来部長","answer":"こういったニーズを勘案しながら、来年度に向けてどういうふうに拡充していったらいいか検討してまいりたいと考えています。","voiceIndex":221,"id":"exchange-101"},{"speaker":"藤原委員","kind":"質問・要望","question":"部長、最初のは質問ではなく要望なので、その辺はよろしくお願いいたします。それで、こういう話をしていて、合っているか合っていないか、自分でもちょっと考えてしまうのですけれども、昔、こんなことがありました。私どもの会派は、所得制限はしないでほしいという考えが基本的にありました。福祉とは何ですか。とてつもないお金持ちにまでお金を助成することが本当に福祉なのでしょうかと言った。","respondent":"榎本福祉部長、金子子ども未来部長","answer":"低所得者については軽減措置が行われるという形で、そういうものがいろいろ保険制度、それからいろんな福祉の諸制度、それから医療制度等にも取り入れられてきておりますので。そういう意味で、私どもの所管は子育て支援ということですので、福祉の側面と、そうでない子育て全般の支援の側面と、両方の性格を持つものですので、なかなか一つ割り切った答えを出すのは難しいと思いますけれども。","voiceIndex":225,"id":"exchange-102"},{"speaker":"藤原委員","kind":"質問・要望","question":"もう時間も来ましたので、いろんな意味で、高額所得者の方からは累進課税でというのもあると思うのですけれど、私はこれからやはり富の再配分ということを念頭に入れていろいろな要望と質問をしていきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":228,"id":"exchange-103"},{"speaker":"吉田委員","kind":"質問・要望","question":"質問は大きく分けて３点行います。自治体には、障害者に対する合理的配慮など、具体的な施策が求められております。４年間、それぞれの事業の対象者、登録者、利用者の数、そして利用の総数をお伺いします。お願いいたします。それを考えますためにも、これまでの事業評価がどうであったか伺いたいと思います。これについては評価ですので、２０１２年から３年間、１４年までの評価を伺いたいと思います。","respondent":"榎本福祉部長","answer":"今現在、今年度の登録者は８名です。それから、評価ですけれども、やはり重症心身障害者通所事業につきましては、本体の事業ということで、生活介護のほうの５名の定員枠というのを持っていますので、それを中心に事業を進めているところです。","voiceIndex":230,"id":"exchange-104"},{"speaker":"吉田委員","kind":"質問","question":"同じような数字の考え方で対象者の把握というのは無理なのでしょうか。それから、２０１３年４名と２０１４年２名については、利用の総数というふうに考えてよろしいのでしょうか。もしかすると１人の方がそれぞれ４回、２回、利用されたと理解してよろしいのでしょうか。お答えをお願いします。","respondent":"榎本福祉部長","answer":"対象者のほうですけれども、今現在、城南特別支援学校へ通っている方の中での対象といいますと、重心の方は９名、それから未就学は１０名という形です。医療対応が必要なお子さんという形です。","voiceIndex":232,"id":"exchange-105"},{"speaker":"吉田委員","kind":"質問・要望","question":"数字の確認はわかりました。ありがとうございました。それで、さっき事業評価、明確なお答えがなかったようなのですが、品川区の姿勢もそういうものであると理解してよろしいのでしょうか。この受入れ体制が整わないということについては、今後、どういう改善が考えられるかお答えをお願いいたします。","respondent":"榎本福祉部長","answer":"やはり通所者の医療的ケアが年々重たくはなっていますけれども、その部分につきましては、どういう形で見直しをかけていくのかということは検討に入っていきたいと考えております。","voiceIndex":234,"id":"exchange-106"},{"speaker":"吉田委員","kind":"質問・要望","question":"事情は伺いましたので理解しておりますが、やはり契約の在り方としては望ましくないのではないかと考えます。次の展開を検討するときには、きちんと契約内容と事業実態が合うものにしていただきたいと、これは要望にとどめします。障害者当事者が実際に差別に遭ったり、そういうときに相談したり、トラブルがあったときに相談できる体制づくりが必要だと思いますが、その点について伺いたいと思います。","respondent":"榎本福祉部長","answer":"あと地域協議会についてですけれども、地域協議会の部分というのは単独でつくるのではなくて、逆にいくと、今、自立支援協議会という形で障害者関連団体も入れた協議会を持っているのですけれども、そちらの中で。","voiceIndex":236,"id":"exchange-107"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは要望にしておきます。それから地域協議会についてですが、自立支援協議会がその役割を担うということでしたけれども、そうしますと、やっぱり自立支援協議会がそのままなるということなのでしょうか。それから、もう一つ、トラブル、差別があったときの相談体制についてさっき伺ったのですけれど、それについてお答えをお願いいたします。","respondent":"榎本福祉部長","answer":"それで、協議会の部分ですけれども、全体の自立支援協議会につきましては年数回という形で進めていますけれども、実際には専門部会を５つ置きまして、その中で個別な課題についてそれぞれやっているところです。","voiceIndex":238,"id":"exchange-108"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり今の自立支援協議会の場合は、区民の参加というと、公募区民の方がお１人と理解しております。そういうもののことについて伺いたいと思います。それから、自立支援協議会が今後、地域協議会の役割も担っていくようになるのかなと思いますが、その場合はやはり会議の公開ということも必要ではないかと思いますが、その辺についてもご見解を伺いたいと思います。","respondent":"榎本福祉部長","answer":"今までは情報交換的な役割だったのですけれども、そういうことで公開はしていなかったわけですけれども、今後についてはどういう形でこれが進められるかというものを含めまして、検討課題にさせていただきたいと考えています。","voiceIndex":240,"id":"exchange-109"},{"speaker":"吉田委員","kind":"質問・要望","question":"これまで、「障害者当事者のご意見をどのように取り入れているのでしょうか」という問いに対して、「障害者７団体の代表の方に協議会に参加していただいて」というようなご答弁が多かったように思います。今後、どのようにして改善していく方針か伺います。それで、これに答えていただく前段として、品川区において障害者７団体の位置付けといいますか、そういうものがどういうものなのか伺いたいと思います。","respondent":"榎本福祉部長","answer":"それで、そういう団体についての意見も聞きますし、それからいろんな、例えば障害者の福祉計画をつくるときには、区民の当事者の方も入っていただきましたので、そういう形での当事者の意見も入れていきたいと考えています。","voiceIndex":242,"id":"exchange-110"},{"speaker":"吉田委員","kind":"質問・要望","question":"これからも、医療が発達すると、今までわからなかった障害とか、そういうものが出てくる可能性もあります。次に、品川区の配偶者暴力対策基本計画改訂版に基づく品川区の施策について伺いたいと思います。これからどのように意識啓発をしていく予定か、研修などはどう考えているのか、また、意識啓発だけでなく、具体的にどのようにして情報漏洩などを防ぐようになっているのか伺いたいと思います。","respondent":"田村総務部長","answer":"それ以外にも、毎年、東京都のウィメンズプラザで実施されるＤＶ被害者支援のための基礎知識研修ということで、広く職員を参加させ、全庁的な意識の底上げを図る取組みを実施していくという考えではあります。","voiceIndex":244,"id":"exchange-111"},{"speaker":"吉田委員","kind":"質問","question":"研修はわかりましたけれども、１点、具体的な情報漏洩について伺っていますので、お答えください。それが危機管理ではないでしょうか。危機管理としてヒューマンエラーなどによる情報漏洩が起きたときの対策は考えていらっしゃるでしょうか。そのほかにどういうものが実施され、また計画されているのか、それから近隣の方たちのＤＶの早期発見につながるような成果があったのか、伺いたいと思います。","respondent":"堀越地域振興部長、田村総務部長","answer":"情報漏洩の防止です。配偶者暴力の被害者の方が加害者に住所を知られることのないように、区では住民票等の閲覧、それから交付の請求を制限する対応をしています。具体的には閲覧の拒否、それから不交付という対応になります。それで、区民への啓発ということですと、ＤＶ啓発講座ということで、実際には今年度も来年の２月７日に、ＤＶを知ってＤＶをなくそうということで、ＤＶを被害者支援している講師を招いて講座を開催する予定です。","voiceIndex":246,"id":"exchange-112"},{"speaker":"吉田委員","kind":"質問・要望","question":"研修とともに、ぜひ有効にそれが活きるような、それから、その相談を受けられるような体制をお願いしたいと思います。最後に、対応窓口の職員の安全確保について伺いたいと思います。ＤＶ被害者が手続や相談に来庁した際、ＤＶ加害者も近くにいるということを想定する必要があります。その点について、どのような意識づけ、また具体策が考えられているのか、その辺を伺いたいと思います。","respondent":"田村総務部長","answer":"あるいは他の来庁者から見えない相談スペースで対応するという具体的な施策ですし、生活福祉課については、やはり防犯カメラだとか緊急コールもありますし、警察のＯＢもいるので対応しているということで、全庁的には不当行為等対応マニュアルというものがございまして。","voiceIndex":249,"id":"exchange-113"},{"speaker":"吉田委員","kind":"質問・要望","question":"ＤＶに関しましては、本当にすぐ、何かのミスがその方の命にかかわる問題です。職員の安全ということもありますので、ぜひ全庁的に意識を高めて対応していただきたいと思います。以上で質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":251,"id":"exchange-114"},{"speaker":"渡辺委員","kind":"提案","question":"今回、品川区議会自民党・子ども未来所属議員が本決算特別委員会において質問、指摘、提案した、ロタウイルスワクチン接種費用助成、市町村交流の拡充、防災・初期消火対応の充実、シティプロモーション、在宅子育て支援と保育環境の向上、水辺の利活用と都市型観光の進展、商店街振興施策等は、区民等から幅広く意見聴取を行い提案したものであり。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":254,"id":"exchange-115"},{"speaker":"たけうち委員","kind":"提案","question":"最後に、本決算特別委員会にて我が会派の委員が提案、要望したオリンピック・パラリンピック開催に向けた品川の魅力発信、受動喫煙防止の分煙体制や公衆便所の整備、がん対策・がん教育、心身の健康づくりの充実、ロタウイルスワクチン接種費助成、１８歳選挙権を踏まえた主権者教育やネウボラネットワークの充実、子どもの貧困対策、教育環境の整備などに対する意見を来年度の予算編成をはじめ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":256,"id":"exchange-116"},{"speaker":"南副委員長","kind":"質問・要望","question":"立憲主義に反する戦争法案に反対を、と求めると、「見解を述べるのを差し控えたい」と答弁し、憲法遵守すら表明しませんでした。都市公園内に保育園をつくるなども含めて、区長公約の待機児ゼロを来年４月に実現させるために、認可保育園２０園以上の増設を求めます。大崎図書館は現在地での改修・建替えを求めます。必要性も住民の要請もない道路を、第４次事業化計画の優先整備路線にしないことを求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":258,"id":"exchange-117"},{"speaker":"あべ委員","kind":"提案","question":"本決算特別委員会における款別審査や総括質疑での我が会派の指摘や提案が、次年度予算をはじめ今後の本区の施策に反映されるよう強く要望するとともに、東京オリンピック・パラリンピック以降を見据え、区民一人一人が安全に、そして安心して住み続けることができる長期的・総合的なまちづくりの推進を要望して、民主党・無所属クラブの意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":260,"id":"exchange-118"},{"speaker":"須貝委員","kind":"質問・要望","question":"平成２６年度決算に対する維新・無所属品川の意見表明をいたします。国でも、貧困から子どもを守るために、貧困の連鎖を断ち切る事業を推し進めています。防災対策や医療、介護、子育ての予算は年々上昇し、財政負担も増え続けると思いますが、このような好業績、３７億円の黒字等の決算があるならば、その一部を低所得者層への支援を拡充していただきたい。以上で、維新・無所属品川の意見表明といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":262,"id":"exchange-119"},{"speaker":"田中委員","kind":"提案","question":"品川・生活者ネットワークは、意見と要望を以下に述べ、２０１４年度品川区一般会計および国民健康保険事業会計、後期高齢者医療特別会計、介護保険特別会計の各歳入歳出決算の認定に対し賛成いたします。情報共有と連携で、貧困の連鎖を断ち切る事業展開を求めます。各款別審査で生活者ネットワークが指摘・提案させていただいた意見を予算編成に活かしていただくことを要望し、最後に一言申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":264,"id":"exchange-120"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1416#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":119091,"voices":269}}]);
